#[derive(Debug)]
struct ChooseBufferSession {
    source_pane: PaneId,
    source_session: SessionId,
    filter: Option<String>,
    format: Option<String>,
    kill_source: bool,
    sort: TmuxSort,
    key_format: Option<String>,
    template: Option<String>,
    names: Vec<String>,
    selected: Option<String>,
    search: Option<ChooseBufferSearchState>,
    last_search: Option<ChooseBufferSearchState>,
    rendered: ChooseBufferState,
}

impl ChooseBufferSession {
    fn new(
        source_pane: PaneId,
        engine: &MuxEngine,
        buffers: &[PasteBuffer],
        attached_session: Option<SessionId>,
        facts: &FormatHookFacts,
        filter: Option<String>,
        format: Option<String>,
        kill_source: bool,
        sort: TmuxSort,
        key_format: Option<String>,
    ) -> Result<Option<Self>, ServerError> {
        let source_window = engine
            .state
            .window_for_pane(source_pane)
            .ok_or_else(|| ServerError::MissingTarget(source_pane.to_string()))?;
        let source_session = engine.state.windows[&source_window].session;
        if buffers.is_empty() {
            return Ok(None);
        }
        let mut chooser = Self {
            source_pane,
            source_session,
            filter,
            format,
            kill_source,
            sort,
            key_format,
            template: None,
            names: Vec::new(),
            selected: None,
            search: None,
            last_search: None,
            rendered: ChooseBufferState {
                items: Vec::new(),
                search: None,
                selected: 0,
                filter_no_matches: false,
            },
        };
        chooser.rebuild(engine, buffers, attached_session, facts);
        Ok(Some(chooser))
    }

    fn rebuild(
        &mut self,
        engine: &MuxEngine,
        buffers: &[PasteBuffer],
        attached_session: Option<SessionId>,
        facts: &FormatHookFacts,
    ) {
        self.names.clear();
        let source_context = ExecutionContext::for_pane(&engine.state, self.source_pane);
        let mut sorted = buffers.iter().collect::<Vec<_>>();
        self.sort.apply(&mut sorted, |left, right| {
            let ordering = match self.sort.order() {
                Some(TmuxSortOrder::Creation) => right.created.cmp(&left.created),
                Some(TmuxSortOrder::Name) => left.name.cmp(&right.name),
                Some(TmuxSortOrder::Size) => left.data.len().cmp(&right.data.len()),
                _ => std::cmp::Ordering::Equal,
            };
            ordering.then_with(|| left.name.cmp(&right.name))
        });
        let filtered = |apply_filter: bool| {
            sorted
                .iter()
                .copied()
                .filter(|buffer| {
                    if !apply_filter {
                        return true;
                    }
                    let (Some(filter), Some(source_context)) =
                        (self.filter.as_deref(), source_context.as_ref())
                    else {
                        return true;
                    };
                    let row_facts = FormatHookFacts {
                        buffer: Some(buffer_format_facts(buffer)),
                        ..facts.clone()
                    };
                    let mut hooks = DaemonFormatHooks::command(&row_facts);
                    format_true(&engine.expand_pane_format(
                        filter,
                        source_context,
                        attached_session,
                        FormatClient::NoClient,
                        &mut hooks,
                    ))
                })
                .collect::<Vec<_>>()
        };
        let mut visible = filtered(self.filter.is_some());
        let filter_no_matches = visible.is_empty() && self.filter.is_some();
        if filter_no_matches {
            visible = filtered(false);
        }
        let mut items = Vec::with_capacity(visible.len().min(MAX_CHOOSE_BUFFER_ITEMS));
        for (line, buffer) in visible
            .into_iter()
            .take(MAX_CHOOSE_BUFFER_ITEMS)
            .enumerate()
        {
            self.names.push(buffer.name.clone());
            let key = match (self.key_format.as_deref(), source_context.as_ref()) {
                (None, _) => default_chooser_row_key(line),
                (Some(format), Some(source_context)) => {
                    let row_facts = FormatHookFacts {
                        buffer: Some(buffer_format_facts(buffer)),
                        ..facts.clone()
                    };
                    let variables = chooser_row_variables(line);
                    let mut hooks =
                        DaemonFormatHooks::command_with_variables(&row_facts, &variables);
                    parsed_chooser_row_key(&engine.expand_pane_format(
                        format,
                        source_context,
                        attached_session,
                        FormatClient::NoClient,
                        &mut hooks,
                    ))
                }
                (Some(_), None) => String::new(),
            };
            let text = match (self.format.as_deref(), source_context.as_ref()) {
                (None, _) | (Some(_), None) => String::new(),
                (Some(format), Some(source_context)) => {
                    let row_facts = FormatHookFacts {
                        buffer: Some(buffer_format_facts(buffer)),
                        ..facts.clone()
                    };
                    let mut hooks = DaemonFormatHooks::command(&row_facts);
                    bounded_choose_item_text(&engine.expand_pane_format(
                        format,
                        source_context,
                        attached_session,
                        FormatClient::NoClient,
                        &mut hooks,
                    ))
                }
            };
            items.push(ChooseBufferItem {
                name: bounded_choose_buffer_name(&buffer.name),
                preview: bounded_choose_buffer_preview(&buffer.data),
                size_bytes: u64::try_from(buffer.data.len()).unwrap_or(u64::MAX),
                created_unix_seconds: buffer
                    .created
                    .duration_since(UNIX_EPOCH)
                    .unwrap_or_default()
                    .as_secs(),
                key,
                text,
            });
        }
        let previous_index = usize::try_from(self.rendered.selected).unwrap_or(usize::MAX);
        let selected = self
            .selected
            .as_ref()
            .and_then(|name| self.names.iter().position(|candidate| candidate == name))
            .unwrap_or(previous_index)
            .min(items.len().saturating_sub(1));
        self.selected = self.names.get(selected).cloned();
        self.rendered = ChooseBufferState {
            items,
            search: self.search.clone(),
            selected: u32::try_from(selected).unwrap_or(u32::MAX),
            filter_no_matches,
        };
    }

    fn apply(
        &mut self,
        action: ChooseBufferAction,
        buffers: &[PasteBuffer],
    ) -> Result<ChooseBufferResult, ServerError> {
        let len = self.rendered.items.len();
        if len == 0 {
            return Ok(ChooseBufferResult::Close);
        }
        let current = usize::try_from(self.rendered.selected)
            .unwrap_or(usize::MAX)
            .min(len - 1);
        match action {
            ChooseBufferAction::Previous => self.select_index(current.saturating_sub(1)),
            ChooseBufferAction::Next => self.select_index((current + 1).min(len - 1)),
            ChooseBufferAction::PagePrevious => {
                self.select_index(current.saturating_sub(CHOOSE_BUFFER_PAGE_ROWS));
            }
            ChooseBufferAction::PageNext => {
                self.select_index(current.saturating_add(CHOOSE_BUFFER_PAGE_ROWS).min(len - 1));
            }
            ChooseBufferAction::First => self.select_index(0),
            ChooseBufferAction::Last => self.select_index(len - 1),
            ChooseBufferAction::Select(index) => {
                self.select_index(usize::try_from(index).unwrap_or(usize::MAX));
            }
            ChooseBufferAction::PasteIndex(index) => {
                self.select_index(usize::try_from(index).unwrap_or(usize::MAX));
                return Ok(self
                    .selected
                    .clone()
                    .map_or(ChooseBufferResult::Updated, ChooseBufferResult::Paste));
            }
            ChooseBufferAction::Paste => {
                return Ok(self
                    .selected
                    .clone()
                    .map_or(ChooseBufferResult::Updated, ChooseBufferResult::Paste));
            }
            ChooseBufferAction::Delete => {
                return Ok(self
                    .selected
                    .clone()
                    .map_or(ChooseBufferResult::Updated, ChooseBufferResult::Delete));
            }
            ChooseBufferAction::SearchStart { reverse } => {
                self.search = Some(ChooseBufferSearchState {
                    query: String::new(),
                    reverse,
                });
                self.rendered.search.clone_from(&self.search);
            }
            ChooseBufferAction::SearchAppend(text) => {
                let Some(search) = self.search.as_mut() else {
                    return Ok(ChooseBufferResult::Updated);
                };
                if search.query.len().saturating_add(text.len()) > MAX_CHOOSE_BUFFER_QUERY_BYTES {
                    return Err(ServerError::InvalidCommand(format!(
                        "choose-buffer search exceeds {MAX_CHOOSE_BUFFER_QUERY_BYTES} bytes"
                    )));
                }
                search.query.push_str(&text);
                let search = search.clone();
                self.rendered.search = Some(search.clone());
                self.select_search_match(buffers, &search.query, search.reverse, true);
            }
            ChooseBufferAction::SearchBackspace => {
                let Some(search) = self.search.as_mut() else {
                    return Ok(ChooseBufferResult::Updated);
                };
                search.query.pop();
                let search = search.clone();
                self.rendered.search = Some(search.clone());
                self.select_search_match(buffers, &search.query, search.reverse, true);
            }
            ChooseBufferAction::SearchAccept => {
                if let Some(search) = self.search.take()
                    && !search.query.is_empty()
                {
                    self.last_search = Some(search);
                }
                self.rendered.search = None;
            }
            ChooseBufferAction::SearchCancel => {
                self.search = None;
                self.rendered.search = None;
            }
            ChooseBufferAction::SearchNext { reverse } => {
                if let Some(search) = self.last_search.clone() {
                    self.select_search_match(
                        buffers,
                        &search.query,
                        search.reverse ^ reverse,
                        false,
                    );
                }
            }
            ChooseBufferAction::Close => return Ok(ChooseBufferResult::Close),
            ChooseBufferAction::Key(_) => {}
        }
        Ok(ChooseBufferResult::Updated)
    }

    fn select_index(&mut self, index: usize) {
        let index = index.min(self.names.len().saturating_sub(1));
        self.rendered.selected = u32::try_from(index).unwrap_or(u32::MAX);
        self.selected = self.names.get(index).cloned();
    }

    fn select_search_match(
        &mut self,
        buffers: &[PasteBuffer],
        query: &str,
        reverse: bool,
        include_current: bool,
    ) {
        if query.is_empty() || self.names.is_empty() {
            return;
        }
        let len = self.names.len();
        let current = usize::try_from(self.rendered.selected)
            .unwrap_or(usize::MAX)
            .min(len - 1);
        let start = usize::from(!include_current);
        for offset in start..start.saturating_add(len) {
            let index = if reverse {
                (current + len - (offset % len)) % len
            } else {
                (current + offset) % len
            };
            let name = &self.names[index];
            let Some(buffer) = buffers.iter().find(|buffer| &buffer.name == name) else {
                continue;
            };
            if contains_buffer_query(buffer.name.as_bytes(), query)
                || contains_buffer_query(&buffer.data, query)
            {
                self.select_index(index);
                return;
            }
        }
    }
}

fn contains_buffer_query(haystack: &[u8], query: &str) -> bool {
    let needle = query.as_bytes();
    if !needle.is_empty()
        && haystack
            .windows(needle.len())
            .any(|candidate| candidate == needle)
    {
        return true;
    }
    !needle.is_empty()
        && needle.is_ascii()
        && haystack
            .windows(needle.len())
            .any(|candidate| candidate.eq_ignore_ascii_case(needle))
}

fn bounded_choose_item_text(text: &str) -> String {
    let mut bounded = String::with_capacity(text.len().min(MAX_CHOOSE_ITEM_TEXT_BYTES));
    for character in text.chars() {
        if bounded.len() + character.len_utf8() > MAX_CHOOSE_ITEM_TEXT_BYTES {
            break;
        }
        bounded.push(character);
    }
    bounded
}

fn bounded_choose_buffer_name(name: &str) -> String {
    if name.len() <= MAX_CHOOSE_BUFFER_NAME_BYTES {
        return name.to_owned();
    }
    let mut end = MAX_CHOOSE_BUFFER_NAME_BYTES.saturating_sub('…'.len_utf8());
    while !name.is_char_boundary(end) {
        end -= 1;
    }
    format!("{}…", &name[..end])
}

fn bounded_choose_buffer_preview(data: &[u8]) -> String {
    let mut preview = String::with_capacity(MAX_CHOOSE_BUFFER_PREVIEW_BYTES);
    let prefix_len = data.len().min(MAX_CHOOSE_BUFFER_PREVIEW_BYTES);
    let sample = String::from_utf8_lossy(&data[..prefix_len]);
    let mut truncated = prefix_len < data.len();
    for character in sample.chars() {
        let mut encoded = [0; 4];
        let fragment = match character {
            '\n' => " ⏎ ",
            '\r' => "",
            '\t' => " ⇥ ",
            character if character.is_control() => "�",
            character => character.encode_utf8(&mut encoded),
        };
        if preview.len().saturating_add(fragment.len())
            > MAX_CHOOSE_BUFFER_PREVIEW_BYTES.saturating_sub('…'.len_utf8())
        {
            truncated = true;
            break;
        }
        preview.push_str(fragment);
    }
    if truncated {
        preview.push('…');
    }
    preview
}

fn choose_tree_command_target(
    engine: &MuxEngine,
    target: ChooseTreeTarget,
) -> Result<String, ServerError> {
    match target {
        ChooseTreeTarget::Session(session) => {
            let session = engine
                .state
                .sessions
                .get(&session)
                .ok_or_else(|| ServerError::MissingTarget(session.to_string()))?;
            Ok(format!("={}:", session.name))
        }
        ChooseTreeTarget::Window(window) => {
            let window_state = engine
                .state
                .windows
                .get(&window)
                .ok_or_else(|| ServerError::MissingTarget(window.to_string()))?;
            let session = engine
                .state
                .sessions
                .get(&window_state.session)
                .ok_or_else(|| ServerError::MissingTarget(window_state.session.to_string()))?;
            Ok(format!("={}:{}.", session.name, window_state.index))
        }
        ChooseTreeTarget::Pane(pane) => {
            let window = engine
                .state
                .window_for_pane(pane)
                .ok_or_else(|| ServerError::MissingTarget(pane.to_string()))?;
            let window_state = engine
                .state
                .windows
                .get(&window)
                .ok_or_else(|| ServerError::MissingTarget(window.to_string()))?;
            let session = engine
                .state
                .sessions
                .get(&window_state.session)
                .ok_or_else(|| ServerError::MissingTarget(window_state.session.to_string()))?;
            Ok(format!("={}:{}.{}", session.name, window_state.index, pane))
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum ChooseTreeResult {
    Updated(ChooseTreeUpdateKind),
    Close,
    Activate(ChooseTreeTarget),
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum ChooseTreeUpdateKind {
    Delta,
    Full,
}

#[derive(Debug)]
struct ChooseTreeSession {
    source_pane: PaneId,
    source_session: SessionId,
    kind: ChooseTreeKind,
    sessions_only: bool,
    filter: Option<String>,
    format: Option<String>,
    hide_source: bool,
    kill_source: bool,
    sort: TmuxSort,
    key_format: Option<String>,
    template: Option<String>,
    expanded_sessions: BTreeSet<SessionId>,
    expanded_windows: BTreeSet<zz_protocol::WindowId>,
    selected: Option<ChooseTreeTarget>,
    search: Option<ChooseTreeSearchState>,
    last_search: Option<ChooseTreeSearchState>,
    rendered: ChooseTreeState,
}

impl ChooseTreeSession {
    fn new(
        kind: ChooseTreeKind,
        sessions_only: bool,
        source_pane: PaneId,
        engine: &MuxEngine,
        attached_session: Option<SessionId>,
        facts: &FormatHookFacts,
        filter: Option<String>,
        format: Option<String>,
        hide_source: bool,
        kill_source: bool,
        sort: TmuxSort,
        key_format: Option<String>,
    ) -> Result<Self, ServerError> {
        let source_window = engine
            .state
            .window_for_pane(source_pane)
            .ok_or_else(|| ServerError::MissingTarget(source_pane.to_string()))?;
        let source_session = engine.state.windows[&source_window].session;
        let expanded_sessions = if sessions_only {
            BTreeSet::new()
        } else {
            engine.state.sessions.keys().copied().collect()
        };
        let expanded_windows = if kind == ChooseTreeKind::Panes {
            engine.state.windows.keys().copied().collect()
        } else {
            BTreeSet::new()
        };
        let selected = Some(if sessions_only {
            ChooseTreeTarget::Session(source_session)
        } else {
            match kind {
                ChooseTreeKind::Windows => ChooseTreeTarget::Window(source_window),
                ChooseTreeKind::Panes if engine.state.windows[&source_window].panes.len() == 1 => {
                    ChooseTreeTarget::Window(source_window)
                }
                ChooseTreeKind::Panes => ChooseTreeTarget::Pane(source_pane),
            }
        });
        let mut chooser = Self {
            source_pane,
            source_session,
            kind,
            sessions_only,
            filter,
            format,
            hide_source,
            kill_source,
            sort,
            key_format,
            template: None,
            expanded_sessions,
            expanded_windows,
            selected,
            search: None,
            last_search: None,
            rendered: ChooseTreeState {
                items: Vec::new(),
                search: None,
                selected: 0,
                kind,
                filter_no_matches: false,
            },
        };
        chooser.rebuild(engine, attached_session, facts);
        Ok(chooser)
    }

    fn branches(
        &self,
        engine: &MuxEngine,
        attached_session: Option<SessionId>,
        facts: &FormatHookFacts,
        apply_filter: bool,
    ) -> Vec<(SessionId, Vec<(WindowId, Vec<PaneId>)>)> {
        let state = &engine.state;
        let mut sessions = state
            .sessions_by_name()
            .into_iter()
            .map(|session| session.id)
            .collect::<Vec<_>>();
        self.sort.apply(&mut sessions, |left, right| {
            let left = &state.sessions[left];
            let right = &state.sessions[right];
            let ordering = match self.sort.order() {
                Some(TmuxSortOrder::Activity) => right.sort_activity.cmp(&left.sort_activity),
                Some(TmuxSortOrder::Creation) => left.sort_created.cmp(&right.sort_created),
                Some(TmuxSortOrder::Index) => left.id.cmp(&right.id),
                Some(TmuxSortOrder::Name) => left.name.cmp(&right.name),
                _ => std::cmp::Ordering::Equal,
            };
            ordering.then_with(|| left.name.cmp(&right.name))
        });

        let mut branches = Vec::new();
        for session_id in sessions {
            let Some(session) = state.sessions.get(&session_id) else {
                continue;
            };
            let mut windows = session
                .windows
                .iter()
                .copied()
                .filter(|window| state.windows.contains_key(window))
                .collect::<Vec<_>>();
            self.sort.apply(&mut windows, |left, right| {
                let left = &state.windows[left];
                let right = &state.windows[right];
                let ordering = match self.sort.order() {
                    Some(TmuxSortOrder::Activity) => right.activity.cmp(&left.activity),
                    Some(TmuxSortOrder::Creation) => left.created.cmp(&right.created),
                    Some(TmuxSortOrder::Index) => left.index.cmp(&right.index),
                    Some(TmuxSortOrder::Name) => left.name.cmp(&right.name),
                    Some(TmuxSortOrder::Size) => {
                        let left_extent = (
                            engine
                                .window_extent(left.id, zz_protocol::Axis::Horizontal)
                                .unwrap_or_default(),
                            engine
                                .window_extent(left.id, zz_protocol::Axis::Vertical)
                                .unwrap_or_default(),
                        );
                        let right_extent = (
                            engine
                                .window_extent(right.id, zz_protocol::Axis::Horizontal)
                                .unwrap_or_default(),
                            engine
                                .window_extent(right.id, zz_protocol::Axis::Vertical)
                                .unwrap_or_default(),
                        );
                        (u32::from(left_extent.0) * u32::from(left_extent.1))
                            .cmp(&(u32::from(right_extent.0) * u32::from(right_extent.1)))
                    }
                    _ => std::cmp::Ordering::Equal,
                };
                ordering.then_with(|| left.name.cmp(&right.name))
            });

            let mut visible_windows = Vec::new();
            for window_id in windows {
                let window = &state.windows[&window_id];
                let mut panes = window.pane_order().to_vec();
                self.sort.apply(&mut panes, |left, right| {
                    let left_pane = &window.panes[left];
                    let right_pane = &window.panes[right];
                    let left_index = window
                        .pane_order()
                        .iter()
                        .position(|pane| pane == left)
                        .unwrap_or_default();
                    let right_index = window
                        .pane_order()
                        .iter()
                        .position(|pane| pane == right)
                        .unwrap_or_default();
                    let ordering = match self.sort.order() {
                        Some(TmuxSortOrder::Activity) => {
                            left_pane.active_point.cmp(&right_pane.active_point)
                        }
                        Some(TmuxSortOrder::Creation) => left.cmp(right),
                        Some(TmuxSortOrder::Index) => left_index.cmp(&right_index),
                        Some(TmuxSortOrder::Name) => left_pane.title.cmp(&right_pane.title),
                        Some(TmuxSortOrder::Size) => {
                            let left_extent =
                                window.displayed_pane_geometry(*left).unwrap_or_default();
                            let right_extent =
                                window.displayed_pane_geometry(*right).unwrap_or_default();
                            (u32::from(left_extent.0) * u32::from(left_extent.1))
                                .cmp(&(u32::from(right_extent.0) * u32::from(right_extent.1)))
                        }
                        _ => std::cmp::Ordering::Equal,
                    };
                    ordering.then_with(|| left_pane.title.cmp(&right_pane.title))
                });
                if apply_filter {
                    panes.retain(|pane| {
                        let (Some(filter), Some(target)) = (
                            self.filter.as_deref(),
                            ExecutionContext::for_pane(state, *pane),
                        ) else {
                            return true;
                        };
                        let mut hooks = DaemonFormatHooks::command(facts);
                        format_true(&engine.expand_pane_format(
                            filter,
                            &target,
                            attached_session,
                            FormatClient::NoClient,
                            &mut hooks,
                        ))
                    });
                }
                let window_visible = !apply_filter || !panes.is_empty();
                if self.hide_source {
                    panes.retain(|pane| *pane != self.source_pane);
                }
                if window_visible {
                    visible_windows.push((window_id, panes));
                }
            }
            if !apply_filter || !visible_windows.is_empty() {
                branches.push((session_id, visible_windows));
            }
        }
        branches
    }

    /// A `-K` format expands in the row's own context, the way
    /// `window_tree_get_key` seeds `format_defaults` from the item type before
    /// expanding `data->key_format`.
    fn assign_row_keys(
        &self,
        items: &mut [ChooseTreeItem],
        engine: &MuxEngine,
        attached_session: Option<SessionId>,
        facts: &FormatHookFacts,
    ) {
        let Some(format) = self.key_format.as_deref() else {
            for (line, item) in items.iter_mut().enumerate() {
                item.key = default_chooser_row_key(line);
            }
            return;
        };
        for (line, item) in items.iter_mut().enumerate() {
            let context = match item.target {
                ChooseTreeTarget::Session(session) => {
                    Some(ExecutionContext::new(Some(session), None, None))
                }
                ChooseTreeTarget::Window(window) => engine
                    .state
                    .windows
                    .get(&window)
                    .map(|entry| ExecutionContext::new(Some(entry.session), Some(window), None)),
                ChooseTreeTarget::Pane(pane) => ExecutionContext::for_pane(&engine.state, pane),
            };
            item.key = context.map_or_else(String::new, |context| {
                let variables = chooser_row_variables(line);
                let mut hooks = DaemonFormatHooks::command_with_variables(facts, &variables);
                parsed_chooser_row_key(&engine.expand_pane_format(
                    format,
                    &context,
                    attached_session,
                    FormatClient::NoClient,
                    &mut hooks,
                ))
            });
        }
    }

    fn assign_row_text(
        &self,
        items: &mut [ChooseTreeItem],
        engine: &MuxEngine,
        attached_session: Option<SessionId>,
        facts: &FormatHookFacts,
    ) {
        let Some(format) = self.format.as_deref() else {
            return;
        };
        for item in items.iter_mut() {
            let context = match item.target {
                ChooseTreeTarget::Session(session) => {
                    Some(ExecutionContext::new(Some(session), None, None))
                }
                ChooseTreeTarget::Window(window) => engine
                    .state
                    .windows
                    .get(&window)
                    .map(|entry| ExecutionContext::new(Some(entry.session), Some(window), None)),
                ChooseTreeTarget::Pane(pane) => ExecutionContext::for_pane(&engine.state, pane),
            };
            item.text = context.map_or_else(String::new, |context| {
                let mut hooks = DaemonFormatHooks::command(facts);
                bounded_choose_item_text(&engine.expand_pane_format(
                    format,
                    &context,
                    attached_session,
                    FormatClient::NoClient,
                    &mut hooks,
                ))
            });
        }
    }

    fn rebuild(
        &mut self,
        engine: &MuxEngine,
        attached_session: Option<SessionId>,
        facts: &FormatHookFacts,
    ) {
        let state = &engine.state;
        let mut branches = self.branches(engine, attached_session, facts, self.filter.is_some());
        let filter_no_matches = branches.is_empty() && self.filter.is_some();
        if filter_no_matches {
            branches = self.branches(engine, attached_session, facts, false);
        }
        let mut items = Vec::new();
        'sessions: for (session_id, windows) in branches {
            let session = &state.sessions[&session_id];
            let session_has_children = !windows.is_empty();
            let session_expanded =
                session_has_children && self.expanded_sessions.contains(&session.id);
            if !push_choose_tree_item(
                &mut items,
                ChooseTreeItem {
                    label: bounded_choose_tree_text(&session.name),
                    detail: format_count(session.windows.len(), "window"),
                    target: ChooseTreeTarget::Session(session.id),
                    depth: 0,
                    flags: choose_tree_flags(
                        session_expanded,
                        session_has_children,
                        attached_session == Some(session.id),
                    ),
                    pane_kind: None,
                    key: String::new(),
                    text: String::new(),
                },
            ) {
                break;
            }
            if !session_expanded {
                continue;
            }

            for (window_id, panes) in windows {
                let window = &state.windows[&window_id];
                let window_has_children = !panes.is_empty();
                let window_expanded =
                    window_has_children && self.expanded_windows.contains(&window_id);
                if !push_choose_tree_item(
                    &mut items,
                    ChooseTreeItem {
                        label: bounded_choose_tree_text(&format!(
                            "{}:{}",
                            window.index, window.name
                        )),
                        detail: format_count(window.panes.len(), "pane"),
                        target: ChooseTreeTarget::Window(window_id),
                        depth: 1,
                        flags: choose_tree_flags(
                            window_expanded,
                            window_has_children,
                            session.active_window == window_id,
                        ),
                        pane_kind: None,
                        key: String::new(),
                        text: String::new(),
                    },
                ) {
                    break 'sessions;
                }
                if !window_expanded {
                    continue;
                }

                for pane_id in panes {
                    let Some(pane) = window.panes.get(&pane_id) else {
                        continue;
                    };
                    let (pane_kind, detail) = match &pane.kind {
                        PaneKind::Picker { .. } => (None, "Choose pane type".to_owned()),
                        PaneKind::Terminal => {
                            (Some(ChooseTreePaneKind::Terminal), "Terminal".to_owned())
                        }
                        PaneKind::Browser(browser) => (
                            Some(ChooseTreePaneKind::Browser),
                            format!("Browser · {} · {}", browser.profile, browser.url()),
                        ),
                        PaneKind::Agent(_) => (Some(ChooseTreePaneKind::Agent), "Agent".to_owned()),
                        PaneKind::Editor(editor) => (
                            Some(ChooseTreePaneKind::Editor),
                            editor.path.as_ref().map_or_else(
                                || "Editor · scratch".to_owned(),
                                |path| format!("Editor · {path}"),
                            ),
                        ),
                    };
                    if !push_choose_tree_item(
                        &mut items,
                        ChooseTreeItem {
                            label: bounded_choose_tree_text(&pane.title),
                            detail: bounded_choose_tree_text(&detail),
                            target: ChooseTreeTarget::Pane(pane_id),
                            depth: 2,
                            flags: choose_tree_flags(false, false, window.active_pane == pane_id),
                            pane_kind,
                            key: String::new(),
                            text: String::new(),
                        },
                    ) {
                        break 'sessions;
                    }
                }
            }
        }

        self.assign_row_keys(&mut items, engine, attached_session, facts);
        self.assign_row_text(&mut items, engine, attached_session, facts);

        let fallback = state.window_for_pane(self.source_pane).map(|window| {
            if self.sessions_only {
                ChooseTreeTarget::Session(self.source_session)
            } else {
                match self.kind {
                    ChooseTreeKind::Windows => ChooseTreeTarget::Window(window),
                    ChooseTreeKind::Panes if state.windows[&window].panes.len() == 1 => {
                        ChooseTreeTarget::Window(window)
                    }
                    ChooseTreeKind::Panes => ChooseTreeTarget::Pane(self.source_pane),
                }
            }
        });
        let selected = self
            .selected
            .and_then(|target| items.iter().position(|item| item.target == target))
            .or_else(|| {
                fallback.and_then(|target| items.iter().position(|item| item.target == target))
            })
            .unwrap_or(0)
            .min(items.len().saturating_sub(1));
        self.selected = items.get(selected).map(|item| item.target);
        self.rendered = ChooseTreeState {
            items,
            search: self.search.clone(),
            selected: u32::try_from(selected).unwrap_or(u32::MAX),
            kind: self.kind,
            filter_no_matches,
        };
    }

    fn apply(
        &mut self,
        action: ChooseTreeAction,
        engine: &MuxEngine,
        attached_session: Option<SessionId>,
        facts: &FormatHookFacts,
    ) -> Result<ChooseTreeResult, ServerError> {
        let len = self.rendered.items.len();
        let current = usize::try_from(self.rendered.selected)
            .unwrap_or(usize::MAX)
            .min(len.saturating_sub(1));
        let mut update = ChooseTreeUpdateKind::Delta;
        match action {
            ChooseTreeAction::Previous => self.select_index(current.saturating_sub(1)),
            ChooseTreeAction::Next => self.select_index((current + 1).min(len.saturating_sub(1))),
            ChooseTreeAction::PagePrevious => {
                self.select_index(current.saturating_sub(CHOOSE_TREE_PAGE_ROWS));
            }
            ChooseTreeAction::PageNext => self.select_index(
                current
                    .saturating_add(CHOOSE_TREE_PAGE_ROWS)
                    .min(len.saturating_sub(1)),
            ),
            ChooseTreeAction::First => self.select_index(0),
            ChooseTreeAction::Last => self.select_index(len.saturating_sub(1)),
            ChooseTreeAction::Select(index) => {
                self.select_index(usize::try_from(index).unwrap_or(usize::MAX));
            }
            ChooseTreeAction::ActivateIndex(index) => {
                self.select_index(usize::try_from(index).unwrap_or(usize::MAX));
                return Ok(self.selected.map_or(
                    ChooseTreeResult::Updated(ChooseTreeUpdateKind::Delta),
                    ChooseTreeResult::Activate,
                ));
            }
            ChooseTreeAction::Collapse => {
                if let Some(item) = self.rendered.items.get(current).cloned() {
                    if item.expanded() {
                        self.set_expanded(item.target, false);
                        self.rebuild(engine, attached_session, facts);
                        update = ChooseTreeUpdateKind::Full;
                    } else if item.depth > 0
                        && let Some(parent) = self.rendered.items[..current]
                            .iter()
                            .rev()
                            .position(|candidate| candidate.depth < item.depth)
                    {
                        self.select_index(current - parent - 1);
                    }
                }
            }
            ChooseTreeAction::Expand => {
                if let Some(item) = self.rendered.items.get(current).cloned() {
                    if item.has_children() && !item.expanded() {
                        self.set_expanded(item.target, true);
                        self.rebuild(engine, attached_session, facts);
                        update = ChooseTreeUpdateKind::Full;
                    } else {
                        self.select_index((current + 1).min(len.saturating_sub(1)));
                    }
                }
            }
            ChooseTreeAction::Activate => {
                return Ok(self.selected.map_or(
                    ChooseTreeResult::Updated(ChooseTreeUpdateKind::Delta),
                    ChooseTreeResult::Activate,
                ));
            }
            ChooseTreeAction::SearchStart { reverse } => {
                self.search = Some(ChooseTreeSearchState {
                    query: String::new(),
                    reverse,
                });
                self.rendered.search.clone_from(&self.search);
            }
            ChooseTreeAction::SearchAppend(text) => {
                let Some(search) = self.search.as_mut() else {
                    return Ok(ChooseTreeResult::Updated(ChooseTreeUpdateKind::Delta));
                };
                if search.query.len().saturating_add(text.len()) > MAX_CHOOSE_TREE_QUERY_BYTES {
                    return Err(ServerError::InvalidCommand(format!(
                        "choose-tree search exceeds {MAX_CHOOSE_TREE_QUERY_BYTES} bytes"
                    )));
                }
                search.query.push_str(&text);
                let search = search.clone();
                self.rendered.search = Some(search.clone());
                self.select_search_match(&search.query, search.reverse, true);
            }
            ChooseTreeAction::SearchBackspace => {
                let Some(search) = self.search.as_mut() else {
                    return Ok(ChooseTreeResult::Updated(ChooseTreeUpdateKind::Delta));
                };
                search.query.pop();
                let search = search.clone();
                self.rendered.search = Some(search.clone());
                self.select_search_match(&search.query, search.reverse, true);
            }
            ChooseTreeAction::SearchAccept => {
                if let Some(search) = self.search.take()
                    && !search.query.is_empty()
                {
                    self.last_search = Some(search);
                }
                self.rendered.search = None;
            }
            ChooseTreeAction::SearchCancel => {
                self.search = None;
                self.rendered.search = None;
            }
            ChooseTreeAction::SearchNext { reverse } => {
                if let Some(search) = self.last_search.clone() {
                    self.select_search_match(&search.query, search.reverse ^ reverse, false);
                }
            }
            ChooseTreeAction::Close => return Ok(ChooseTreeResult::Close),
            ChooseTreeAction::Key(_) => {}
        }
        Ok(ChooseTreeResult::Updated(update))
    }

    fn select_index(&mut self, index: usize) {
        let index = index.min(self.rendered.items.len().saturating_sub(1));
        self.rendered.selected = u32::try_from(index).unwrap_or(u32::MAX);
        self.selected = self.rendered.items.get(index).map(|item| item.target);
    }

    fn set_expanded(&mut self, target: ChooseTreeTarget, expanded: bool) {
        match target {
            ChooseTreeTarget::Session(session) => {
                if expanded {
                    self.expanded_sessions.insert(session);
                } else {
                    self.expanded_sessions.remove(&session);
                }
            }
            ChooseTreeTarget::Window(window) => {
                if expanded {
                    self.expanded_windows.insert(window);
                } else {
                    self.expanded_windows.remove(&window);
                }
            }
            ChooseTreeTarget::Pane(_) => {}
        }
    }

    fn select_search_match(&mut self, query: &str, reverse: bool, include_current: bool) {
        if query.is_empty() || self.rendered.items.is_empty() {
            return;
        }
        let query = query.to_lowercase();
        let len = self.rendered.items.len();
        let current = usize::try_from(self.rendered.selected)
            .unwrap_or(usize::MAX)
            .min(len - 1);
        let start = usize::from(!include_current);
        for offset in start..start.saturating_add(len) {
            let index = if reverse {
                (current + len - (offset % len)) % len
            } else {
                (current + offset) % len
            };
            let item = &self.rendered.items[index];
            if item.label.to_lowercase().contains(&query)
                || item.detail.to_lowercase().contains(&query)
                || item.target.to_string().to_lowercase().contains(&query)
            {
                self.select_index(index);
                return;
            }
        }
    }
}

fn push_choose_tree_item(items: &mut Vec<ChooseTreeItem>, item: ChooseTreeItem) -> bool {
    if items.len() >= MAX_CHOOSE_TREE_ITEMS {
        return false;
    }
    items.push(item);
    true
}

fn bounded_choose_tree_text(text: &str) -> String {
    if text.len() <= MAX_CHOOSE_TREE_ITEM_BYTES {
        return text.to_owned();
    }
    let mut end = MAX_CHOOSE_TREE_ITEM_BYTES.saturating_sub('…'.len_utf8());
    while !text.is_char_boundary(end) {
        end -= 1;
    }
    format!("{}…", &text[..end])
}

fn format_count(count: usize, noun: &str) -> String {
    if count == 1 {
        format!("1 {noun}")
    } else {
        format!("{count} {noun}s")
    }
}

const fn choose_tree_flags(expanded: bool, has_children: bool, active: bool) -> u8 {
    let mut flags = 0;
    if expanded {
        flags |= ChooseTreeItem::EXPANDED;
    }
    if has_children {
        flags |= ChooseTreeItem::HAS_CHILDREN;
    }
    if active {
        flags |= ChooseTreeItem::ACTIVE;
    }
    flags
}

#[derive(Debug)]
struct CommandOutputSession {
    output_id: u64,
    pane: PaneId,
    terminal: Arc<TerminalSession>,
    previous_key_table: Option<String>,
}

struct PopupWaiter {
    client: ClientId,
    wake: crossbeam_channel::Sender<u8>,
}

/// One `load-buffer` or `save-buffer` parked on the client that has to do the
/// IO, keyed in `client_file_waiters` by the request id the reply carries.
struct ClientFileWaiter {
    client: ClientId,
    wake: crossbeam_channel::Sender<ClientFileResponse>,
}

struct PopupSession {
    terminal: Arc<TerminalSession>,
    state: PopupState,
    /// The position and size the popup asked for, kept for the life of the
    /// popup. The pin holds the same four numbers in `ppx`/`ppy`/`psx`/`psy`
    /// so a client that shrinks and grows again lands back where it started.
    preferred: PopupPlacement,
    cell_width_px: u32,
    cell_height_px: u32,
    /// The `-s` and `-S` styles the command carried. The pin keeps them beside
    /// the popup because `popup_reapply_styles` rebuilds the cell from the
    /// option on every draw and lets only these two replace its foreground and
    /// background.
    styles: OverlayStyleOverrides,
    waiter: Option<PopupWaiter>,
}

/// The overlay styles a `display-menu` or `display-popup` command named, kept
/// apart from the option-derived cell they override.
#[derive(Clone, Debug, Default)]
struct OverlayStyleOverrides {
    style: Option<String>,
    selected_style: Option<String>,
    border_style: Option<String>,
}

#[derive(Clone, Copy)]
struct PopupPlacement {
    left: u16,
    top: u16,
    width: u16,
    height: u16,
}

struct MenuSession {
    state: MenuState,
    commands: Vec<Option<String>>,
    target: ExecutionContext,
    styles: OverlayStyleOverrides,
    waiter: Option<MenuWaiter>,
}

struct MenuWaiter {
    client: ClientId,
    wake: crossbeam_channel::Sender<()>,
}

enum ConfirmExecution {
    Blocking {
        client: ClientId,
        wake: crossbeam_channel::Sender<bool>,
    },
    Deferred {
        commands: Vec<CommandInvocation>,
        context: Box<ExecutionContext>,
    },
    Background {
        commands: Vec<CommandInvocation>,
    },
}

struct ConfirmSession {
    state: ConfirmState,
    execution: ConfirmExecution,
}

enum EitherPopupFinish {
    Closed(RetiredPopup),
    Retained(PopupState),
}

fn current_command_output_subscriber(
    inner: &ServerState,
    client: ClientId,
    pane: PaneId,
    terminal: &Arc<TerminalSession>,
) -> Option<(u64, Arc<OutboundMailbox>)> {
    let output = inner.command_outputs.get(&client)?;
    if output.pane != pane || !Arc::ptr_eq(&output.terminal, terminal) {
        return None;
    }
    Some((output.output_id, inner.subscribers.get(&client).cloned()?))
}

type RetiredCommandOutput = (CommandOutputSession, Option<Arc<OutboundMailbox>>);
type RetiredPopup = (PopupSession, Option<Arc<OutboundMailbox>>);

#[derive(Clone, Copy, PartialEq, Eq)]
enum Overlay {
    CommandPrompt,
    ChooseTree,
    ChooseBuffer,
    DisplayPanes,
    Popup,
    Menu,
    Confirm,
}

fn dismiss_overlays(
    inner: &mut ServerState,
    client: ClientId,
    raising: Option<Overlay>,
    events: &mut Vec<EventPayload>,
    retired: &mut Vec<(ClientId, RetiredCommandOutput)>,
    retired_popups: &mut Vec<(ClientId, RetiredPopup)>,
    resume_terminals: &mut bool,
) {
    if raising != Some(Overlay::CommandPrompt)
        && let Some(prompt) = inner.command_prompts.remove(&client)
    {
        events.push(EventPayload::CommandPrompt { state: None });
        *resume_terminals |= prompt.freezes();
    }
    if raising != Some(Overlay::ChooseTree) && inner.choose_trees.remove(&client).is_some() {
        events.push(EventPayload::ChooseTree { state: None });
    }
    if raising != Some(Overlay::ChooseBuffer) && inner.choose_buffers.remove(&client).is_some() {
        events.push(EventPayload::ChooseBuffer { state: None });
    }
    if raising != Some(Overlay::DisplayPanes) && take_display_panes(inner, client).is_some() {
        events.push(EventPayload::DisplayPanes { state: None });
    }
    if let Some(output) = take_command_output(inner, client) {
        retired.push((client, output));
    }
    if raising != Some(Overlay::Popup)
        && let Some(popup) = take_popup(inner, client)
    {
        retired_popups.push((client, popup));
    }
    if raising != Some(Overlay::Menu)
        && let Some(menu) = inner.menus.remove(&client)
    {
        if let Some(waiter) = menu.waiter {
            let _ = waiter.wake.try_send(());
        }
        events.push(EventPayload::Menu { state: None });
    }
    if raising != Some(Overlay::Confirm)
        && let Some(confirm) = inner.confirms.remove(&client)
    {
        if let ConfirmExecution::Blocking { wake, .. } = confirm.execution {
            let _ = wake.try_send(false);
        }
        events.push(EventPayload::Confirm { state: None });
    }
}

fn take_command_output(inner: &mut ServerState, client: ClientId) -> Option<RetiredCommandOutput> {
    let output = inner.command_outputs.remove(&client)?;
    inner
        .key_engines
        .entry(client)
        .or_default()
        .switch_table(output.previous_key_table.clone());
    let subscriber = inner.subscribers.get(&client).cloned();
    Some((output, subscriber))
}

fn take_popup(inner: &mut ServerState, client: ClientId) -> Option<RetiredPopup> {
    let popup = inner.popups.remove(&client)?;
    let subscriber = inner.subscribers.get(&client).cloned();
    Some((popup, subscriber))
}

#[derive(Clone, Debug)]
struct PasteBuffer {
    name: String,
    data: Arc<[u8]>,
    created: SystemTime,
    automatic: bool,
    utf8: bool,
}

#[derive(Clone, Debug)]
struct ServerMessage {
    number: u64,
    time: SystemTime,
    text: String,
}

#[derive(Clone, Copy, Debug)]
struct PasteBufferPaste<'a> {
    requested_name: Option<&'a str>,
    separator: &'a [u8],
    expected_client: Option<ClientId>,
    delete: bool,
    bracketed: bool,
    literal: bool,
    event_hooks_enabled: bool,
}

#[derive(Clone, Debug)]
struct CommandPrompt {
    prompt: String,
    input: String,
    cursor: usize,
    template: Option<CommandPromptTemplate>,
    source: Option<SourceSpan>,
    history_index: Option<usize>,
    history_draft: String,
    prompt_type: CommandPromptType,
    mode: CommandPromptMode,
    no_freeze: bool,
    /// `prompt_create`'s `pr->last`: under `-i` the initial input seeds this
    /// instead of the buffer, and `C-r`/`C-s` restore it into an empty buffer.
    last: String,
}

impl CommandPrompt {
    fn new(
        prompt: String,
        input: String,
        template: Option<CommandPromptTemplate>,
        source: Option<SourceSpan>,
        prompt_type: CommandPromptType,
        mode: CommandPromptMode,
        no_freeze: bool,
    ) -> Self {
        let incremental = mode == CommandPromptMode::Incremental;
        let (input, last) = if incremental {
            (String::new(), input)
        } else {
            (input, String::new())
        };
        let cursor = input.len();
        Self {
            prompt,
            history_draft: input.clone(),
            input,
            cursor,
            template,
            source,
            history_index: None,
            prompt_type,
            mode,
            no_freeze,
            last,
        }
    }

    fn kind(&self) -> CommandPromptKind {
        if self.template.is_some() {
            CommandPromptKind::Value
        } else {
            CommandPromptKind::Command
        }
    }

    /// `status_prompt_set`: the prompt raises `TTY_FREEZE` unless it is
    /// incremental or `-C` asked it not to.
    const fn freezes(&self) -> bool {
        !self.no_freeze && !matches!(self.mode, CommandPromptMode::Incremental)
    }

    /// `-1`, `-N` and `-k` read key codes rather than committed text, so the
    /// text half of a split key press must not reach the buffer.
    const fn reads_raw_keys(&self) -> bool {
        matches!(
            self.mode,
            CommandPromptMode::Single | CommandPromptMode::Numeric | CommandPromptMode::Key
        )
    }

    fn state(&self, history: &[String]) -> CommandPromptState {
        CommandPromptState {
            prompt: self.prompt.clone(),
            input: self.input.clone(),
            cursor: u32::try_from(self.input[..self.cursor].chars().count()).unwrap_or(u32::MAX),
            kind: self.kind(),
            history: if self.kind() == CommandPromptKind::Command {
                command_prompt_history_snapshot(history)
            } else {
                Vec::new()
            },
            prompt_type: self.prompt_type,
            mode: self.mode,
            no_freeze: self.no_freeze,
        }
    }

    fn replace_input(&mut self, input: String, cursor: u32) -> Result<(), ServerError> {
        if input.len() > zz_protocol::MAX_COMMAND_PROMPT_BYTES {
            return Err(ServerError::InvalidCommand(format!(
                "command prompt input exceeds {} bytes",
                zz_protocol::MAX_COMMAND_PROMPT_BYTES
            )));
        }
        let cursor = usize::try_from(cursor).unwrap_or(usize::MAX);
        let cursor = char_index_to_byte(&input, cursor).ok_or_else(|| {
            ServerError::InvalidCommand("command prompt cursor is out of bounds".to_owned())
        })?;
        self.input = input;
        self.cursor = cursor;
        self.finish_edit();
        Ok(())
    }

    fn insert(&mut self, text: &str) -> bool {
        if text.is_empty()
            || self.input.len().saturating_add(text.len()) > zz_protocol::MAX_COMMAND_PROMPT_BYTES
        {
            return false;
        }
        self.input.insert_str(self.cursor, text);
        self.cursor += text.len();
        self.finish_edit();
        true
    }

    /// `prompt_key`'s `C-r`/`C-s`: an empty incremental buffer is refilled from
    /// `pr->last` and searches forward again, otherwise the direction prefix
    /// changes and the buffer stands.
    fn incremental_prefix(&mut self, backward: bool) -> char {
        if self.input.is_empty() {
            self.input.clone_from(&self.last);
            self.cursor = self.input.len();
            self.finish_edit();
            '='
        } else if backward {
            '-'
        } else {
            '+'
        }
    }

    fn move_left(&mut self) -> bool {
        let next = previous_char_boundary(&self.input, self.cursor);
        let changed = next != self.cursor;
        self.cursor = next;
        changed
    }

    fn move_right(&mut self) -> bool {
        let next = next_char_boundary(&self.input, self.cursor);
        let changed = next != self.cursor;
        self.cursor = next;
        changed
    }

    fn move_word_left(&mut self) -> bool {
        let original = self.cursor;
        while self.cursor > 0 {
            let previous = previous_char_boundary(&self.input, self.cursor);
            if !self.input[previous..self.cursor]
                .chars()
                .next()
                .is_some_and(char::is_whitespace)
            {
                break;
            }
            self.cursor = previous;
        }
        while self.cursor > 0 {
            let previous = previous_char_boundary(&self.input, self.cursor);
            if self.input[previous..self.cursor]
                .chars()
                .next()
                .is_some_and(char::is_whitespace)
            {
                break;
            }
            self.cursor = previous;
        }
        self.cursor != original
    }

    fn move_word_right(&mut self) -> bool {
        let original = self.cursor;
        while self.cursor < self.input.len() {
            let next = next_char_boundary(&self.input, self.cursor);
            if !self.input[self.cursor..next]
                .chars()
                .next()
                .is_some_and(char::is_whitespace)
            {
                break;
            }
            self.cursor = next;
        }
        while self.cursor < self.input.len() {
            let next = next_char_boundary(&self.input, self.cursor);
            if self.input[self.cursor..next]
                .chars()
                .next()
                .is_some_and(char::is_whitespace)
            {
                break;
            }
            self.cursor = next;
        }
        self.cursor != original
    }

    fn delete_backward(&mut self) -> bool {
        let previous = previous_char_boundary(&self.input, self.cursor);
        if previous == self.cursor {
            return false;
        }
        self.input.replace_range(previous..self.cursor, "");
        self.cursor = previous;
        self.finish_edit();
        true
    }

    fn delete_forward(&mut self) -> bool {
        let next = next_char_boundary(&self.input, self.cursor);
        if next == self.cursor {
            return false;
        }
        self.input.replace_range(self.cursor..next, "");
        self.finish_edit();
        true
    }

    fn delete_previous_word(&mut self) -> bool {
        let end = self.cursor;
        self.move_word_left();
        if self.cursor == end {
            return false;
        }
        self.input.replace_range(self.cursor..end, "");
        self.finish_edit();
        true
    }

    fn clear(&mut self) -> bool {
        if self.input.is_empty() {
            return false;
        }
        self.input.clear();
        self.cursor = 0;
        self.finish_edit();
        true
    }

    fn delete_to_end(&mut self) -> bool {
        if self.cursor == self.input.len() {
            return false;
        }
        self.input.truncate(self.cursor);
        self.finish_edit();
        true
    }

    fn history_up(&mut self, history: &[String]) -> bool {
        if history.is_empty() {
            return false;
        }
        let index = self.history_index.map_or_else(
            || {
                self.history_draft.clone_from(&self.input);
                history.len() - 1
            },
            |index| index.saturating_sub(1),
        );
        if self.history_index == Some(index) {
            return false;
        }
        self.history_index = Some(index);
        self.input.clone_from(&history[index]);
        self.cursor = self.input.len();
        true
    }

    fn history_down(&mut self, history: &[String]) -> bool {
        let Some(index) = self.history_index else {
            return false;
        };
        if index + 1 < history.len() {
            self.history_index = Some(index + 1);
            self.input.clone_from(&history[index + 1]);
        } else {
            self.history_index = None;
            self.input.clone_from(&self.history_draft);
        }
        self.cursor = self.input.len();
        true
    }

    fn finish_edit(&mut self) {
        self.history_index = None;
        self.history_draft.clone_from(&self.input);
    }
}

fn command_prompt_history_snapshot(history: &[String]) -> Vec<String> {
    let mut bytes: usize = 0;
    let mut snapshot = history
        .iter()
        .rev()
        .take(MAX_COMMAND_PROMPT_HISTORY_SNAPSHOT_ITEMS)
        .take_while(|entry| {
            let next = bytes.saturating_add(entry.len());
            if next > MAX_COMMAND_PROMPT_HISTORY_SNAPSHOT_BYTES {
                false
            } else {
                bytes = next;
                true
            }
        })
        .cloned()
        .collect::<Vec<_>>();
    snapshot.reverse();
    snapshot
}

fn append_prompt_history_output(output: &mut String, prompt_type: &str, history: &[String]) {
    let _ = writeln!(output, "History for {prompt_type}:\n");
    for (index, entry) in history.iter().enumerate() {
        let _ = writeln!(output, "{}: {entry}", index + 1);
    }
    output.push('\n');
}

/// `prompt_hlist[PROMPT_NTYPES]`: command and search prompts keep separate
/// rings, and `-T` alone decides which one a prompt reads and writes.
fn prompt_history(inner: &ServerState, prompt_type: CommandPromptType) -> &[String] {
    match prompt_type {
        CommandPromptType::Command => &inner.command_history,
        CommandPromptType::Search => &inner.search_history,
    }
}

fn command_prompt_state(inner: &ServerState, client: ClientId) -> Option<CommandPromptState> {
    inner
        .command_prompts
        .get(&client)
        .map(|prompt| prompt.state(prompt_history(inner, prompt.prompt_type)))
}

fn char_index_to_byte(input: &str, index: usize) -> Option<usize> {
    input
        .char_indices()
        .nth(index)
        .map(|(offset, _)| offset)
        .or_else(|| (index == input.chars().count()).then_some(input.len()))
}

fn previous_char_boundary(text: &str, index: usize) -> usize {
    text[..index]
        .char_indices()
        .next_back()
        .map_or(0, |(index, _)| index)
}

fn next_char_boundary(text: &str, index: usize) -> usize {
    text[index..]
        .char_indices()
        .nth(1)
        .map_or(text.len(), |(offset, _)| index + offset)
}

/// `prompt_key`'s return, split by what the daemon owes the client afterwards.
/// `Handled`, `Updated` and `LimitExceeded` keep the prompt; everything else
/// retires it. Only `SubmitAndPass` is the pin's `PROMPT_KEY_NOT_HANDLED`, the
/// one answer that lets the key go on to the key tables.
#[derive(Clone, Debug, PartialEq, Eq)]
enum PromptKeyAction {
    Handled,
    Updated,
    Close,
    Submit,
    /// `-i`: Enter records history and closes, because every edit already ran.
    SubmitIncremental,
    /// `-1`/`-k`: the answer is the key itself, not the buffer, and the pin
    /// records history only for Enter.
    SubmitAnswer(String),
    /// `-N`: the buffer runs and the key still reaches the key tables.
    SubmitAndPass,
    /// `-i`: the template runs against this prefix plus the buffer and the
    /// prompt stays open.
    Incremental(char),
    LimitExceeded,
}

struct CommandPromptSubmission {
    input: String,
    template: Option<CommandPromptTemplate>,
    source: Option<SourceSpan>,
}

/// What the wire owes the client about the prompt after one key press.
#[derive(Default)]
enum PromptWireUpdate {
    /// The prompt neither changed nor closed, so nothing is published.
    #[default]
    Silent,
    Republish(Box<CommandPromptState>),
    Retire,
}

/// What one key press owes the client once the prompt lock is released.
#[derive(Default)]
struct PromptKeyOutcome {
    event: PromptWireUpdate,
    /// The retired prompt was freezing, so the client owes a full viewport.
    retired: bool,
    remember: Option<(CommandPromptType, String)>,
    submission: Option<CommandPromptSubmission>,
    /// The pin's `PROMPT_KEY_NOT_HANDLED`: the key goes on to the key tables.
    pass: bool,
    limit_exceeded: bool,
}

fn command_prompt_focus_action(mode: CommandPromptMode, focused: bool) -> PromptKeyAction {
    match mode {
        CommandPromptMode::Key => {
            PromptKeyAction::SubmitAnswer(if focused { "FocusIn" } else { "FocusOut" }.to_owned())
        }
        CommandPromptMode::Numeric => PromptKeyAction::SubmitAndPass,
        CommandPromptMode::Text
        | CommandPromptMode::Single
        | CommandPromptMode::Incremental
        | CommandPromptMode::BackspaceExit => PromptKeyAction::Handled,
    }
}

fn command_prompt_outcome(
    inner: &mut ServerState,
    client: ClientId,
    prompt: CommandPrompt,
    action: PromptKeyAction,
    state: Option<CommandPromptState>,
) -> PromptKeyOutcome {
    let prompt_type = prompt.prompt_type;
    match action {
        PromptKeyAction::Handled => {
            inner.command_prompts.insert(client, prompt);
            PromptKeyOutcome::default()
        }
        PromptKeyAction::Updated => {
            inner.command_prompts.insert(client, prompt);
            PromptKeyOutcome {
                event: PromptWireUpdate::Republish(Box::new(
                    state.expect("an updated prompt built its state"),
                )),
                ..PromptKeyOutcome::default()
            }
        }
        PromptKeyAction::LimitExceeded => {
            inner.command_prompts.insert(client, prompt);
            PromptKeyOutcome {
                limit_exceeded: true,
                ..PromptKeyOutcome::default()
            }
        }
        PromptKeyAction::Incremental(prefix) => {
            let fired = CommandPromptSubmission {
                input: format!("{prefix}{}", prompt.input),
                template: prompt.template.clone(),
                source: prompt.source.clone(),
            };
            inner.command_prompts.insert(client, prompt);
            PromptKeyOutcome {
                event: PromptWireUpdate::Republish(Box::new(
                    state.expect("an incremental edit built its state"),
                )),
                submission: Some(fired),
                ..PromptKeyOutcome::default()
            }
        }
        PromptKeyAction::Close => PromptKeyOutcome {
            event: PromptWireUpdate::Retire,
            retired: prompt.freezes(),
            ..PromptKeyOutcome::default()
        },
        PromptKeyAction::SubmitIncremental => PromptKeyOutcome {
            event: PromptWireUpdate::Retire,
            retired: prompt.freezes(),
            remember: (!prompt.input.is_empty()).then_some((prompt_type, prompt.input)),
            ..PromptKeyOutcome::default()
        },
        PromptKeyAction::SubmitAnswer(answer) => PromptKeyOutcome {
            event: PromptWireUpdate::Retire,
            retired: prompt.freezes(),
            submission: Some(CommandPromptSubmission {
                input: answer,
                template: prompt.template,
                source: prompt.source,
            }),
            ..PromptKeyOutcome::default()
        },
        PromptKeyAction::Submit => {
            let retired = prompt.freezes();
            let submission = (!prompt.input.is_empty() || prompt.template.is_some()).then(|| {
                CommandPromptSubmission {
                    input: prompt.input.clone(),
                    template: prompt.template.clone(),
                    source: prompt.source.clone(),
                }
            });
            PromptKeyOutcome {
                event: PromptWireUpdate::Retire,
                retired,
                remember: (!prompt.input.is_empty()).then_some((prompt_type, prompt.input)),
                submission,
                pass: false,
                limit_exceeded: false,
            }
        }
        PromptKeyAction::SubmitAndPass => {
            let retired = prompt.freezes();
            let submission = (!prompt.input.is_empty() || prompt.template.is_some()).then_some({
                CommandPromptSubmission {
                    input: prompt.input,
                    template: prompt.template,
                    source: prompt.source,
                }
            });
            PromptKeyOutcome {
                event: PromptWireUpdate::Retire,
                retired,
                remember: None,
                submission,
                pass: true,
                limit_exceeded: false,
            }
        }
    }
}

fn append_command_prompt_output(output: &mut String, piece: &str) -> bool {
    let content_limit =
        MAX_COMMAND_PROMPT_OUTPUT_BYTES.saturating_sub(COMMAND_PROMPT_OUTPUT_TRUNCATED.len() + 1);
    let separator_bytes = usize::from(!output.is_empty());
    let available = content_limit.saturating_sub(output.len());
    if separator_bytes.saturating_add(piece.len()) <= available {
        if separator_bytes != 0 {
            output.push('\n');
        }
        output.push_str(piece);
        return false;
    }

    let piece_available = available.saturating_sub(separator_bytes);
    let mut prefix_bytes = piece.len().min(piece_available);
    while !piece.is_char_boundary(prefix_bytes) {
        prefix_bytes -= 1;
    }
    if prefix_bytes != 0 {
        if separator_bytes != 0 {
            output.push('\n');
        }
        output.push_str(&piece[..prefix_bytes]);
    }
    true
}

fn bounded_command_output(text: &str) -> String {
    let mut output = String::new();
    if append_command_prompt_output(&mut output, text) {
        if !output.is_empty() {
            output.push('\n');
        }
        output.push_str(COMMAND_PROMPT_OUTPUT_TRUNCATED);
    }
    output
}

fn startup_config_preview(causes: &[String]) -> String {
    let joined = causes.join("\n");
    let mut preview = String::with_capacity(joined.len().min(MAX_STARTUP_CONFIG_PREVIEW_BYTES));
    for character in joined.chars() {
        if character.is_control() && !matches!(character, '\n' | '\t') {
            preview.push('\u{fffd}');
        } else {
            preview.push(character);
        }
    }
    if preview.len() <= MAX_STARTUP_CONFIG_PREVIEW_BYTES {
        return preview;
    }
    let mut end =
        MAX_STARTUP_CONFIG_PREVIEW_BYTES.saturating_sub(STARTUP_CONFIG_PREVIEW_TRUNCATED.len() + 1);
    while !preview.is_char_boundary(end) {
        end -= 1;
    }
    preview.truncate(end);
    preview.push('\n');
    preview.push_str(STARTUP_CONFIG_PREVIEW_TRUNCATED);
    preview
}

fn client_context_pane(inner: &ServerState, client: ClientId) -> Option<PaneId> {
    client_attached_session(inner, client)
        .and_then(|session| inner.engine.state.sessions.get(&session))
        .and_then(|session| {
            inner
                .engine
                .state
                .windows
                .get(&client_focused_window(inner, client, session))
        })
        .map(|window| window.active_pane)
        .or_else(|| {
            inner
                .engine
                .state
                .default_context()
                .map(|(_, _, pane)| pane)
        })
}

fn sync_context_with_attachment(
    inner: &ServerState,
    client: ClientId,
    context: &mut ExecutionContext,
) {
    retarget_context_to_attachment(inner, client, context);
}

fn retarget_context_to_attachment(
    inner: &ServerState,
    client: ClientId,
    context: &mut ExecutionContext,
) {
    let Some(session) = client_attached_session(inner, client)
        .and_then(|session| inner.engine.state.sessions.get(&session))
    else {
        return;
    };
    let window = client_focused_window(inner, client, session);
    let Some(pane) = inner
        .engine
        .state
        .windows
        .get(&window)
        .map(|window| window.active_pane)
    else {
        return;
    };
    context.retarget(&ExecutionContext::new(
        Some(session.id),
        Some(window),
        Some(pane),
    ));
}

fn enter_copy_session(
    inner: &mut ServerState,
    client: ClientId,
    pane: PaneId,
) -> Result<(), ServerError> {
    let table = inner.engine.copy_mode_table_for_pane(pane)?.to_owned();
    inner
        .key_engines
        .entry(client)
        .or_default()
        .switch_table(Some(table));
    inner.copy_sessions.insert(
        client,
        CopySession {
            pane,
            observed: false,
            scroll_exit: false,
            exiting: false,
        },
    );
    Ok(())
}

fn terminal_view_action_arms_scroll_exit(action: &zz_terminal::TerminalViewAction) -> bool {
    matches!(
        action,
        zz_terminal::TerminalViewAction::CopyMode(zz_terminal::CopyModeAction::PageDownScrollExit)
            | zz_terminal::TerminalViewAction::CopyModeCounted {
                action: zz_terminal::CopyModeAction::PageDownScrollExit,
                ..
            }
    )
}

fn exit_copy_session(inner: &mut ServerState, client: ClientId) {
    inner.copy_sessions.remove(&client);
    inner
        .key_engines
        .entry(client)
        .or_default()
        .switch_table(None);
}

fn begin_exit_copy_session(inner: &mut ServerState, client: ClientId) {
    if let Some(session) = inner.copy_sessions.get_mut(&client) {
        session.exiting = true;
    }
    inner
        .key_engines
        .entry(client)
        .or_default()
        .switch_table(None);
}

fn active_copy_mode_panes(inner: &ServerState) -> BTreeSet<PaneId> {
    inner
        .copy_sessions
        .values()
        .filter(|session| !session.exiting)
        .map(|session| session.pane)
        .collect()
}

fn sync_copy_session_for_view_action(
    inner: &mut ServerState,
    client: ClientId,
    pane: PaneId,
    action: &zz_terminal::TerminalViewAction,
) -> Result<(), ServerError> {
    if terminal_view_action_enters_copy_mode(action) {
        enter_copy_session(inner, client, pane)?;
    } else if terminal_view_action_exits_copy_mode(action) {
        begin_exit_copy_session(inner, client);
    } else if terminal_view_action_arms_scroll_exit(action)
        && let Some(session) = inner.copy_sessions.get_mut(&client)
        && session.pane == pane
    {
        session.scroll_exit = true;
    }
    Ok(())
}

fn terminal_view_action_enters_copy_mode(action: &zz_terminal::TerminalViewAction) -> bool {
    matches!(
        action,
        zz_terminal::TerminalViewAction::EnterCopyMode
            | zz_terminal::TerminalViewAction::EnterCopyModeScrollExit
            | zz_terminal::TerminalViewAction::EnterCopyModeWith { .. }
    )
}

fn terminal_view_action_exits_copy_mode(action: &zz_terminal::TerminalViewAction) -> bool {
    match action {
        zz_terminal::TerminalViewAction::ClearHistory
        | zz_terminal::TerminalViewAction::CopyMode(zz_terminal::CopyModeAction::Cancel)
        | zz_terminal::TerminalViewAction::CopyModeCounted {
            action: zz_terminal::CopyModeAction::Cancel,
            ..
        } => true,
        zz_terminal::TerminalViewAction::CopyMode(
            zz_terminal::CopyModeAction::CopySelection(copy)
            | zz_terminal::CopyModeAction::CopyEndOfLine(copy),
        )
        | zz_terminal::TerminalViewAction::CopyModeCounted {
            action:
                zz_terminal::CopyModeAction::CopySelection(copy)
                | zz_terminal::CopyModeAction::CopyEndOfLine(copy),
            ..
        } => copy.cancel,
        _ => false,
    }
}

fn retarget_copy_mode_tables(inner: &mut ServerState, changed_window: Option<WindowId>) {
    let retargeted = inner
        .copy_sessions
        .iter()
        .filter(|(client, session)| {
            !session.exiting && !inner.command_outputs.contains_key(*client)
        })
        .filter_map(|(client, session)| {
            let window = inner.engine.state.window_for_pane(session.pane)?;
            changed_window
                .is_none_or(|changed| changed == window)
                .then_some((*client, session.pane))
        })
        .chain(inner.command_outputs.iter().filter_map(|(client, output)| {
            let window = inner.engine.state.window_for_pane(output.pane)?;
            changed_window
                .is_none_or(|changed| changed == window)
                .then_some((*client, output.pane))
        }))
        .collect::<Vec<_>>();
    let restored = inner
        .command_outputs
        .keys()
        .filter_map(|client| {
            let session = inner
                .copy_sessions
                .get(client)
                .filter(|session| !session.exiting)?;
            let window = inner.engine.state.window_for_pane(session.pane)?;
            changed_window
                .is_none_or(|changed| changed == window)
                .then_some((*client, session.pane))
        })
        .collect::<Vec<_>>();
    for (client, pane) in retargeted {
        let Ok(table) = inner.engine.copy_mode_table_for_pane(pane) else {
            continue;
        };
        let table = table.to_owned();
        inner
            .key_engines
            .entry(client)
            .or_default()
            .switch_table(Some(table));
    }
    for (client, pane) in restored {
        let Ok(table) = inner.engine.copy_mode_table_for_pane(pane) else {
            continue;
        };
        let table = table.to_owned();
        if let Some(output) = inner.command_outputs.get_mut(&client) {
            output.previous_key_table = Some(table);
        }
    }
}

fn unfocused_copy_sessions(inner: &mut ServerState) -> Vec<(ClientId, Arc<TerminalSession>)> {
    let stale = inner
        .copy_sessions
        .iter()
        .filter(|(client, session)| client_context_pane(inner, **client) != Some(session.pane))
        .map(|(client, session)| (*client, session.pane))
        .collect::<Vec<_>>();
    stale
        .into_iter()
        .filter_map(|(client, pane)| {
            exit_copy_session(inner, client);
            Some((client, inner.terminals.get(&pane).cloned()?))
        })
        .collect()
}

fn reconcile_copy_session(
    inner: &mut ServerState,
    pane: PaneId,
    client: ClientId,
    mode: TerminalMode,
) -> (Option<Arc<TerminalSession>>, bool) {
    match (mode, inner.copy_sessions.get_mut(&client)) {
        (TerminalMode::Copy { .. }, Some(session)) if session.pane == pane => {
            if !session.exiting {
                session.observed = true;
            }
            (None, false)
        }
        (TerminalMode::Copy { .. }, _) => (inner.terminals.get(&pane).cloned(), false),
        (TerminalMode::Live, Some(session))
            if session.pane == pane
                && (session.observed || session.scroll_exit || session.exiting) =>
        {
            exit_copy_session(inner, client);
            (None, true)
        }
        _ => (None, false),
    }
}

/// The window `menu_reapply_styles` and `popup_reapply_styles` read their
/// options from: the current window of the session the overlay's own client is
/// attached to, which is not always the window the command targeted.
fn client_overlay_style_window(inner: &ServerState, client: ClientId) -> Option<WindowId> {
    let session = client_attached_session(inner, client)?;
    inner
        .engine
        .state
        .sessions
        .get(&session)
        .map(|state| state.active_window)
}

/// Fold a command line overlay style into the option-derived one the way
/// `menu_reapply_styles` and `popup_reapply_styles` do: the option supplies the
/// whole cell, and `style_parse` is read back for its foreground and background
/// alone, both of which land on the default when the command line style never
/// names them. An attribute the option asked for therefore survives a `-s` that
/// carries none, and a colour the option asked for is dropped by a `-s` that
/// only names the other half. A command line style `style_parse` rejects is
/// dropped whole and leaves the option's cell alone.
fn overlay_style(option: &str, explicit: Option<&str>) -> String {
    let Some(explicit) = explicit.filter(|explicit| zz_protocol::valid_style(explicit)) else {
        return option.to_owned();
    };
    let mut foreground = Some("fg=default");
    let mut background = Some("bg=default");
    for token in explicit
        .split([' ', ',', '\n'])
        .filter(|token| !token.is_empty())
    {
        if token.eq_ignore_ascii_case("default") {
            foreground = None;
            background = None;
        } else if style_field_is(token, "fg=") {
            foreground = Some(token);
        } else if style_field_is(token, "bg=") {
            background = Some(token);
        }
    }
    let mut composed = option.to_owned();
    for field in [foreground, background].into_iter().flatten() {
        if !composed.is_empty() {
            composed.push(',');
        }
        composed.push_str(field);
    }
    composed
}

fn style_field_is(token: &str, field: &str) -> bool {
    token.len() > field.len()
        && token.as_bytes()[..field.len()].eq_ignore_ascii_case(field.as_bytes())
}

fn client_attached_session(inner: &ServerState, client: ClientId) -> Option<SessionId> {
    inner
        .attached
        .iter()
        .find_map(|(session, clients)| clients.contains(&client).then_some(*session))
}

fn client_tty_fact(capabilities: &[String]) -> Option<String> {
    capabilities.iter().find_map(|capability| {
        capability
            .strip_prefix(ClientHello::CLIENT_TTY_CAPABILITY_PREFIX)
            .filter(|tty| !tty.is_empty())
            .map(str::to_owned)
    })
}

fn client_nested_fact(capabilities: &[String]) -> bool {
    capabilities
        .iter()
        .any(|capability| capability == ClientHello::CLIENT_NESTED_CAPABILITY)
}

fn client_size_fact(capabilities: &[String]) -> Option<(u16, u16)> {
    capabilities.iter().find_map(|capability| {
        let value = capability.strip_prefix(ClientHello::CLIENT_SIZE_CAPABILITY_PREFIX)?;
        let (columns, rows) = value.split_once('x')?;
        let columns = columns.parse::<u16>().ok().filter(|columns| *columns > 0)?;
        let rows = rows.parse::<u16>().ok().filter(|rows| *rows > 0)?;
        Some((columns, rows))
    })
}

fn client_working_directory_fact(working_directory: Option<&ClientPath>) -> Option<PathBuf> {
    working_directory
        .and_then(ClientPath::to_path_buf)
        .filter(|working_directory| working_directory.is_absolute())
}

fn client_environment_fact(entries: &[String]) -> Arc<BTreeMap<String, String>> {
    Arc::new(
        entries
            .iter()
            .filter_map(|entry| entry.split_once('='))
            .map(|(name, value)| (name.to_owned(), value.to_owned()))
            .collect(),
    )
}

fn effective_mux_options(inner: &ServerState, client: ClientId) -> MuxOptions {
    let mut options = inner.mux_options.clone();
    let mouse = inner
        .engine
        .effective_mouse(client_attached_session(inner, client));
    let source = options
        .get(MuxOptionKey::Mouse)
        .map_or(MuxOptionSource::Default, |value| value.source);
    options.set(
        MuxOptionKey::Mouse,
        if mouse { "on" } else { "off" },
        source,
    );
    options
}

fn best_client_on_session(inner: &ServerState, session: SessionId) -> Option<ClientId> {
    inner
        .attached
        .get(&session)?
        .iter()
        .copied()
        .max_by_key(|client| {
            (
                inner
                    .client_activity
                    .get(client)
                    .copied()
                    .unwrap_or_default(),
                Reverse(client.0),
            )
        })
}

fn best_display_message_format_client(
    inner: &ServerState,
    target_session: SessionId,
) -> Option<ClientId> {
    best_client_on_session(inner, target_session).or_else(|| best_attached_client(inner))
}

fn best_attached_client(inner: &ServerState) -> Option<ClientId> {
    inner
        .attached
        .values()
        .flatten()
        .copied()
        .max_by_key(|client| {
            (
                inner
                    .client_activity
                    .get(client)
                    .copied()
                    .unwrap_or_default(),
                Reverse(client.0),
            )
        })
}

fn best_attached_session(inner: &ServerState) -> Option<SessionId> {
    inner
        .attached
        .iter()
        .filter(|(session, clients)| {
            !clients.is_empty() && inner.engine.state.sessions.contains_key(session)
        })
        .map(|(session, _)| *session)
        .max_by_key(|session| {
            let state = &inner.engine.state.sessions[session];
            (state.sort_activity, state.sort_created, state.name.clone())
        })
}

fn newest_session_matching(
    inner: &ServerState,
    predicate: impl Fn(SessionId) -> bool,
) -> Option<SessionId> {
    inner
        .engine
        .state
        .sessions
        .values()
        .filter(|session| predicate(session.id))
        .max_by_key(|session| {
            (
                session.sort_activity,
                session.sort_created,
                session.name.clone(),
            )
        })
        .map(|session| session.id)
}

fn destroyed_session_survivor(
    inner: &ServerState,
    destroyed_name: &str,
    policy: &str,
) -> Option<SessionId> {
    match policy {
        "off" => newest_session_matching(inner, |_| true),
        "no-detached" => newest_session_matching(inner, |session| {
            inner.attached.get(&session).is_none_or(BTreeSet::is_empty)
        }),
        "previous" => {
            let sessions = inner.engine.state.sessions_by_name();
            sessions
                .iter()
                .rev()
                .find(|session| session.name.as_str() < destroyed_name)
                .or_else(|| sessions.last())
                .map(|session| session.id)
        }
        "next" => {
            let sessions = inner.engine.state.sessions_by_name();
            sessions
                .iter()
                .find(|session| session.name.as_str() > destroyed_name)
                .or_else(|| sessions.first())
                .map(|session| session.id)
        }
        _ => None,
    }
}

fn resolve_client_target(
    inner: &ServerState,
    invoking_client: ClientId,
    kind: ClientKind,
    target: Option<&str>,
) -> Result<ClientId, ServerError> {
    if let Some(target) = target {
        return find_attached_client(inner, target).ok_or_else(|| client_target_error(target));
    }
    if matches!(kind, ClientKind::Interactive | ClientKind::Control)
        && client_attached_session(inner, invoking_client).is_some()
    {
        return Ok(invoking_client);
    }
    if let Some(session) = inner
        .client_origins
        .get(&invoking_client)
        .and_then(|pane| inner.engine.state.window_for_pane(*pane))
        .and_then(|window| inner.engine.state.windows.get(&window))
        .map(|window| window.session)
        && let Some(client) = best_client_on_session(inner, session)
    {
        return Ok(client);
    }
    best_attached_session(inner)
        .and_then(|session| best_client_on_session(inner, session))
        .ok_or_else(|| ServerError::InvalidCommand("no current client".to_owned()))
}

fn normalized_client_target(target: &str) -> &str {
    target.strip_suffix(':').unwrap_or(target)
}

fn attached_client_matches(
    inner: &ServerState,
    client: ClientId,
    target: &str,
    native_aliases: bool,
) -> bool {
    inner
        .client_names
        .get(&client)
        .is_some_and(|name| name == target)
        || client_format_name(inner, client) == target
        || format!("device-{}", client.0) == target
        || inner.client_ttys.get(&client).is_some_and(|tty| {
            tty == target
                || tty
                    .strip_prefix("/dev/")
                    .is_some_and(|device| device == target)
        })
        || native_aliases
            && (target == client.0.to_string() || target == format!("client-{}", client.0))
}

fn find_attached_client_with_aliases(
    inner: &ServerState,
    target: &str,
    native_aliases: bool,
) -> Option<ClientId> {
    let target = normalized_client_target(target);
    inner
        .attached
        .values()
        .flatten()
        .copied()
        .filter(|client| attached_client_matches(inner, *client, target, native_aliases))
        .min()
}

fn find_attached_client(inner: &ServerState, target: &str) -> Option<ClientId> {
    find_attached_client_with_aliases(inner, target, false)
}

fn client_target_error(target: &str) -> ServerError {
    ServerError::InvalidCommand(format!(
        "can't find client: {}",
        normalized_client_target(target)
    ))
}

fn requested_detach_victims(
    inner: &ServerState,
    detach: ResolvedDetach,
) -> Vec<(SessionId, ClientId)> {
    match detach {
        ResolvedDetach::Client(target) => client_attached_session(inner, target)
            .map(|session| vec![(session, target)])
            .unwrap_or_default(),
        ResolvedDetach::Others(target) => inner
            .attached
            .iter()
            .flat_map(|(session, clients)| {
                clients
                    .iter()
                    .filter(move |client| **client != target)
                    .map(|client| (*session, *client))
            })
            .collect(),
        ResolvedDetach::Session(session) => inner
            .attached
            .get(&session)
            .into_iter()
            .flatten()
            .map(|client| (session, *client))
            .collect(),
    }
}

fn resolve_display_panes_client(
    inner: &ServerState,
    target: &str,
) -> Result<ClientId, ServerError> {
    find_attached_client(inner, target).ok_or_else(|| client_target_error(target))
}

fn resolve_display_message_client(inner: &ServerState, target: &str) -> Option<ClientId> {
    find_attached_client(inner, target)
}

fn nested_attach_refusal(inner: &ServerState, client: ClientId) -> Option<ServerError> {
    if !inner.nested_clients.contains(&client) {
        return None;
    }
    let tty = inner.client_ttys.get(&client)?;
    if inner.engine.state.sessions.is_empty() {
        return None;
    }
    inner
        .terminals
        .values()
        .any(|terminal| {
            terminal
                .tty()
                .is_some_and(|pane_tty| pane_tty.as_os_str() == tty.as_str())
        })
        .then(|| {
            ServerError::InvalidCommand(
                "sessions should be nested with care, unset $TMUX to force".to_owned(),
            )
        })
}

fn format_client_flags(inner: &ServerState, client: ClientId) -> String {
    let mut flags = Vec::new();
    let requested = inner.client_flags.get(client);
    if client_attached_session(inner, client).is_some() {
        flags.push("attached".to_owned());
    }
    if inner.client_focused.get(&client).copied().unwrap_or(true) {
        flags.push("focused".to_owned());
    }
    if inner.client_kinds.get(&client) == Some(&ClientKind::Control) {
        flags.push("control-mode".to_owned());
    }
    if client_ignores_size(inner, client) {
        flags.push("ignore-size".to_owned());
    }
    if requested.no_detach_on_destroy {
        flags.push("no-detach-on-destroy".to_owned());
    }
    if inner.client_kinds.get(&client) == Some(&ClientKind::Control)
        && let Some(output) = inner.control_outputs.get(&client)
    {
        if output.no_output {
            flags.push("no-output".to_owned());
        }
        if output.wait_exit {
            flags.push("wait-exit".to_owned());
        }
        if let Some(pause_after_ms) = output.pause_after_ms {
            flags.push(format!("pause-after={}", pause_after_ms / 1000));
        }
    }
    if requested.read_only {
        flags.push("read-only".to_owned());
    }
    if requested.active_pane {
        flags.push("active-pane".to_owned());
    }
    if client_uses_utf8(inner, client) {
        flags.push("UTF-8".to_owned());
    }
    flags.join(",")
}

fn client_environment_value<'a>(
    inner: &'a ServerState,
    client: ClientId,
    name: &str,
) -> Option<&'a str> {
    inner
        .client_environments
        .get(&client)?
        .get(name)
        .map(String::as_str)
}

fn client_uses_utf8(inner: &ServerState, client: ClientId) -> bool {
    if client_environment_value(inner, client, "TMUX").is_some_and(|value| !value.is_empty()) {
        return true;
    }
    ["LC_ALL", "LC_CTYPE", "LANG"]
        .into_iter()
        .find_map(|name| {
            client_environment_value(inner, client, name).filter(|value| !value.is_empty())
        })
        .is_some_and(|locale| {
            let locale = locale.to_ascii_lowercase();
            locale.contains("utf-8") || locale.contains("utf8")
        })
}

fn client_colour_count(inner: &ServerState, client: ClientId) -> Option<u32> {
    if inner.client_kinds.get(&client) != Some(&ClientKind::Interactive)
        || !inner.client_terminals.contains(&client)
    {
        return None;
    }
    let term = client_environment_value(inner, client, "TERM").unwrap_or_default();
    let colour_term = client_environment_value(inner, client, "COLORTERM")
        .unwrap_or_default()
        .to_ascii_lowercase();
    if matches!(colour_term.as_str(), "truecolor" | "24bit")
        || term.to_ascii_lowercase().contains("truecolor")
    {
        Some(16_777_216)
    } else if term.to_ascii_lowercase().contains("256color") {
        Some(256)
    } else if term == "dumb" {
        Some(2)
    } else {
        Some(16)
    }
}

fn client_term_features(inner: &ServerState, client: ClientId) -> String {
    let Some(colours) = client_colour_count(inner, client) else {
        return String::new();
    };
    let mut features = Vec::new();
    if colours >= 256 {
        features.push("256");
    }
    features.extend([
        "bpaste",
        "ccolour",
        "clipboard",
        "hyperlinks",
        "cstyle",
        "extkeys",
        "focus",
        "mouse",
        "osc7",
        "overline",
    ]);
    if colours == 16_777_216 {
        features.push("RGB");
    }
    features.extend(["strikethrough", "sync", "title", "usstyle"]);
    features.join(",")
}

fn client_format_geometry(
    inner: &ServerState,
    client: ClientId,
    window: WindowId,
) -> Option<TerminalGeometry> {
    let pane = inner.engine.state.windows.get(&window)?.active_pane;
    inner
        .terminal_geometries
        .get(&pane)
        .and_then(|geometries| geometries.get(&client))
        .copied()
        .or_else(|| {
            inner
                .terminal_geometries
                .values()
                .find_map(|geometries| geometries.get(&client).copied())
        })
}

fn client_format_time(time: Option<u64>) -> String {
    time.filter(|time| *time != 0)
        .map_or_else(String::new, |time| time.to_string())
}

fn client_ignores_size(inner: &ServerState, client: ClientId) -> bool {
    inner.client_flags.get(client).ignore_size
}

fn unignored_attached_sizing_client_exists(inner: &ServerState) -> bool {
    inner.attached.values().flatten().any(|client| {
        matches!(
            inner.client_kinds.get(client),
            Some(ClientKind::Interactive | ClientKind::Control)
        ) && !client_ignores_size(inner, *client)
    })
}

fn client_is_sizing_candidate(
    inner: &ServerState,
    client: ClientId,
    suppress_ignored: bool,
) -> bool {
    matches!(
        inner.client_kinds.get(&client),
        Some(ClientKind::Interactive | ClientKind::Control)
    ) && (!suppress_ignored || !client_ignores_size(inner, client))
}

fn interactive_client_window_extent(
    inner: &ServerState,
    client: ClientId,
    session: SessionId,
    window: WindowId,
) -> Option<(u16, u16)> {
    if let Some((columns, rows)) = inner.client_sizes.get(&client).copied() {
        let status = inner.engine.status_formats_for_session(Some(session));
        let status_rows = if status.enabled {
            u16::from(status.lines).min(rows.saturating_sub(1))
        } else {
            0
        };
        return Some((columns.max(1), rows.saturating_sub(status_rows).max(1)));
    }
    let window_state = inner.engine.state.windows.get(&window)?;
    std::iter::once(window_state.active_pane)
        .chain(
            window_state
                .panes
                .keys()
                .copied()
                .filter(|pane| *pane != window_state.active_pane),
        )
        .find_map(|pane| {
            let geometry = inner.terminal_geometries.get(&pane)?.get(&client)?;
            inner
                .engine
                .window_extent_for_pane_geometry(pane, geometry.columns, geometry.rows)
        })
}

fn attached_client_window_extent(
    inner: &ServerState,
    window: WindowId,
    mode: WindowSize,
) -> Option<(u16, u16)> {
    let window_state = inner.engine.state.windows.get(&window)?;
    let session = window_state.session;
    let suppress_ignored = unignored_attached_sizing_client_exists(inner);
    let mut candidates = Vec::new();
    let mut ceilings = Vec::new();
    for client in inner.attached.get(&session).into_iter().flatten().copied() {
        if !client_is_sizing_candidate(inner, client, suppress_ignored) {
            continue;
        }
        let extent = match inner.client_kinds.get(&client) {
            Some(ClientKind::Interactive) => {
                interactive_client_window_extent(inner, client, session, window)
            }
            Some(ClientKind::Control) => {
                let output = inner.control_outputs.get(&client);
                if let Some(geometry) =
                    output.and_then(|output| output.window_geometries.get(&window).copied())
                {
                    ceilings.push((geometry.columns, geometry.rows));
                    Some((geometry.columns, geometry.rows))
                } else {
                    output
                        .and_then(|output| output.geometry)
                        .map(|geometry| (geometry.columns, geometry.rows))
                }
            }
            Some(ClientKind::Command) | None => None,
        };
        if let Some(extent) = extent {
            candidates.push(extent);
        }
    }
    let mut extent = candidates.into_iter().reduce(|left, right| {
        if mode == WindowSize::Smallest {
            (left.0.min(right.0), left.1.min(right.1))
        } else {
            (left.0.max(right.0), left.1.max(right.1))
        }
    });
    if extent.is_none() {
        extent = Some(inner.engine.default_size_for_session(session));
    }
    let (mut columns, mut rows) = extent?;
    for (ceiling_columns, ceiling_rows) in ceilings {
        columns = columns.min(ceiling_columns);
        rows = rows.min(ceiling_rows);
    }
    Some((
        columns.clamp(1, WINDOW_SIZE_MAXIMUM),
        rows.clamp(1, WINDOW_SIZE_MAXIMUM),
    ))
}

fn control_client_geometry(
    inner: &ServerState,
    client: ClientId,
    window: WindowId,
) -> Option<TerminalGeometry> {
    let output = inner.control_outputs.get(&client)?;
    output
        .window_geometries
        .get(&window)
        .copied()
        .or(output.geometry)
}

fn control_client_sized_panes(inner: &ServerState, client: ClientId) -> BTreeSet<PaneId> {
    let Some(session) = client_attached_session(inner, client)
        .and_then(|session| inner.engine.state.sessions.get(&session))
    else {
        return BTreeSet::new();
    };
    let Some(output) = inner.control_outputs.get(&client) else {
        return BTreeSet::new();
    };
    session
        .windows
        .iter()
        .filter(|window| output.geometry.is_some() || output.window_geometries.contains_key(window))
        .filter_map(|window| inner.engine.state.windows.get(window))
        .flat_map(|window| window.panes.keys().copied())
        .collect()
}

fn client_format_facts(
    inner: &ServerState,
    client: ClientId,
    session: SessionId,
) -> ClientFormatFacts {
    let session_state = &inner.engine.state.sessions[&session];
    let window = client_focused_window(inner, client, session_state);
    let kind = inner.client_kinds.get(&client).copied();
    let has_terminal =
        kind == Some(ClientKind::Interactive) && inner.client_terminals.contains(&client);
    let control_geometry = (kind == Some(ClientKind::Control))
        .then(|| control_client_geometry(inner, client, window))
        .flatten();
    let terminal_geometry = has_terminal
        .then(|| client_format_geometry(inner, client, window))
        .flatten();
    let retained_size = inner.client_sizes.get(&client).copied();
    let width = if kind == Some(ClientKind::Control) {
        control_geometry.map_or(80, |geometry| geometry.columns)
    } else {
        retained_size.map_or(80, |size| size.0)
    };
    let height = has_terminal.then(|| retained_size.map_or(24, |size| size.1));
    let format_context = inner
        .engine
        .format_status_context(Some(session), Some(window), None);
    let tty = inner.client_ttys.get(&client).cloned().unwrap_or_default();
    let pid = inner.client_pids.get(&client).copied().unwrap_or_default();
    let name = client_format_name(inner, client);
    let default_key_table = inner.engine.key_table_for_session(session);
    let key_table = inner
        .key_engines
        .get(&client)
        .and_then(KeyEngine::active_table)
        .unwrap_or(default_key_table.as_str())
        .to_owned();
    let prefix = usize::from(key_table != default_key_table).to_string();
    let (written, discarded) = inner
        .subscribers
        .get(&client)
        .map_or((0, 0), |subscriber| subscriber.stats());
    let colours = client_colour_count(inner, client);
    ClientFormatFacts {
        activity: client_format_time(inner.client_activity_times.get(&client).copied()),
        cell_height: terminal_geometry
            .map_or_else(
                || has_terminal.then_some(0),
                |geometry| Some(geometry.cell_height_px),
            )
            .map_or_else(String::new, |height| height.to_string()),
        cell_width: terminal_geometry
            .map_or_else(
                || has_terminal.then_some(0),
                |geometry| Some(geometry.cell_width_px),
            )
            .map_or_else(String::new, |width| width.to_string()),
        colours: colours.map_or_else(String::new, |colours| colours.to_string()),
        control_mode: usize::from(kind == Some(ClientKind::Control)).to_string(),
        created: client_format_time(inner.client_created_times.get(&client).copied()),
        discarded: discarded.to_string(),
        flags: format_client_flags(inner, client),
        height: height.map_or_else(String::new, |height| height.to_string()),
        key_table,
        last_session: inner
            .last_sessions
            .get(&client)
            .and_then(|last| inner.engine.state.sessions.get(last))
            .map(|session| session.name.clone())
            .unwrap_or_default(),
        name,
        pid: if pid == 0 {
            String::new()
        } else {
            pid.to_string()
        },
        prefix,
        readonly: usize::from(inner.client_flags.contains(client)).to_string(),
        session: session_state.name.clone(),
        termfeatures: client_term_features(inner, client),
        termname: client_environment_value(inner, client, "TERM")
            .filter(|term| !term.is_empty())
            .unwrap_or("unknown")
            .to_owned(),
        termtype: String::new(),
        theme: inner
            .client_color_schemes
            .get(&client)
            .map(|scheme| scheme.as_str().to_owned())
            .unwrap_or_default(),
        tty,
        uid: format_context.uid,
        user: format_context.user,
        utf8: usize::from(client_uses_utf8(inner, client)).to_string(),
        width: width.to_string(),
        written: written.to_string(),
        line: 0,
        environment: client_environment_rows(inner.client_environments.get(&client)),
    }
}

fn client_format_name(inner: &ServerState, client: ClientId) -> String {
    inner
        .client_ttys
        .get(&client)
        .filter(|tty| !tty.is_empty())
        .cloned()
        .or_else(|| {
            inner
                .client_names
                .get(&client)
                .filter(|name| !name.is_empty())
                .cloned()
        })
        .unwrap_or_else(|| {
            let pid = inner.client_pids.get(&client).copied().unwrap_or_default();
            if pid == 0 {
                format!("device-{}", client.0)
            } else {
                format!("client-{pid}")
            }
        })
}

fn client_focused_window(
    inner: &ServerState,
    client: ClientId,
    session: &zz_mux::Session,
) -> WindowId {
    inner
        .focused_windows
        .get(&client)
        .copied()
        .filter(|focused| session.windows.contains(focused))
        .unwrap_or(session.active_window)
}

fn client_focused_window_for_attachment(inner: &ServerState, client: ClientId) -> Option<WindowId> {
    client_attached_session(inner, client)
        .and_then(|session| inner.engine.state.sessions.get(&session))
        .map(|session| client_focused_window(inner, client, session))
}

fn client_hook_event_for_window(
    inner: &ServerState,
    name: &'static str,
    client: ClientId,
    window: WindowId,
) -> Option<PendingHookEvent> {
    let session = client_attached_session(inner, client)?;
    let window_state = inner.engine.state.windows.get(&window)?;
    if window_state.session != session {
        return None;
    }
    let pane = window_state.active_pane;
    let client_name = client_format_name(inner, client);
    Some(PendingHookEvent::client(
        name,
        ExecutionContext::new(Some(session), Some(window), Some(pane)),
        client,
        Some(client_name.as_str()),
    ))
}

fn client_hook_event(
    inner: &ServerState,
    name: &'static str,
    client: ClientId,
) -> Option<PendingHookEvent> {
    let window = client_focused_window_for_attachment(inner, client)?;
    client_hook_event_for_window(inner, name, client, window)
}

fn set_window_latest_client(
    inner: &mut ServerState,
    client: ClientId,
    window: WindowId,
    event_hooks_enabled: bool,
) -> Option<PendingHookEvent> {
    let session = client_attached_session(inner, client)?;
    if inner.engine.state.windows.get(&window)?.session != session {
        return None;
    }
    if inner.window_latest_clients.insert(window, client) == Some(client) {
        return None;
    }
    event_hooks_enabled
        .then(|| client_hook_event_for_window(inner, "client-active", client, window))
        .flatten()
}

fn set_current_window_latest_client(
    inner: &mut ServerState,
    client: ClientId,
    event_hooks_enabled: bool,
) -> Option<PendingHookEvent> {
    let window = client_focused_window_for_attachment(inner, client)?;
    set_window_latest_client(inner, client, window, event_hooks_enabled)
}

fn promote_window_latest_clients(
    inner: &mut ServerState,
    detached: ClientId,
    event_hooks_enabled: bool,
) -> Vec<PendingHookEvent> {
    let windows = inner
        .window_latest_clients
        .iter()
        .filter_map(|(window, client)| (*client == detached).then_some(*window))
        .collect::<Vec<_>>();
    let mut events = Vec::new();
    for window in windows {
        let survivor = inner
            .engine
            .state
            .windows
            .get(&window)
            .and_then(|window_state| inner.attached.get(&window_state.session))
            .into_iter()
            .flatten()
            .filter(|client| client_focused_window_for_attachment(inner, **client) == Some(window))
            .copied()
            .max_by_key(|client| {
                (
                    inner
                        .client_activity
                        .get(client)
                        .copied()
                        .unwrap_or_default(),
                    Reverse(client.0),
                )
            });
        if let Some(survivor) = survivor {
            inner.window_latest_clients.insert(window, survivor);
            if event_hooks_enabled
                && let Some(event) =
                    client_hook_event_for_window(inner, "client-active", survivor, window)
            {
                events.push(event);
            }
        } else {
            inner.window_latest_clients.remove(&window);
        }
    }
    events
}

fn client_input_pane(
    inner: &ServerState,
    client: ClientId,
    preferred: Option<PaneId>,
) -> Option<PaneId> {
    preferred
        .filter(|pane| client_is_attached_to_pane(inner, client, *pane))
        .or_else(|| {
            client_focused_window_for_attachment(inner, client)
                .and_then(|window| inner.engine.state.windows.get(&window))
                .map(|window| window.active_pane)
        })
}

fn status_request(
    inner: &ServerState,
    client: ClientId,
    snapshot: &MuxSnapshot,
    option_snapshot: Arc<zz_mux::StatusRowVariables>,
    facts: FormatHookFacts,
    startup_ready: bool,
) -> StatusRequest {
    let attached = client_attached_session(inner, client);
    let mut facts = facts;
    facts.client_environment = Arc::new(client_environment_rows(
        inner.client_environments.get(&client),
    ));
    if let Some(session) = attached {
        facts.client = Some(client_format_facts(inner, client, session));
    }
    let mut context = status_context(
        snapshot,
        &inner.engine,
        attached,
        client_focused_window_for_attachment(inner, client),
    );
    context.config_files.clone_from(&inner.config_files);
    StatusRequest {
        client,
        formats: inner.engine.status_formats_for_session(attached),
        row_formats: inner.engine.status_format_array_for_session(attached),
        option_snapshot,
        message_line: inner.engine.message_line_for_session(attached),
        customized: inner.engine.status_customized_for_session(attached),
        title_format: (attached.is_some() && inner.engine.set_titles_for_session(attached))
            .then(|| inner.engine.set_titles_string_for_session(attached)),
        environment: inner.engine.job_environment(None),
        default_terminal: inner.engine.default_terminal_for_spawn().to_owned(),
        startup: !startup_ready,
        context,
        facts,
    }
}

fn resolve_popup_client(
    inner: &ServerState,
    invoking_client: ClientId,
    context: &ExecutionContext,
    target: Option<&str>,
) -> Result<ClientId, ServerError> {
    let eligible = inner
        .subscribers
        .keys()
        .copied()
        .filter(|client| client_attached_session(inner, *client).is_some())
        .collect::<Vec<_>>();
    if let Some(target) = target {
        return find_attached_client_with_aliases(inner, target, true)
            .ok_or_else(|| client_target_error(target));
    }
    if eligible.contains(&invoking_client) {
        return Ok(invoking_client);
    }
    if let Some(owner) = context
        .pane
        .and_then(|pane| terminal_geometry_owner(inner, pane))
        && eligible.contains(&owner)
    {
        return Ok(owner);
    }
    eligible
        .into_iter()
        .next()
        .ok_or_else(|| ServerError::InvalidCommand("no current client".to_owned()))
}

fn resolve_attached_client(
    inner: &ServerState,
    invoking_client: ClientId,
    target: Option<&str>,
) -> Result<ClientId, ServerError> {
    let attached = inner
        .attached
        .values()
        .flat_map(BTreeSet::iter)
        .copied()
        .collect::<BTreeSet<_>>();
    if let Some(target) = target {
        return find_attached_client_with_aliases(inner, target, true)
            .ok_or_else(|| client_target_error(target));
    }
    attached
        .contains(&invoking_client)
        .then_some(invoking_client)
        .ok_or_else(|| ServerError::InvalidCommand("no current client".to_owned()))
}

fn popup_client_geometry(
    inner: &ServerState,
    client: ClientId,
) -> Result<Option<TerminalGeometry>, ServerError> {
    let session_id = client_attached_session(inner, client)
        .ok_or_else(|| ServerError::InvalidCommand("no current client".to_owned()))?;
    let session = inner
        .engine
        .state
        .sessions
        .get(&session_id)
        .ok_or_else(|| ServerError::MissingTarget(session_id.to_string()))?;
    let window_id = client_focused_window(inner, client, session);
    if inner.client_kinds.get(&client) == Some(&ClientKind::Control) {
        return Ok(control_client_geometry(inner, client, window_id));
    }
    let window = inner
        .engine
        .state
        .windows
        .get(&window_id)
        .ok_or_else(|| ServerError::MissingTarget(window_id.to_string()))?;
    let pane = window.active_pane;
    let measured = inner
        .terminal_geometries
        .get(&pane)
        .and_then(|geometries| geometries.get(&client))
        .copied();
    let columns = inner
        .engine
        .window_extent(window_id, zz_protocol::Axis::Horizontal)
        .unwrap_or(80);
    let rows = inner
        .engine
        .window_extent(window_id, zz_protocol::Axis::Vertical)
        .unwrap_or(24);
    Ok(Some(measured.map_or(
        TerminalGeometry {
            columns,
            rows,
            cell_width_px: CONTROL_CELL_WIDTH_PX,
            cell_height_px: CONTROL_CELL_HEIGHT_PX,
        },
        |geometry| TerminalGeometry {
            columns,
            rows,
            ..geometry
        },
    )))
}

const POPUP_CENTRE_X_CONTEXT_FORMAT: &str = "popup_centre_x";
const POPUP_CENTRE_Y_CONTEXT_FORMAT: &str = "popup_centre_y";
const POPUP_HEIGHT_CONTEXT_FORMAT: &str = "popup_height";
const POPUP_LAST_X_CONTEXT_FORMAT: &str = "popup_last_x";
const POPUP_LAST_Y_CONTEXT_FORMAT: &str = "popup_last_y";
const POPUP_MOUSE_BOTTOM_CONTEXT_FORMAT: &str = "popup_mouse_bottom";
const POPUP_MOUSE_CENTRE_X_CONTEXT_FORMAT: &str = "popup_mouse_centre_x";
const POPUP_MOUSE_CENTRE_Y_CONTEXT_FORMAT: &str = "popup_mouse_centre_y";
const POPUP_MOUSE_TOP_CONTEXT_FORMAT: &str = "popup_mouse_top";
const POPUP_MOUSE_X_CONTEXT_FORMAT: &str = "popup_mouse_x";
const POPUP_MOUSE_Y_CONTEXT_FORMAT: &str = "popup_mouse_y";
const POPUP_PANE_BOTTOM_CONTEXT_FORMAT: &str = "popup_pane_bottom";
const POPUP_PANE_LEFT_CONTEXT_FORMAT: &str = "popup_pane_left";
const POPUP_PANE_RIGHT_CONTEXT_FORMAT: &str = "popup_pane_right";
const POPUP_PANE_TOP_CONTEXT_FORMAT: &str = "popup_pane_top";
const POPUP_STATUS_LINE_Y_CONTEXT_FORMAT: &str = "popup_status_line_y";
const POPUP_WIDTH_CONTEXT_FORMAT: &str = "popup_width";
const POPUP_WINDOW_STATUS_LINE_X_CONTEXT_FORMAT: &str = "popup_window_status_line_x";
const POPUP_WINDOW_STATUS_LINE_Y_CONTEXT_FORMAT: &str = "popup_window_status_line_y";
#[cfg(test)]
const POPUP_POSITION_CONTEXT_FORMATS: [&str; 19] = [
    POPUP_CENTRE_X_CONTEXT_FORMAT,
    POPUP_CENTRE_Y_CONTEXT_FORMAT,
    POPUP_HEIGHT_CONTEXT_FORMAT,
    POPUP_LAST_X_CONTEXT_FORMAT,
    POPUP_LAST_Y_CONTEXT_FORMAT,
    POPUP_MOUSE_BOTTOM_CONTEXT_FORMAT,
    POPUP_MOUSE_CENTRE_X_CONTEXT_FORMAT,
    POPUP_MOUSE_CENTRE_Y_CONTEXT_FORMAT,
    POPUP_MOUSE_TOP_CONTEXT_FORMAT,
    POPUP_MOUSE_X_CONTEXT_FORMAT,
    POPUP_MOUSE_Y_CONTEXT_FORMAT,
    POPUP_PANE_BOTTOM_CONTEXT_FORMAT,
    POPUP_PANE_LEFT_CONTEXT_FORMAT,
    POPUP_PANE_RIGHT_CONTEXT_FORMAT,
    POPUP_PANE_TOP_CONTEXT_FORMAT,
    POPUP_STATUS_LINE_Y_CONTEXT_FORMAT,
    POPUP_WIDTH_CONTEXT_FORMAT,
    POPUP_WINDOW_STATUS_LINE_X_CONTEXT_FORMAT,
    POPUP_WINDOW_STATUS_LINE_Y_CONTEXT_FORMAT,
];

fn popup_position_variables(
    engine: &MuxEngine,
    target: &ExecutionContext,
    columns: u16,
    rows: u16,
    width: u16,
    height: u16,
) -> BTreeMap<String, String> {
    let status = engine.format_status_context(target.session, target.window, target.pane);
    let centre_x = i64::from(columns.saturating_sub(1)) / 2 - i64::from(width) / 2;
    let centre_x = centre_x.max(0);
    let centre_y = i64::from(rows.saturating_sub(1)) / 2 + i64::from(height) / 2;
    let centre_y = if centre_y >= i64::from(rows) {
        i64::from(rows.saturating_sub(height))
    } else {
        centre_y
    };
    let pane_left = status.pane_left.unwrap_or_default();
    let pane_top = status.pane_top.unwrap_or_default();
    let pane_width = status.pane_width.unwrap_or(columns);
    let pane_height = status.pane_height.unwrap_or(rows);
    let pane_popup_top = i64::from(pane_top) + i64::from(height);
    let pane_popup_top = if pane_popup_top >= i64::from(rows) {
        i64::from(rows.saturating_sub(height))
    } else {
        pane_popup_top
    };
    let pane_right = i64::from(pane_left) + i64::from(pane_width) - i64::from(width);
    let mut variables = BTreeMap::from([
        (POPUP_WIDTH_CONTEXT_FORMAT.to_owned(), width.to_string()),
        (POPUP_HEIGHT_CONTEXT_FORMAT.to_owned(), height.to_string()),
        (
            POPUP_CENTRE_X_CONTEXT_FORMAT.to_owned(),
            centre_x.to_string(),
        ),
        (
            POPUP_CENTRE_Y_CONTEXT_FORMAT.to_owned(),
            centre_y.to_string(),
        ),
        (
            POPUP_PANE_TOP_CONTEXT_FORMAT.to_owned(),
            pane_popup_top.to_string(),
        ),
        (
            POPUP_PANE_BOTTOM_CONTEXT_FORMAT.to_owned(),
            pane_top.saturating_add(pane_height).to_string(),
        ),
        (
            POPUP_PANE_LEFT_CONTEXT_FORMAT.to_owned(),
            pane_left.to_string(),
        ),
        (
            POPUP_PANE_RIGHT_CONTEXT_FORMAT.to_owned(),
            pane_right.max(0).to_string(),
        ),
        (POPUP_LAST_X_CONTEXT_FORMAT.to_owned(), "0".to_owned()),
        (POPUP_LAST_Y_CONTEXT_FORMAT.to_owned(), height.to_string()),
    ]);
    for (name, value) in [
        (POPUP_MOUSE_X_CONTEXT_FORMAT, i64::from(columns) / 2),
        (POPUP_MOUSE_Y_CONTEXT_FORMAT, i64::from(rows) / 2),
        (POPUP_MOUSE_CENTRE_X_CONTEXT_FORMAT, centre_x),
        (POPUP_MOUSE_CENTRE_Y_CONTEXT_FORMAT, centre_y),
        (POPUP_MOUSE_TOP_CONTEXT_FORMAT, centre_y),
        (POPUP_MOUSE_BOTTOM_CONTEXT_FORMAT, centre_y),
        (POPUP_STATUS_LINE_Y_CONTEXT_FORMAT, centre_y),
        (POPUP_WINDOW_STATUS_LINE_X_CONTEXT_FORMAT, centre_x),
        (POPUP_WINDOW_STATUS_LINE_Y_CONTEXT_FORMAT, centre_y),
    ] {
        variables.insert(name.to_owned(), value.to_string());
    }
    variables
}

fn popup_position(
    x: Option<&str>,
    y: Option<&str>,
    columns: u16,
    rows: u16,
    width: u16,
    height: u16,
    mut expand: impl FnMut(&str) -> String,
) -> (u16, u16) {
    let x = match x.unwrap_or("C") {
        "C" => "#{popup_centre_x}",
        "R" => "#{popup_pane_right}",
        "P" => "#{popup_pane_left}",
        "M" => "#{popup_mouse_centre_x}",
        "L" => "#{popup_last_x}",
        "W" => "#{popup_window_status_line_x}",
        value => value,
    };
    let y = match y.unwrap_or("C") {
        "C" => "#{popup_centre_y}",
        "P" => "#{popup_pane_bottom}",
        "M" => "#{popup_mouse_top}",
        "L" => "#{popup_last_y}",
        "S" => "#{popup_status_line_y}",
        "W" => "#{popup_window_status_line_y}",
        value => value,
    };
    let left = popup_position_value(&expand(x), columns);
    let left = left.clamp(0, i64::from(columns.saturating_sub(width)));
    let bottom = popup_position_value(&expand(y), rows);
    let top = if bottom < i64::from(height) {
        0
    } else {
        bottom - i64::from(height)
    };
    let top = top.clamp(0, i64::from(rows.saturating_sub(height)));
    (
        u16::try_from(left).unwrap_or_default(),
        u16::try_from(top).unwrap_or_default(),
    )
}

fn popup_position_value(value: &str, dimension: u16) -> i64 {
    if let Some(percent) = value.strip_suffix('%') {
        let percent = percent.parse::<u64>().unwrap_or_default();
        return i64::try_from(
            u64::from(dimension)
                .saturating_mul(percent)
                .checked_div(100)
                .unwrap_or_default(),
        )
        .unwrap_or(i64::MAX);
    }
    value.parse().unwrap_or_default()
}

type SnapshotPresence = BTreeMap<SessionId, Vec<(ClientId, SessionViewer)>>;

fn snapshot_presence(inner: &ServerState) -> SnapshotPresence {
    inner
        .attached
        .iter()
        .filter_map(|(session, clients)| {
            let session_state = inner.engine.state.sessions.get(session)?;
            let viewers = clients
                .iter()
                .map(|client| {
                    let name = if inner.client_kinds.get(client) == Some(&ClientKind::Control) {
                        client_format_name(inner, *client)
                    } else {
                        inner
                            .client_names
                            .get(client)
                            .filter(|name| !name.is_empty())
                            .cloned()
                            .unwrap_or_else(|| format!("device-{}", client.0))
                    };
                    (
                        *client,
                        SessionViewer {
                            name,
                            window: client_focused_window(inner, *client, session_state),
                            is_self: false,
                        },
                    )
                })
                .collect();
            Some((*session, viewers))
        })
        .collect()
}

fn stamp_snapshot_for_client(
    inner: &ServerState,
    client: ClientId,
    snapshot: &mut MuxSnapshot,
    presence: &SnapshotPresence,
) {
    snapshot.focused_window = client_focused_window_for_attachment(inner, client);
    for session in &mut snapshot.sessions {
        session.viewers = presence
            .get(&session.id)
            .into_iter()
            .flatten()
            .map(|(viewer_client, viewer)| SessionViewer {
                is_self: *viewer_client == client,
                ..viewer.clone()
            })
            .collect();
    }
    let facts = format_hook_facts(inner);
    let format_client = client_attached_session(inner, client)
        .map_or(FormatClient::Unattached, FormatClient::Attached);
    expand_window_status_labels(
        &inner.engine,
        &inner.config_files,
        &facts,
        format_client,
        snapshot,
    );
    stamp_pane_border_colours(
        &inner.engine,
        &inner.config_files,
        &facts,
        format_client,
        snapshot,
    );
}

fn stamp_pane_border_colours(
    engine: &MuxEngine,
    config_files: &str,
    facts: &FormatHookFacts,
    format_client: FormatClient,
    snapshot: &mut MuxSnapshot,
) {
    if !engine.has_pane_border_style_settings() {
        return;
    }
    let resolve = |value: Option<String>, session, window, pane| {
        let value = value?;
        let context = server_format_context_with_format_client(
            engine,
            config_files,
            Some(session),
            Some(window),
            Some(pane),
            Some(session),
            format_client,
        );
        let mut hooks = DaemonFormatHooks::command(facts).with_option_engine(engine);
        let expanded = if value.contains("#{") {
            expand_format_values(&value, &context, &mut hooks)
        } else {
            value
        };
        zz_protocol::parse_style(&expanded)?.fg
    };
    for session in &mut snapshot.sessions {
        for window in &mut session.windows {
            for (pane, pane_snapshot) in &mut window.panes {
                let styles = engine.pane_border_style_values(*pane);
                pane_snapshot.border_colour = resolve(styles.border, session.id, window.id, *pane);
                pane_snapshot.active_border_colour =
                    resolve(styles.active_border, session.id, window.id, *pane);
            }
        }
    }
}

fn expand_window_status_labels(
    engine: &MuxEngine,
    config_files: &str,
    facts: &FormatHookFacts,
    format_client: FormatClient,
    snapshot: &mut MuxSnapshot,
) {
    for session in &mut snapshot.sessions {
        for window in &mut session.windows {
            let formats = engine.window_status_formats(window.id);
            let format = if window.id == session.active_window {
                &formats.current_format
            } else {
                &formats.format
            };
            let context = server_format_context_with_format_client(
                engine,
                config_files,
                Some(session.id),
                Some(window.id),
                Some(window.active_pane),
                Some(session.id),
                format_client,
            );
            let mut hooks = DaemonFormatHooks::command(facts).with_option_engine(engine);
            let style = expand_window_status_style(&formats, &context, &mut hooks);
            let label = expand_status(format, &context, &mut hooks);
            window.status_label =
                truncate_window_status_label(format!("#[{style}]#[push-default]{label}"));
        }
    }
}

fn expand_window_status_style(
    formats: &zz_mux::WindowStatusFormats,
    context: &zz_mux::StatusContext,
    hooks: &mut DaemonFormatHooks<'_>,
) -> String {
    let mut style = if context.window_active == Some(true) {
        let current = expand_status(&formats.current_style, context, hooks);
        if current == "default" {
            expand_status(&formats.style, context, hooks)
        } else {
            current
        }
    } else {
        expand_status(&formats.style, context, hooks)
    };
    if context.window_last == Some(true) {
        let last = expand_status(&formats.last_style, context, hooks);
        append_window_status_style(&mut style, &last);
    }
    let mut bell_styled = false;
    if context.window_bell {
        let bell = expand_status(&formats.bell_style, context, hooks);
        if bell != "default" && !bell.is_empty() {
            append_window_status_style(&mut style, &bell);
            bell_styled = true;
        }
    }
    if !bell_styled && (context.window_activity_alert || context.window_silence_alert) {
        let activity = expand_status(&formats.activity_style, context, hooks);
        append_window_status_style(&mut style, &activity);
    }
    style
}

fn append_window_status_style(style: &mut String, layer: &str) {
    if layer == "default" || layer.is_empty() {
        return;
    }
    if !style.is_empty() {
        style.push(' ');
    }
    style.push_str(layer);
}

fn truncate_window_status_label(mut label: String) -> String {
    if label.len() <= MAX_WINDOW_STATUS_LABEL_BYTES {
        return label;
    }
    let boundary = (0..=MAX_WINDOW_STATUS_LABEL_BYTES)
        .rev()
        .find(|index| label.is_char_boundary(*index))
        .unwrap_or_default();
    label.truncate(boundary);
    label
}

fn truncate_pane_indicator_label(mut label: String) -> String {
    if label.len() <= MAX_PANE_INDICATOR_LABEL_BYTES {
        return label;
    }
    let boundary = (0..=MAX_PANE_INDICATOR_LABEL_BYTES)
        .rev()
        .find(|index| label.is_char_boundary(*index))
        .unwrap_or_default();
    label.truncate(boundary);
    label
}

/// `prompt_key`'s three head branches, taken before any editing: `-k` answers
/// with the key's own name, `-N` collects digits and hands the first non-digit
/// back to the key tables, and `-1` folds one key into a character and submits
/// it — with the pin's quirk that a buffer seeded by `-I` can never be one
/// character long, so the prompt closes with nothing submitted.
fn command_prompt_raw_key(
    prompt: &mut CommandPrompt,
    input: &zz_terminal::KeyInput,
) -> PromptKeyAction {
    // The pin has no platform modifier, and `input_key_name` spells such a
    // chord as nothing at all, so a raw mode must not answer with it.
    if input.modifiers.platform() {
        return PromptKeyAction::Handled;
    }
    match prompt.mode {
        CommandPromptMode::Key => {
            PromptKeyAction::SubmitAnswer(input_key_name(input).into_string())
        }
        CommandPromptMode::Numeric => match input.key {
            zz_terminal::KeyCode::Character(character)
                if character.is_ascii_digit()
                    && !input.modifiers.control()
                    && !input.modifiers.alt() =>
            {
                let mut encoded = [0_u8; 4];
                if prompt.insert(character.encode_utf8(&mut encoded)) {
                    PromptKeyAction::Updated
                } else {
                    PromptKeyAction::LimitExceeded
                }
            }
            _ => PromptKeyAction::SubmitAndPass,
        },
        _ => {
            let Some(character) = single_key_character(input) else {
                return PromptKeyAction::Handled;
            };
            let mut encoded = [0_u8; 4];
            if !prompt.insert(character.encode_utf8(&mut encoded)) {
                return PromptKeyAction::LimitExceeded;
            }
            if prompt.input.chars().count() == 1 {
                PromptKeyAction::SubmitAnswer(prompt.input.clone())
            } else {
                PromptKeyAction::Close
            }
        }
    }
}

/// `prompt_key`'s `PROMPT_SINGLE` normalisation: backspace becomes `DEL`, a
/// control chord masks down to `0x1f`, and anything the pin cannot squeeze into
/// one character (arrows, function keys) leaves the prompt untouched.
fn single_key_character(input: &zz_terminal::KeyInput) -> Option<char> {
    match input.key {
        zz_terminal::KeyCode::Backspace => Some('\u{7f}'),
        zz_terminal::KeyCode::Escape => Some('\u{1b}'),
        zz_terminal::KeyCode::Enter => Some('\r'),
        zz_terminal::KeyCode::Tab => Some('\t'),
        zz_terminal::KeyCode::Character(character) if input.modifiers.control() => character
            .is_ascii()
            .then(|| char::from(character.to_ascii_uppercase() as u8 & 0x1f)),
        zz_terminal::KeyCode::Character(character) => Some(
            if input.modifiers.shift() && character.is_ascii_lowercase() {
                character.to_ascii_uppercase()
            } else {
                character
            },
        ),
        _ => None,
    }
}

fn command_prompt_key(
    prompt: &mut CommandPrompt,
    input: &zz_terminal::KeyInput,
    text_follows: bool,
    history: &[String],
) -> PromptKeyAction {
    if input.action == zz_terminal::KeyAction::Release {
        return PromptKeyAction::Handled;
    }
    if prompt.reads_raw_keys() {
        return command_prompt_raw_key(prompt, input);
    }
    let incremental = prompt.mode == CommandPromptMode::Incremental;
    if incremental
        && matches!(
            input.key,
            zz_terminal::KeyCode::ArrowUp
                | zz_terminal::KeyCode::ArrowDown
                | zz_terminal::KeyCode::PageUp
                | zz_terminal::KeyCode::PageDown
        )
    {
        return PromptKeyAction::Close;
    }
    let action = command_prompt_edit_key(prompt, input, text_follows, history);
    match action {
        PromptKeyAction::Updated if incremental => PromptKeyAction::Incremental('='),
        PromptKeyAction::Submit if incremental => PromptKeyAction::SubmitIncremental,
        other => other,
    }
}

fn command_prompt_edit_key(
    prompt: &mut CommandPrompt,
    input: &zz_terminal::KeyInput,
    text_follows: bool,
    history: &[String],
) -> PromptKeyAction {
    let changed = |changed| {
        if changed {
            PromptKeyAction::Updated
        } else {
            PromptKeyAction::Handled
        }
    };
    let control = input.modifiers.control();
    let alt = input.modifiers.alt();
    let platform = input.modifiers.platform();

    let backspace = |prompt: &mut CommandPrompt| {
        if prompt.mode == CommandPromptMode::BackspaceExit && prompt.input.is_empty() {
            PromptKeyAction::Close
        } else {
            changed(prompt.delete_backward())
        }
    };

    match input.key {
        zz_terminal::KeyCode::Enter => PromptKeyAction::Submit,
        zz_terminal::KeyCode::Escape => PromptKeyAction::Close,
        zz_terminal::KeyCode::Backspace => backspace(prompt),
        zz_terminal::KeyCode::Delete => changed(prompt.delete_forward()),
        zz_terminal::KeyCode::Home => changed({
            let changed = prompt.cursor != 0;
            prompt.cursor = 0;
            changed
        }),
        zz_terminal::KeyCode::End => changed({
            let changed = prompt.cursor != prompt.input.len();
            prompt.cursor = prompt.input.len();
            changed
        }),
        zz_terminal::KeyCode::ArrowLeft if control || alt => changed(prompt.move_word_left()),
        zz_terminal::KeyCode::ArrowRight if control || alt => changed(prompt.move_word_right()),
        zz_terminal::KeyCode::ArrowLeft if platform => changed({
            let changed = prompt.cursor != 0;
            prompt.cursor = 0;
            changed
        }),
        zz_terminal::KeyCode::ArrowRight if platform => changed({
            let changed = prompt.cursor != prompt.input.len();
            prompt.cursor = prompt.input.len();
            changed
        }),
        zz_terminal::KeyCode::ArrowLeft => changed(prompt.move_left()),
        zz_terminal::KeyCode::ArrowRight => changed(prompt.move_right()),
        zz_terminal::KeyCode::ArrowUp => changed(prompt.history_up(history)),
        zz_terminal::KeyCode::ArrowDown => changed(prompt.history_down(history)),
        zz_terminal::KeyCode::Character(character) if control => {
            match character.to_ascii_lowercase() {
                'a' => changed({
                    let changed = prompt.cursor != 0;
                    prompt.cursor = 0;
                    changed
                }),
                'e' => changed({
                    let changed = prompt.cursor != prompt.input.len();
                    prompt.cursor = prompt.input.len();
                    changed
                }),
                'b' => changed(prompt.move_left()),
                'f' => changed(prompt.move_right()),
                'p' => changed(prompt.history_up(history)),
                'n' => changed(prompt.history_down(history)),
                'h' => backspace(prompt),
                'd' => changed(prompt.delete_forward()),
                'u' => changed(prompt.clear()),
                'k' => changed(prompt.delete_to_end()),
                'w' => changed(prompt.delete_previous_word()),
                'c' | 'g' | '[' => PromptKeyAction::Close,
                letter @ ('r' | 's') if prompt.mode == CommandPromptMode::Incremental => {
                    PromptKeyAction::Incremental(prompt.incremental_prefix(letter == 'r'))
                }
                _ => PromptKeyAction::Handled,
            }
        }
        zz_terminal::KeyCode::Character(character) if alt => match character.to_ascii_lowercase() {
            'b' => changed(prompt.move_word_left()),
            'f' => changed(prompt.move_word_right()),
            _ => PromptKeyAction::Handled,
        },
        zz_terminal::KeyCode::Character(_) if platform => PromptKeyAction::Handled,
        zz_terminal::KeyCode::Character(character) => {
            if text_follows {
                PromptKeyAction::Handled
            } else {
                let text = input
                    .text
                    .as_deref()
                    .map_or_else(|| character.to_string(), str::to_owned);
                if prompt.insert(&text) {
                    PromptKeyAction::Updated
                } else {
                    PromptKeyAction::LimitExceeded
                }
            }
        }
        zz_terminal::KeyCode::Tab
        | zz_terminal::KeyCode::Insert
        | zz_terminal::KeyCode::PageUp
        | zz_terminal::KeyCode::PageDown
        | zz_terminal::KeyCode::Function(_)
        | zz_terminal::KeyCode::Unidentified => PromptKeyAction::Handled,
    }
}

struct ShutdownBlocker {
    shared: Arc<Shared>,
    detached: bool,
}

impl ShutdownBlocker {
    fn acquire(shared: &Arc<Shared>, detached: bool) -> Option<Self> {
        let mut blockers = shared.shutdown_blockers.lock();
        if blockers.closed {
            return None;
        }
        blockers.active = blockers
            .active
            .checked_add(1)
            .expect("shutdown blocker count overflow");
        if detached {
            blockers.detached = blockers
                .detached
                .checked_add(1)
                .expect("detached shutdown blocker count overflow");
        }
        drop(blockers);
        Some(Self {
            shared: Arc::clone(shared),
            detached,
        })
    }

    fn fork(&self, detached: bool) -> Self {
        let mut blockers = self.shared.shutdown_blockers.lock();
        blockers.active = blockers
            .active
            .checked_add(1)
            .expect("shutdown blocker count overflow");
        if detached {
            blockers.detached = blockers
                .detached
                .checked_add(1)
                .expect("detached shutdown blocker count overflow");
        }
        drop(blockers);
        Self {
            shared: Arc::clone(&self.shared),
            detached,
        }
    }
}

impl Drop for ShutdownBlocker {
    fn drop(&mut self) {
        let resume_shutdown = {
            let mut blockers = self.shared.shutdown_blockers.lock();
            blockers.active = blockers
                .active
                .checked_sub(1)
                .expect("shutdown blocker count underflow");
            if self.detached {
                blockers.detached = blockers
                    .detached
                    .checked_sub(1)
                    .expect("detached shutdown blocker count underflow");
            }
            blockers.closed && blockers.active == 0
        };
        if resume_shutdown {
            self.shared
                .request_shutdown_with_hooks(self.shared.shutdown_forced.load(Ordering::Acquire));
        }
    }
}

struct ShellJobPermit {
    shared: Arc<Shared>,
    token: u64,
    process: Arc<Mutex<Option<Child>>>,
    managed: bool,
    shutdown_blocker: Option<ShutdownBlocker>,
}

impl ShellJobPermit {
    fn acquire(
        shared: &Arc<Shared>,
        detached: bool,
        shutdown_blocking: bool,
        shutdown_blocker: Option<ShutdownBlocker>,
    ) -> Option<Self> {
        let mut shutdown_blocker = if shutdown_blocking {
            Some(match shutdown_blocker {
                Some(blocker) => blocker,
                None => ShutdownBlocker::acquire(shared, detached)?,
            })
        } else {
            None
        };
        let mut inner = shared.inner.lock();
        if shared.stopping.load(Ordering::Acquire) && !detached
            || inner.active_shell_jobs >= MAX_SHELL_JOBS
        {
            drop(inner);
            drop(shutdown_blocker.take());
            return None;
        }
        inner.next_shell_job_token = inner.next_shell_job_token.wrapping_add(1).max(1);
        let token = inner.next_shell_job_token;
        let process = Arc::new(Mutex::new(None));
        let managed = !detached && !shutdown_blocking;
        inner.active_shell_jobs += 1;
        if managed {
            inner.shell_jobs.insert(token, Arc::clone(&process));
        }
        drop(inner);
        Some(Self {
            shared: Arc::clone(shared),
            token,
            process,
            managed,
            shutdown_blocker,
        })
    }
}

impl Drop for ShellJobPermit {
    fn drop(&mut self) {
        let mut inner = self.shared.inner.lock();
        if self.managed {
            inner.shell_jobs.remove(&self.token);
        }
        inner.active_shell_jobs = inner.active_shell_jobs.saturating_sub(1);
        drop(inner);
        drop(self.shutdown_blocker.take());
    }
}

struct ShellJobResult {
    output: Vec<u8>,
    status: ExitStatus,
}

#[cfg(unix)]
fn run_shell_job(
    command: &str,
    cwd: &Path,
    tmux: &str,
    environment: &[(String, Option<String>)],
    default_terminal: &str,
    zz_socket: &Path,
    startup_reentry: Option<&str>,
    tmux_shim: Option<&Path>,
    zz_executable: Option<&Path>,
    show_stderr: bool,
    job_process: &Mutex<Option<Child>>,
    stopping: &AtomicBool,
    detached: bool,
    started: Option<&mpsc::SyncSender<()>>,
) -> Result<ShellJobResult, ()> {
    use std::{
        os::{fd::OwnedFd, unix::net::UnixStream, unix::process::CommandExt as _},
        process::Stdio,
    };

    let (mut output, child_socket) = UnixStream::pair().map_err(|_| ())?;
    let stdin = OwnedFd::from(child_socket.try_clone().map_err(|_| ())?);
    let stdout = OwnedFd::from(child_socket.try_clone().map_err(|_| ())?);
    let cwd = existing_job_working_directory(cwd);
    let mut process = shell_process(command);
    configure_shell_job_environment(
        &mut process,
        environment,
        default_terminal,
        startup_reentry.is_some(),
        tmux,
        zz_socket.as_os_str(),
        tmux_shim,
        zz_executable,
    );
    process
        .arg0("sh")
        .process_group(0)
        .current_dir(&cwd)
        .env("PWD", cwd.as_os_str())
        .stdin(Stdio::from(stdin))
        .stdout(Stdio::from(stdout));
    if let Some(startup_reentry) = startup_reentry {
        process.env(crate::STARTUP_REENTRY_ENVIRONMENT_VARIABLE, startup_reentry);
    }
    if show_stderr {
        let stderr = OwnedFd::from(child_socket.try_clone().map_err(|_| ())?);
        process.stderr(Stdio::from(stderr));
    } else {
        process.stderr(Stdio::null());
    }
    let child = process.spawn().map_err(|_| ())?;
    drop(process);
    drop(child_socket);
    install_shell_job_process(job_process, stopping, child, detached)?;
    if let Some(started) = started {
        let _ = started.send(());
    }
    let mut bytes = Vec::new();
    if output.read_to_end(&mut bytes).is_err() {
        terminate_managed_process(job_process);
        return Err(());
    }
    let status = wait_shell_job_process(job_process)?;
    Ok(ShellJobResult {
        output: bytes,
        status,
    })
}

#[cfg(not(unix))]
fn run_shell_job(
    command: &str,
    cwd: &Path,
    tmux: &str,
    environment: &[(String, Option<String>)],
    default_terminal: &str,
    zz_socket: &Path,
    startup_reentry: Option<&str>,
    tmux_shim: Option<&Path>,
    zz_executable: Option<&Path>,
    show_stderr: bool,
    job_process: &Mutex<Option<Child>>,
    stopping: &AtomicBool,
    detached: bool,
    started: Option<&mpsc::SyncSender<()>>,
) -> Result<ShellJobResult, ()> {
    let cwd = existing_job_working_directory(cwd);
    let mut process = shell_process(command);
    configure_shell_job_environment(
        &mut process,
        environment,
        default_terminal,
        startup_reentry.is_some(),
        tmux,
        zz_socket.as_os_str(),
        tmux_shim,
        zz_executable,
    );
    process
        .current_dir(&cwd)
        .env("PWD", cwd.as_os_str())
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(if show_stderr {
            Stdio::piped()
        } else {
            Stdio::null()
        });
    if let Some(startup_reentry) = startup_reentry {
        process.env(crate::STARTUP_REENTRY_ENVIRONMENT_VARIABLE, startup_reentry);
    }
    let mut child = process.spawn().map_err(|_| ())?;
    let _stdin = child.stdin.take();
    let Some(mut stdout) = child.stdout.take() else {
        let _ = terminate_copy_pipe(&mut child);
        return Err(());
    };
    let stderr = child.stderr.take();
    install_shell_job_process(job_process, stopping, child, detached)?;
    if let Some(started) = started {
        let _ = started.send(());
    }
    let stdout = thread::spawn(move || {
        let mut output = Vec::new();
        stdout.read_to_end(&mut output).map(|_| output)
    });
    let stderr = stderr.map(|mut stderr| {
        thread::spawn(move || {
            let mut output = Vec::new();
            stderr.read_to_end(&mut output).map(|_| output)
        })
    });
    let status = wait_shell_job_process(job_process);
    let mut output = stdout.join().map_err(|_| ())?.map_err(|_| ())?;
    if let Some(stderr) = stderr {
        output.extend(stderr.join().map_err(|_| ())?.map_err(|_| ())?);
    }
    let status = status?;
    Ok(ShellJobResult { output, status })
}

fn install_shell_job_process(
    process: &Mutex<Option<Child>>,
    stopping: &AtomicBool,
    mut child: Child,
    detached: bool,
) -> Result<(), ()> {
    let mut process = process.lock();
    if stopping.load(Ordering::Acquire) && !detached {
        drop(process);
        let _ = terminate_copy_pipe(&mut child);
        return Err(());
    }
    *process = Some(child);
    Ok(())
}

fn wait_shell_job_process(process: &Mutex<Option<Child>>) -> Result<ExitStatus, ()> {
    loop {
        let mut process = process.lock();
        let Some(child) = process.as_mut() else {
            return Err(());
        };
        match child.try_wait() {
            Ok(Some(status)) => {
                process.take();
                return Ok(status);
            }
            Ok(None) => drop(process),
            Err(_) => {
                let mut child = process.take().expect("shell job process was present");
                drop(process);
                let _ = terminate_copy_pipe(&mut child);
                return Err(());
            }
        }
        thread::sleep(COPY_PIPE_POLL_INTERVAL);
    }
}

fn shell_job_output(command: &str, result: &ShellJobResult) -> (String, u8) {
    let mut output = String::from_utf8_lossy(&result.output).into_owned();
    let (exit_code, message) = shell_exit(result.status).map_or_else(
        || {
            let exit_code = result
                .status
                .code()
                .and_then(|code| u8::try_from(code).ok())
                .unwrap_or(1);
            let message = (exit_code != 0).then(|| format!("'{command}' returned {exit_code}"));
            (exit_code, message)
        },
        |signal| {
            let exit_code = u8::try_from(128_i32.saturating_add(signal)).unwrap_or(u8::MAX);
            (
                exit_code,
                Some(format!("'{command}' terminated by signal {signal}")),
            )
        },
    );
    if let Some(message) = message {
        append_inserted_output(&mut output, &message);
    }
    (output, exit_code)
}

#[cfg(unix)]
fn shell_exit(status: ExitStatus) -> Option<i32> {
    use std::os::unix::process::ExitStatusExt as _;

    status.signal()
}

#[cfg(not(unix))]
fn shell_exit(_: ExitStatus) -> Option<i32> {
    None
}

struct CopyPipePermit {
    shared: Arc<Shared>,
}

impl Drop for CopyPipePermit {
    fn drop(&mut self) {
        let mut inner = self.shared.inner.lock();
        inner.active_copy_pipes = inner.active_copy_pipes.saturating_sub(1);
    }
}

struct CopyPipeEnvironment {
    variables: Vec<(String, Option<String>)>,
    default_terminal: String,
    tmux: String,
    zz_socket: PathBuf,
}

fn run_copy_pipe(
    command: &str,
    data: &str,
    environment: &CopyPipeEnvironment,
) -> Result<(), String> {
    run_copy_pipe_with_timeout(command, data, environment, COPY_PIPE_TIMEOUT)
}

fn run_copy_pipe_with_timeout(
    command: &str,
    data: &str,
    environment: &CopyPipeEnvironment,
    timeout: Duration,
) -> Result<(), String> {
    let mut input = tempfile::tempfile()
        .map_err(|error| format!("could not stage input in a temporary file: {error}"))?;
    input
        .write_all(data.as_bytes())
        .map_err(|error| format!("could not stage input: {error}"))?;
    input
        .seek(SeekFrom::Start(0))
        .map_err(|error| format!("could not rewind staged input: {error}"))?;

    let mut process = shell_process(command);
    #[cfg(unix)]
    {
        use std::os::unix::process::CommandExt as _;

        process.process_group(0);
    }
    configure_shell_job_environment(
        &mut process,
        &environment.variables,
        &environment.default_terminal,
        false,
        &environment.tmux,
        environment.zz_socket.as_os_str(),
        None,
        None,
    );
    process
        .stdin(Stdio::from(input))
        .stdout(Stdio::null())
        .stderr(Stdio::null());
    let mut child = process
        .spawn()
        .map_err(|error| format!("could not start process: {error}"))?;
    let started = Instant::now();
    loop {
        match child.try_wait() {
            Ok(Some(status)) if status.success() => return Ok(()),
            Ok(Some(status)) => return Err(format!("process exited unsuccessfully ({status})")),
            Ok(None) if started.elapsed() >= timeout => {
                let (kill_error, wait_error) = terminate_copy_pipe(&mut child);
                if let Some(error) = kill_error {
                    return Err(format!(
                        "process timed out after {} seconds and could not be terminated: {error}",
                        timeout.as_secs()
                    ));
                }
                if let Some(error) = wait_error {
                    return Err(format!(
                        "process timed out after {} seconds and could not be reaped: {error}",
                        timeout.as_secs()
                    ));
                }
                return Err(format!(
                    "process timed out after {} seconds",
                    timeout.as_secs()
                ));
            }
            Ok(None) => thread::sleep(COPY_PIPE_POLL_INTERVAL),
            Err(error) => {
                terminate_copy_pipe(&mut child);
                return Err(format!("could not query process status: {error}"));
            }
        }
    }
}

fn terminate_copy_pipe(child: &mut Child) -> (Option<String>, Option<std::io::Error>) {
    #[cfg(unix)]
    let tree_result = rustix::process::kill_process_group(
        rustix::process::Pid::from_child(&*child),
        rustix::process::Signal::KILL,
    )
    .or_else(|error| {
        if error == rustix::io::Errno::SRCH {
            Ok(())
        } else {
            Err(error)
        }
    })
    .map_err(|error| format!("could not terminate process group: {error}"));
    #[cfg(windows)]
    let tree_result = {
        let pid = child.id().to_string();
        std::process::Command::new("taskkill")
            .args(["/PID", pid.as_str(), "/T", "/F"])
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .status()
            .map_err(|error| format!("could not run taskkill: {error}"))
            .and_then(|status| {
                if status.success() {
                    Ok(())
                } else {
                    Err(format!("taskkill exited unsuccessfully ({status})"))
                }
            })
    };
    #[cfg(not(any(unix, windows)))]
    let tree_result = Err("process-tree termination is unsupported".to_owned());
    let child_error = child.kill().err();
    let kill_error = tree_result.err().map(|tree_error| match child_error {
        Some(child_error) => {
            format!("{tree_error}; could not terminate immediate child: {child_error}")
        }
        None => tree_error,
    });
    let wait_error = child.wait().err();
    (kill_error, wait_error)
}

fn terminate_managed_process(process: &Mutex<Option<Child>>) {
    let Some(mut child) = process.lock().take() else {
        return;
    };
    let _ = terminate_copy_pipe(&mut child);
}

fn pane_pipe_process_exited(process: &Mutex<Option<Child>>) -> bool {
    let mut process = process.lock();
    let Some(child) = process.as_mut() else {
        return true;
    };
    match child.try_wait() {
        Ok(Some(_)) => {
            process.take();
            true
        }
        Ok(None) => false,
        Err(_) => {
            let mut child = process.take().expect("pipe process was present");
            drop(process);
            let _ = terminate_copy_pipe(&mut child);
            true
        }
    }
}

fn stop_pane_pipe(mut pipe: PanePipe) {
    pipe.stop.store(true, Ordering::Release);
    terminate_managed_process(&pipe.process);
    if let Some(worker) = pipe.thread.take()
        && worker.join().is_err()
    {
        log::error!("pipe-pane worker panicked for pane process {}", pipe.pid);
    }
    let terminal = Arc::clone(&pipe.terminal.lock());
    let _ = terminal.disarm_raw_output_tap(pipe.token);
}

fn control_output_wanted(inner: &ServerState, pane: PaneId) -> bool {
    let Some(window) = inner.engine.state.window_for_pane(pane) else {
        return false;
    };
    inner
        .engine
        .state
        .sessions
        .iter()
        .filter(|(_, session)| session.windows.contains(&window))
        .filter_map(|(session, _)| inner.attached.get(session))
        .flatten()
        .any(|client| inner.client_kinds.get(client) == Some(&ClientKind::Control))
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum ControlOutputAgeAction {
    Output(u64),
    Pause,
    Kill,
}

fn control_output_age_action(
    pause_after_ms: Option<u64>,
    enqueued_at: Instant,
    now: Instant,
) -> ControlOutputAgeAction {
    let age = now.saturating_duration_since(enqueued_at);
    let age_ms = u64::try_from(age.as_millis()).unwrap_or(u64::MAX);
    if let Some(pause_after_ms) = pause_after_ms {
        if age_ms >= pause_after_ms {
            ControlOutputAgeAction::Pause
        } else {
            ControlOutputAgeAction::Output(age_ms)
        }
    } else if age >= CONTROL_MAXIMUM_AGE {
        ControlOutputAgeAction::Kill
    } else {
        ControlOutputAgeAction::Output(age_ms)
    }
}

fn drain_control_pane_output(
    output: &mut ControlPaneOutput,
    limit: usize,
    now: Instant,
) -> (u64, Vec<u8>) {
    let enqueued_at = output
        .pending
        .front()
        .expect("pending control output is present")
        .enqueued_at;
    let age_ms =
        u64::try_from(now.saturating_duration_since(enqueued_at).as_millis()).unwrap_or(u64::MAX);
    let mut bytes = Vec::with_capacity(limit);
    while bytes.len() < limit {
        let Some(chunk) = output.pending.front_mut() else {
            break;
        };
        let take = (limit - bytes.len()).min(chunk.bytes.len().saturating_sub(chunk.offset));
        bytes.extend_from_slice(&chunk.bytes[chunk.offset..chunk.offset + take]);
        chunk.offset += take;
        if chunk.offset == chunk.bytes.len() {
            output.pending.pop_front();
        }
    }
    (age_ms, bytes)
}

fn stop_control_output_tap(mut tap: ControlOutputTap) {
    tap.stop.store(true, Ordering::Release);
    let _ = tap.terminal.disarm_raw_output_tap(tap.token);
    if let Some(worker) = tap.thread.take()
        && worker.join().is_err()
    {
        log::error!("control output worker panicked");
    }
}

fn run_control_output_tap(
    shared: &std::sync::Weak<Shared>,
    pane: PaneId,
    stop: &Arc<AtomicBool>,
    receiver: &crossbeam_channel::Receiver<Arc<[u8]>>,
) {
    loop {
        match receiver.recv_timeout(COPY_PIPE_POLL_INTERVAL) {
            Ok(bytes) => {
                let Some(shared) = shared.upgrade() else {
                    break;
                };
                if stop.load(Ordering::Acquire) {
                    shared.publish_pipe_output_for_pane(pane, &bytes);
                } else {
                    shared.publish_control_output_for_pane(pane, &bytes);
                }
            }
            Err(crossbeam_channel::RecvTimeoutError::Timeout) => {
                let Some(shared) = shared.upgrade() else {
                    break;
                };
                shared.pump_control_output_at(Instant::now());
                if stop.load(Ordering::Acquire) {
                    break;
                }
            }
            Err(crossbeam_channel::RecvTimeoutError::Disconnected) => break,
        }
    }
}

#[allow(clippy::too_many_arguments)]
fn run_pane_pipe(
    shared: &std::sync::Weak<Shared>,
    pane: PaneId,
    token: u64,
    terminal: &Arc<Mutex<Arc<TerminalSession>>>,
    process: &Arc<Mutex<Option<Child>>>,
    stop: &Arc<AtomicBool>,
    mut child_input: Option<std::process::ChildStdin>,
    child_output: Option<std::process::ChildStdout>,
    tap: Option<crossbeam_channel::Receiver<Arc<[u8]>>>,
) {
    let input_worker = child_output.map(|mut output| {
        let terminal = Arc::clone(terminal);
        let stop = Arc::clone(stop);
        thread::Builder::new()
            .name(format!("zz-pipe-input-{}", pane.0))
            .spawn(move || {
                let mut buffer = vec![0_u8; 64 * 1024];
                while !stop.load(Ordering::Acquire) {
                    match output.read(&mut buffer) {
                        Ok(0) | Err(_) => break,
                        Ok(length) => {
                            let target = Arc::clone(&terminal.lock());
                            if !target.send_raw_input(Arc::from(&buffer[..length])) {
                                break;
                            }
                        }
                    }
                }
            })
    });
    let input_worker = match input_worker {
        Some(Ok(worker)) => Some(worker),
        Some(Err(_)) => {
            stop.store(true, Ordering::Release);
            None
        }
        None => None,
    };
    let mut exited = false;
    while !stop.load(Ordering::Acquire) {
        let Some(tap) = tap.as_ref() else {
            if pane_pipe_process_exited(process) {
                exited = true;
                break;
            }
            thread::sleep(COPY_PIPE_POLL_INTERVAL);
            continue;
        };
        match tap.recv_timeout(COPY_PIPE_POLL_INTERVAL) {
            Ok(bytes) => {
                let Some(input) = child_input.as_mut() else {
                    break;
                };
                if input.write_all(&bytes).is_err() {
                    exited = pane_pipe_process_exited(process);
                    break;
                }
            }
            Err(crossbeam_channel::RecvTimeoutError::Timeout) => {
                if pane_pipe_process_exited(process) {
                    exited = true;
                    break;
                }
            }
            Err(crossbeam_channel::RecvTimeoutError::Disconnected) => break,
        }
    }
    drop(tap);
    drop(child_input);
    if !exited {
        terminate_managed_process(process);
    }
    if let Some(worker) = input_worker {
        let _ = worker.join();
    }
    let terminal = Arc::clone(&terminal.lock());
    let _ = terminal.disarm_raw_output_tap(token);
    if let Some(shared) = shared.upgrade() {
        shared.pipe_finished(pane, token);
    }
}

enum PaneSink {
    Terminal(Arc<TerminalSession>),
    Browser(PaneId),
}

enum DeferredTerminalCommand {
    SetWordSeparators {
        terminal: Arc<TerminalSession>,
        separators: WordSeparators,
    },
    SetAllowPassthrough {
        terminal: Arc<TerminalSession>,
        enabled: bool,
    },
    SetWrapSearch {
        terminal: Arc<TerminalSession>,
        enabled: bool,
    },
    SetAppearance {
        terminal: Arc<TerminalSession>,
        appearance: Arc<TerminalAppearance>,
    },
    AttachView {
        terminal: Arc<TerminalSession>,
        view: TerminalViewId,
    },
    Resize {
        terminal: Arc<TerminalSession>,
        geometry: TerminalGeometry,
    },
    ViewAction {
        terminal: Arc<TerminalSession>,
        view: TerminalViewId,
        action: zz_terminal::TerminalViewAction,
    },
    SendTokens {
        terminals: Vec<Arc<TerminalSession>>,
        keys: Vec<zz_protocol::KeyToken>,
        repeat: u32,
    },
    ResetScreen {
        terminals: Vec<Arc<TerminalSession>>,
    },
}

impl DeferredTerminalCommand {
    #[cfg(test)]
    const fn wrap_search(&self) -> Option<bool> {
        match self {
            Self::SetWrapSearch { enabled, .. } => Some(*enabled),
            _ => None,
        }
    }

    fn run(self) {
        match self {
            Self::SetWordSeparators {
                terminal,
                separators,
            } => terminal.set_word_separators(separators),
            Self::SetAllowPassthrough { terminal, enabled } => {
                terminal.set_allow_passthrough(enabled);
            }
            Self::SetWrapSearch { terminal, enabled } => terminal.set_wrap_search(enabled),
            Self::SetAppearance {
                terminal,
                appearance,
            } => terminal.set_appearance(appearance),
            Self::AttachView { terminal, view } => terminal.attach_view(view),
            Self::ResetScreen { terminals } => {
                for terminal in terminals {
                    terminal.reset_screen();
                }
            }
            Self::Resize { terminal, geometry } => terminal.resize(
                geometry.columns,
                geometry.rows,
                geometry.cell_width_px,
                geometry.cell_height_px,
            ),
            Self::ViewAction {
                terminal,
                view,
                action,
            } => terminal.view_action(view, action),
            Self::SendTokens {
                terminals,
                keys,
                repeat,
            } => repeat_until_rejected(repeat, || send_tokens(&terminals, &keys)),
        }
    }
}

fn repeat_until_rejected(mut repeat: u32, mut send: impl FnMut() -> bool) {
    while repeat > 0 && send() {
        repeat -= 1;
    }
}

fn resolve_input_sinks(inner: &ServerState, source: PaneId) -> Result<Vec<PaneSink>, ServerError> {
    if inner.engine.pane_input_off(source)? {
        return Ok(Vec::new());
    }
    let targets = inner.engine.synchronized_input_targets(source)?;
    let mut sinks = Vec::with_capacity(targets.len());
    for pane in targets {
        if inner.engine.pane_input_off(pane)? {
            continue;
        }
        if matches!(
            inner.engine.state.pane(pane).map(|pane| &pane.kind),
            Some(
                zz_mux::PaneKind::Picker { .. }
                    | zz_mux::PaneKind::Agent(_)
                    | zz_mux::PaneKind::Editor(_)
            )
        ) {
        } else if let Some(terminal) = inner.terminals.get(&pane) {
            sinks.push(PaneSink::Terminal(Arc::clone(terminal)));
        } else if matches!(
            inner.engine.state.pane(pane).map(|pane| &pane.kind),
            Some(zz_mux::PaneKind::Browser(_))
        ) {
            ensure_browser_attached(inner, pane)?;
            sinks.push(PaneSink::Browser(pane));
        } else {
            return Err(ServerError::PaneExited(pane));
        }
    }
    Ok(sinks)
}

fn session_terminals(inner: &ServerState, session: SessionId) -> Vec<Arc<TerminalSession>> {
    inner
        .engine
        .state
        .sessions
        .get(&session)
        .into_iter()
        .flat_map(|session| session.windows.iter())
        .filter_map(|window| inner.engine.state.windows.get(window))
        .flat_map(|window| window.panes.keys())
        .filter_map(|pane| inner.terminals.get(pane).cloned())
        .collect()
}

fn session_terminal_panes(inner: &ServerState, session: SessionId) -> BTreeSet<PaneId> {
    inner
        .engine
        .state
        .sessions
        .get(&session)
        .into_iter()
        .flat_map(|session| session.windows.iter())
        .filter_map(|window| inner.engine.state.windows.get(window))
        .flat_map(|window| window.panes.keys())
        .filter(|pane| inner.terminals.contains_key(pane))
        .copied()
        .collect()
}

fn terminal_viewport_for_pane(
    inner: &ServerState,
    pane: PaneId,
    view: TerminalViewId,
) -> Option<(Arc<TerminalSession>, Arc<TerminalViewport>)> {
    let terminal = inner.terminals.get(&pane)?;
    let viewport = terminal.latest_viewport_for(view).or_else(|| {
        inner
            .engine
            .state
            .pane(pane)
            .is_some_and(|pane| pane.dead)
            .then(|| terminal.latest_viewport())
    })?;
    Some((Arc::clone(terminal), viewport))
}

fn visible_terminal_panes(
    inner: &ServerState,
    client: ClientId,
    session: SessionId,
) -> BTreeSet<PaneId> {
    if inner.client_kinds.get(&client) == Some(&ClientKind::Control) {
        return BTreeSet::new();
    }
    let Some(session) = inner.engine.state.sessions.get(&session) else {
        return BTreeSet::new();
    };
    let focused_window = client_focused_window(inner, client, session);
    let Some(window) = inner.engine.state.windows.get(&focused_window) else {
        return BTreeSet::new();
    };
    window
        .panes
        .iter()
        .filter(|(pane, entry)| {
            window.zoomed_pane.is_none_or(|zoomed| **pane == zoomed)
                && inner.terminals.contains_key(pane)
                && !matches!(entry.kind, PaneKind::Agent(_))
        })
        .map(|(pane, _)| *pane)
        .collect()
}

fn streamed_terminal_panes(
    inner: &ServerState,
    client: ClientId,
    session: SessionId,
    visible: &BTreeSet<PaneId>,
) -> BTreeMap<PaneId, TerminalStreamKind> {
    let mut streamed = visible
        .iter()
        .copied()
        .map(|pane| (pane, TerminalStreamKind::Foreground))
        .collect::<BTreeMap<_, _>>();
    if inner.terminal_preview_clients.contains(&client) {
        for pane in session_terminal_panes(inner, session) {
            streamed.entry(pane).or_insert(TerminalStreamKind::Preview);
        }
    }
    streamed
}

/// The agent panes a client can actually see, derived exactly like the
/// terminal ones: attached session, focused window, zoom.
#[cfg(feature = "agent")]
fn visible_agent_panes(
    inner: &ServerState,
    client: ClientId,
    session: SessionId,
) -> BTreeSet<PaneId> {
    let Some(session) = inner.engine.state.sessions.get(&session) else {
        return BTreeSet::new();
    };
    let focused_window = client_focused_window(inner, client, session);
    let Some(window) = inner.engine.state.windows.get(&focused_window) else {
        return BTreeSet::new();
    };
    window
        .panes
        .keys()
        .filter(|pane| {
            window.zoomed_pane.is_none_or(|zoomed| **pane == zoomed)
                && inner
                    .engine
                    .state
                    .pane(**pane)
                    .is_some_and(|pane| matches!(pane.kind, PaneKind::Agent(_)))
        })
        .copied()
        .collect()
}

fn attached_clients_for_pane(inner: &ServerState, pane: PaneId) -> Option<&BTreeSet<ClientId>> {
    let window = inner.engine.state.window_for_pane(pane)?;
    let session = inner.engine.state.windows.get(&window)?.session;
    inner.attached.get(&session)
}

fn client_is_attached_to_pane(inner: &ServerState, client: ClientId, pane: PaneId) -> bool {
    attached_clients_for_pane(inner, pane).is_some_and(|clients| clients.contains(&client))
}

fn remove_client_terminal_geometries(
    inner: &mut ServerState,
    client: ClientId,
) -> BTreeSet<PaneId> {
    let mut affected = BTreeSet::new();
    inner.terminal_geometries.retain(|pane, geometries| {
        if geometries.remove(&client).is_some() {
            affected.insert(*pane);
        }
        !geometries.is_empty()
    });
    affected
}

fn terminal_geometry_owner(inner: &ServerState, pane: PaneId) -> Option<ClientId> {
    let window = inner.engine.state.window_for_pane(pane)?;
    let session = inner.engine.state.windows.get(&window)?.session;
    inner
        .attached
        .get(&session)?
        .iter()
        .filter(|client| {
            inner.client_kinds.get(*client) == Some(&ClientKind::Control)
                || inner
                    .visible_terminals
                    .get(*client)
                    .is_some_and(|visible| visible.contains(&pane))
        })
        .filter(|client| client_terminal_geometry(inner, **client, pane).is_some())
        .min_by_key(|client| {
            (
                Reverse(
                    inner
                        .client_terminal_input_sequences
                        .get(*client)
                        .copied()
                        .unwrap_or_default(),
                ),
                client.0,
            )
        })
        .copied()
}

fn client_terminal_geometry(
    inner: &ServerState,
    client: ClientId,
    pane: PaneId,
) -> Option<TerminalGeometry> {
    if inner.client_kinds.get(&client) != Some(&ClientKind::Control) {
        return inner.terminal_geometries.get(&pane)?.get(&client).copied();
    }
    let window = inner.engine.state.window_for_pane(pane)?;
    let session = inner.engine.state.windows.get(&window)?.session;
    if client_attached_session(inner, client) != Some(session) {
        return None;
    }
    let geometry = control_client_geometry(inner, client, window)?;
    let (columns, rows) =
        inner
            .engine
            .pane_geometry_at_window_extent(pane, geometry.columns, geometry.rows)?;
    Some(TerminalGeometry {
        columns,
        rows,
        ..geometry
    })
}

#[cfg(test)]
fn aggressive_terminal_geometry(inner: &ServerState, pane: PaneId) -> Option<TerminalGeometry> {
    terminal_geometry_for_mode(inner, pane, true, WindowSize::Smallest)
}

fn terminal_geometry_for_mode(
    inner: &ServerState,
    pane: PaneId,
    aggressive: bool,
    mode: WindowSize,
) -> Option<TerminalGeometry> {
    let window = inner.engine.state.window_for_pane(pane)?;
    let window_state = inner.engine.state.windows.get(&window)?;
    if window_state
        .zoomed_pane
        .is_some_and(|zoomed| zoomed != pane)
    {
        return None;
    }
    let session = window_state.session;
    let suppress_ignored = unignored_attached_sizing_client_exists(inner);
    let candidates = inner
        .attached
        .get(&session)?
        .iter()
        .filter(|client| client_is_sizing_candidate(inner, **client, suppress_ignored))
        .filter(|client| {
            if aggressive {
                client_focused_window_for_attachment(inner, **client) == Some(window)
            } else {
                inner.client_kinds.get(*client) == Some(&ClientKind::Control)
                    || inner
                        .visible_terminals
                        .get(*client)
                        .is_some_and(|visible| visible.contains(&pane))
            }
        })
        .filter_map(|client| {
            client_terminal_geometry(inner, *client, pane).map(|geometry| (*client, geometry))
        })
        .collect::<Vec<_>>();
    let owner = candidates.iter().min_by_key(|(client, _)| {
        (
            Reverse(
                inner
                    .client_terminal_input_sequences
                    .get(client)
                    .copied()
                    .unwrap_or_default(),
            ),
            client.0,
        )
    })?;
    let mut geometry = if mode == WindowSize::Manual {
        let (columns, rows) = inner.engine.pane_geometry(pane)?;
        TerminalGeometry {
            columns,
            rows,
            ..owner.1
        }
    } else if mode == WindowSize::Latest {
        owner.1
    } else {
        let first_geometry = candidates.first()?.1;
        let mut columns = first_geometry.columns;
        let mut rows = first_geometry.rows;
        for (_, geometry) in &candidates[1..] {
            if mode == WindowSize::Largest {
                columns = columns.max(geometry.columns);
                rows = rows.max(geometry.rows);
            } else {
                columns = columns.min(geometry.columns);
                rows = rows.min(geometry.rows);
            }
        }
        TerminalGeometry {
            columns,
            rows,
            ..owner.1
        }
    };
    if mode != WindowSize::Manual {
        for (client, _) in &candidates {
            let Some(ceiling) = inner
                .control_outputs
                .get(client)
                .and_then(|output| output.window_geometries.get(&window))
            else {
                continue;
            };
            let (columns, rows) =
                inner
                    .engine
                    .pane_geometry_at_window_extent(pane, ceiling.columns, ceiling.rows)?;
            geometry.columns = geometry.columns.min(columns);
            geometry.rows = geometry.rows.min(rows);
        }
    }
    Some(geometry)
}

fn terminal_resize_for_pane(
    inner: &ServerState,
    pane: PaneId,
) -> Option<(Arc<TerminalSession>, TerminalGeometry)> {
    let window = inner.engine.state.window_for_pane(pane)?;
    let aggressive = inner.engine.state.window_aggressive_resize(window).ok()?;
    let mode = inner.engine.window_size(window);
    let geometry = terminal_geometry_for_mode(inner, pane, aggressive, mode)?;
    let terminal = inner.terminals.get(&pane).cloned()?;
    Some((terminal, geometry))
}

fn write_back_terminal_geometries(
    inner: &mut ServerState,
    panes: &BTreeSet<PaneId>,
    aggressive_only: bool,
) -> bool {
    let measurements = panes
        .iter()
        .filter_map(|pane| {
            let window = inner.engine.state.window_for_pane(*pane)?;
            if aggressive_only && !inner.engine.state.window_aggressive_resize(window).ok()? {
                return None;
            }
            terminal_resize_for_pane(inner, *pane)
                .map(|(_, geometry)| (*pane, geometry.columns, geometry.rows))
        })
        .collect::<Vec<_>>();
    measurements
        .into_iter()
        .fold(false, |changed, (pane, columns, rows)| {
            inner.engine.set_pane_geometry(pane, columns, rows) || changed
        })
}

fn panes_for_windows(inner: &ServerState, windows: &BTreeSet<WindowId>) -> BTreeSet<PaneId> {
    windows
        .iter()
        .filter_map(|window| inner.engine.state.windows.get(window))
        .flat_map(|window| window.panes.keys().copied())
        .collect()
}

fn note_terminal_activity_locked(inner: &mut ServerState, client: ClientId, pane: PaneId) -> bool {
    let Some(session) = client_is_attached_to_pane(inner, client, pane)
        .then(|| inner.engine.state.window_for_pane(pane))
        .flatten()
        .and_then(|window| inner.engine.state.windows.get(&window))
        .map(|window| window.session)
    else {
        return false;
    };
    note_client_activity_locked(inner, client, session)
}

fn note_client_activity_locked(
    inner: &mut ServerState,
    client: ClientId,
    session: SessionId,
) -> bool {
    let now = unix_timestamp();
    inner.engine.mark_session_active_at(session, now);
    inner.activity_sequence = inner.activity_sequence.saturating_add(1);
    let activity = inner.activity_sequence;
    inner.client_activity.insert(client, activity);
    inner.client_activity_times.insert(client, now);
    inner
        .choose_trees
        .values()
        .any(|chooser| chooser.sort.order() == Some(TmuxSortOrder::Activity))
}

fn terminal_resizes_after_client_focus(
    inner: &mut ServerState,
    client: ClientId,
) -> (Vec<(Arc<TerminalSession>, TerminalGeometry)>, bool) {
    let visible_panes = inner
        .visible_terminals
        .get(&client)
        .cloned()
        .unwrap_or_default();
    terminal_resizes_after_client_sequence(inner, client, &visible_panes)
}

fn terminal_resizes_after_client_input(
    inner: &mut ServerState,
    client: ClientId,
    source_pane: PaneId,
) -> (Vec<(Arc<TerminalSession>, TerminalGeometry)>, bool) {
    let Some(visible_panes) = inner.visible_terminals.get(&client).cloned() else {
        return (Vec::new(), false);
    };
    if !visible_panes.contains(&source_pane) || !inner.terminals.contains_key(&source_pane) {
        return (Vec::new(), false);
    }
    terminal_resizes_after_client_sequence(inner, client, &visible_panes)
}

fn terminal_resizes_after_client_sequence(
    inner: &mut ServerState,
    client: ClientId,
    visible_panes: &BTreeSet<PaneId>,
) -> (Vec<(Arc<TerminalSession>, TerminalGeometry)>, bool) {
    let previous_owners = visible_panes
        .iter()
        .map(|pane| (*pane, terminal_geometry_owner(inner, *pane)))
        .collect::<Vec<_>>();
    let previous_geometries = visible_panes
        .iter()
        .map(|pane| {
            (
                *pane,
                terminal_resize_for_pane(inner, *pane).map(|(_, geometry)| geometry),
            )
        })
        .collect::<BTreeMap<_, _>>();

    mark_client_terminal_latest(inner, client);

    let owner_changed_panes = previous_owners
        .into_iter()
        .filter_map(|(pane, previous)| {
            (terminal_geometry_owner(inner, pane) != previous).then_some(pane)
        })
        .collect::<BTreeSet<_>>();
    if owner_changed_panes.is_empty() {
        return (Vec::new(), false);
    }
    let layout_changed = write_back_terminal_geometries(inner, &owner_changed_panes, false);
    let resizes = visible_panes
        .iter()
        .filter_map(|pane| {
            let resize = terminal_resize_for_pane(inner, *pane)?;
            (previous_geometries.get(pane).copied().flatten() != Some(resize.1)).then_some(resize)
        })
        .collect();
    (resizes, layout_changed)
}

fn mark_client_terminal_latest(inner: &mut ServerState, client: ClientId) {
    let sequence = inner
        .terminal_input_sequence
        .checked_add(1)
        .expect("terminal input sequence exhausted");
    inner.terminal_input_sequence = sequence;
    inner
        .client_terminal_input_sequences
        .insert(client, sequence);
}

fn terminal_view_action_is_input(action: &zz_terminal::TerminalViewAction) -> bool {
    use zz_terminal::TerminalViewAction as Action;

    match action {
        Action::Focus(_) | Action::ClearLinkHover => false,
        Action::Mouse(input) => !terminal_mouse_is_bare_hover(*input),
        Action::ScrollLines(_)
        | Action::ScrollPages(_)
        | Action::ScrollTop
        | Action::ScrollBottom
        | Action::ScrollToFraction(_)
        | Action::ScrollToOffset(_)
        | Action::ScrollWheel { .. }
        | Action::SelectionPress(_)
        | Action::SelectionDrag(_)
        | Action::SelectionAutoscroll { .. }
        | Action::SelectionRelease(_)
        | Action::SelectAll
        | Action::ClearSelection
        | Action::ClearHistory
        | Action::EnterCopyMode
        | Action::EnterCopyModeScrollExit
        | Action::EnterCopyModeWith { .. }
        | Action::CopyMode(_)
        | Action::CopyModeCounted { .. }
        | Action::CopySelection { .. }
        | Action::SearchBegin(_)
        | Action::SearchUpdate(_)
        | Action::SearchNext
        | Action::SearchPrevious
        | Action::SearchClose
        | Action::Paste(_) => true,
    }
}

fn terminal_view_action_dismisses_display_panes(action: &zz_terminal::TerminalViewAction) -> bool {
    match action {
        zz_terminal::TerminalViewAction::Mouse(input) => !terminal_mouse_is_bare_hover(*input),
        zz_terminal::TerminalViewAction::ScrollWheel { .. } => true,
        _ => false,
    }
}

fn terminal_mouse_is_bare_hover(input: zz_terminal::TerminalMouseInput) -> bool {
    input.phase() == zz_terminal::TerminalMousePhase::Motion && input.button().is_none()
}

fn terminal_view_action_is_modal_input(action: &zz_terminal::TerminalViewAction) -> bool {
    !matches!(
        action,
        zz_terminal::TerminalViewAction::Focus(_) | zz_terminal::TerminalViewAction::ClearLinkHover
    )
}

#[derive(Clone, Copy)]
enum EarlyInputActivity {
    WithoutBell(PaneId),
    Full(PaneId),
}

const READ_ONLY_SAFE_COMMANDS: &[&str] = &[
    "attach-session",
    "copy-mode",
    "detach-client",
    "list-clients",
    "switch-client",
];

fn command_is_read_only_safe(command: &CommandInvocation) -> bool {
    if MuxEngine::is_command_alias_group(command) {
        return MuxEngine::command_alias_group_commands(command).is_ok_and(|commands| {
            commands.is_some_and(|commands| commands.iter().all(command_is_read_only_safe))
        });
    }
    let name = canonical_command(&command.name);
    if name == "send-keys" {
        return send_keys_is_read_only_safe(&command.args).unwrap_or(true);
    }
    READ_ONLY_SAFE_COMMANDS.contains(&name)
}

fn input_dismisses_client_message(input: &InputMessage) -> bool {
    match input {
        InputMessage::Key { input, .. } => input.action != zz_terminal::KeyAction::Release,
        InputMessage::TerminalView { action, .. } => {
            terminal_view_action_dismisses_display_panes(action)
        }
        _ => false,
    }
}

fn input_is_ignored_by_client_message(input: &InputMessage) -> bool {
    match input {
        InputMessage::Key { .. }
        | InputMessage::Text { .. }
        | InputMessage::TerminalView {
            action: zz_terminal::TerminalViewAction::Paste(_),
            ..
        }
        | InputMessage::ClientFocus { .. } => true,
        InputMessage::TerminalView { action, .. } => {
            terminal_view_action_dismisses_display_panes(action)
        }
        _ => false,
    }
}

fn committed_character(input: &zz_terminal::KeyInput, text_follows: bool) -> Option<char> {
    if !text_follows
        || !matches!(
            input.action,
            zz_terminal::KeyAction::Press | zz_terminal::KeyAction::Repeat
        )
    {
        return None;
    }
    if let Some(text) = input.text.as_deref() {
        let mut characters = text.chars();
        if let Some(character) = characters.next()
            && characters.next().is_none()
        {
            return Some(character);
        }
    }
    match input.key {
        zz_terminal::KeyCode::Character(character) => Some(character),
        _ => None,
    }
}

fn enqueue_pending_committed_text_locked(
    inner: &mut ServerState,
    client: ClientId,
    pane: PaneId,
    lane: CommittedTextLane,
    suppressed_character: Option<char>,
) {
    let stale = {
        let pending = inner.pending_committed_text.entry(client).or_default();
        let stale = (pending.len() >= MAX_PENDING_COMMITTED_TEXT)
            .then(|| pending.pop_front())
            .flatten();
        pending.push_back(PendingCommittedText {
            pane,
            lane,
            suppressed_character,
        });
        stale
    };
    if let Some(character) = suppressed_character {
        *inner
            .suppressed_text
            .entry(client)
            .or_default()
            .entry(character)
            .or_default() += 1;
    }
    if let Some(stale) = stale {
        retire_pending_committed_text_locked(inner, client, stale);
    }
}

fn suppress_committed_character_locked(
    inner: &mut ServerState,
    client: ClientId,
    pane: PaneId,
    lane: CommittedTextLane,
    character: char,
) {
    let tagged = if let Some(pending) = inner
        .pending_committed_text
        .get_mut(&client)
        .and_then(VecDeque::back_mut)
        .filter(|pending| {
            pending.pane == pane && pending.lane == lane && pending.suppressed_character.is_none()
        }) {
        pending.suppressed_character = Some(character);
        true
    } else {
        false
    };
    if !tagged {
        return;
    }
    *inner
        .suppressed_text
        .entry(client)
        .or_default()
        .entry(character)
        .or_default() += 1;
}

fn retire_pending_committed_text_locked(
    inner: &mut ServerState,
    client: ClientId,
    pending: PendingCommittedText,
) {
    let Some(character) = pending.suppressed_character else {
        return;
    };
    let remove_client = if let Some(characters) = inner.suppressed_text.get_mut(&client) {
        if let Some(count) = characters.get_mut(&character) {
            *count = count.saturating_sub(1);
        }
        characters.retain(|_, count| *count != 0);
        characters.is_empty()
    } else {
        false
    };
    if remove_client {
        inner.suppressed_text.remove(&client);
    }
}

fn read_only_blocks_input(input: &InputMessage) -> bool {
    match input {
        InputMessage::ResizeSplit { .. }
        | InputMessage::Popup { .. }
        | InputMessage::Menu { .. }
        | InputMessage::Confirm { .. } => true,
        InputMessage::TerminalView { action, .. } => {
            !terminal_view_action_is_read_only_safe(action)
        }
        InputMessage::Text { .. }
        | InputMessage::Key { .. }
        | InputMessage::BrowserSurfaceText { .. }
        | InputMessage::BrowserSurfaceKey { .. }
        | InputMessage::ChooseTree { .. }
        | InputMessage::ChooseBuffer { .. }
        | InputMessage::DisplayPanes { .. }
        | InputMessage::CommandPrompt { .. }
        | InputMessage::ResizeTerminal { .. }
        | InputMessage::ResizeCommandOutput { .. }
        | InputMessage::CommandOutputView { .. }
        | InputMessage::CancelPrefix { .. }
        | InputMessage::ClientTerminalSize { .. }
        | InputMessage::ClientFocus { .. } => false,
    }
}

fn terminal_view_action_is_read_only_safe(action: &zz_terminal::TerminalViewAction) -> bool {
    use zz_terminal::TerminalViewAction as Action;

    match action {
        Action::ScrollLines(_)
        | Action::ScrollPages(_)
        | Action::ScrollTop
        | Action::ScrollBottom
        | Action::ScrollToFraction(_)
        | Action::ScrollToOffset(_)
        | Action::ClearLinkHover
        | Action::EnterCopyMode
        | Action::EnterCopyModeScrollExit
        | Action::EnterCopyModeWith { .. } => true,
        Action::CopyMode(action) | Action::CopyModeCounted { action, .. } => {
            copy_mode_action_is_read_only_safe(action)
        }
        Action::SelectionPress(_)
        | Action::SelectionDrag(_)
        | Action::SelectionAutoscroll { .. }
        | Action::SelectionRelease(_)
        | Action::Mouse(_)
        | Action::ScrollWheel { .. }
        | Action::SelectAll
        | Action::ClearHistory
        | Action::ClearSelection
        | Action::SearchBegin(_)
        | Action::SearchUpdate(_)
        | Action::SearchNext
        | Action::SearchPrevious
        | Action::SearchClose
        | Action::CopySelection { .. }
        | Action::Focus(_)
        | Action::Paste(_) => false,
    }
}

fn terminal_view_action_is_mouse(action: &zz_terminal::TerminalViewAction) -> bool {
    matches!(
        action,
        zz_terminal::TerminalViewAction::Mouse(_)
            | zz_terminal::TerminalViewAction::ScrollWheel { .. }
    )
}

fn terminal_mouse_rejected(inner: &ServerState, client: ClientId, input: &InputMessage) -> bool {
    let (terminal, action) = match input {
        InputMessage::TerminalView { pane, action } => (inner.terminals.get(pane), action),
        InputMessage::Popup {
            action: PopupAction::TerminalView(action),
        } => (
            inner.popups.get(&client).map(|popup| &popup.terminal),
            action,
        ),
        _ => return false,
    };
    if !terminal_view_action_is_mouse(action)
        || !inner.client_sizes.contains_key(&client)
        || inner
            .engine
            .effective_mouse(client_attached_session(inner, client))
    {
        return false;
    }
    !terminal.is_some_and(|terminal| {
        terminal
            .latest_viewport_for(TerminalViewId(client.0))
            .unwrap_or_else(|| terminal.latest_viewport())
            .mouse_tracking
    })
}

fn wait_for_terminal_identity(terminal: &TerminalSession) {
    let deadline = Instant::now() + Duration::from_secs(2);
    while terminal.process_id().is_none() || cfg!(unix) && terminal.tty().is_none() {
        if terminal.completion().is_some() || Instant::now() >= deadline {
            return;
        }
        thread::sleep(Duration::from_millis(1));
    }
}

fn terminal_resizes_for_panes(
    inner: &ServerState,
    panes: &BTreeSet<PaneId>,
) -> Vec<(Arc<TerminalSession>, TerminalGeometry)> {
    panes
        .iter()
        .filter_map(|pane| terminal_resize_for_pane(inner, *pane))
        .collect()
}

fn apply_terminal_resizes(resizes: Vec<(Arc<TerminalSession>, TerminalGeometry)>) {
    for (terminal, geometry) in resizes {
        terminal.resize(
            geometry.columns,
            geometry.rows,
            geometry.cell_width_px,
            geometry.cell_height_px,
        );
    }
}

fn find_buffer<'a>(inner: &'a ServerState, name: Option<&str>) -> Option<&'a PasteBuffer> {
    inner
        .paste_buffers
        .iter()
        .find(|buffer| name.map_or(buffer.automatic, |name| buffer.name == name))
}

/// The row a keystroke selects, or `None` when nothing claims it. `mode_tree_key`
/// scans every line for the first item holding that key and turns the press into
/// `\r` right there, so a row shortcut beats the navigation table and the FIRST
/// of several duplicate rows wins. The scan sits below the prompt handling, so a
/// chooser mid-search keeps typing into the query instead.
fn chooser_row_for_key<T>(
    items: &[T],
    input: &zz_terminal::KeyInput,
    searching: bool,
    key: impl Fn(&T) -> &str,
) -> Option<u32> {
    if searching {
        return None;
    }
    let pressed = input_key_name(input);
    let pressed = pressed.as_str();
    if pressed.is_empty() {
        return None;
    }
    let row = items
        .iter()
        .position(|item| !key(item).is_empty() && key(item) == pressed)?;
    u32::try_from(row).ok()
}

/// The pin's stock chooser shortcut ladder: `0`-`9`, then `M-a`-`M-z`, then
/// nothing at all from row 36 on. `mode_tree_build_lines` spells it inline as
/// the fallback for modes with no key callback, and `choose-tree` /
/// `choose-buffer` reach the identical ladder through
/// `WINDOW_TREE_DEFAULT_KEY_FORMAT` / `WINDOW_BUFFER_DEFAULT_KEY_FORMAT`,
/// whose `#{line}` arithmetic produces exactly these strings.
fn default_chooser_row_key(line: usize) -> String {
    match line {
        0..=9 => line.to_string(),
        10..=35 => {
            let offset = u8::try_from(line - 10).expect("a row below 36 fits a byte");
            format!("M-{}", char::from(b'a' + offset))
        }
        _ => String::new(),
    }
}

/// A `-K` expansion becomes a shortcut only when it names a key some client can
/// actually press. The pin drops the rest the same way: `key_string_lookup_string`
/// answers `KEYC_UNKNOWN` and `mode_tree_build_lines` stores `KEYC_NONE`.
fn parsed_chooser_row_key(expanded: &str) -> String {
    let canonical = canonical_key(expanded);
    if canonical.len() > MAX_CHOOSE_ITEM_KEY_BYTES || !is_key_name(&canonical) {
        return String::new();
    }
    canonical
}

const CHOOSER_ROW_CONTEXT_FORMATS: [&str; 1] = ["line"];

fn chooser_row_variables(line: usize) -> BTreeMap<String, String> {
    let [line_name] = CHOOSER_ROW_CONTEXT_FORMATS;
    BTreeMap::from([(line_name.to_owned(), line.to_string())])
}

fn buffer_format_facts(buffer: &PasteBuffer) -> BufferFormatFacts {
    BufferFormatFacts {
        name: buffer.name.clone(),
        data: Arc::clone(&buffer.data),
        created: buffer.created,
    }
}

fn format_hook_facts(inner: &ServerState) -> FormatHookFacts {
    FormatHookFacts {
        mux: Arc::new(inner.engine.format_facts()),
        terminals: Arc::new(inner.terminals.clone()),
        pane_pipes: Arc::new(
            inner
                .pane_pipes
                .iter()
                .map(|(pane, pipe)| (*pane, pipe.pid))
                .collect(),
        ),
        session_attachments: Arc::new(
            inner
                .attached
                .iter()
                .map(|(session, clients)| {
                    let names = clients
                        .iter()
                        .filter_map(|client| inner.client_names.get(client))
                        .cloned()
                        .collect::<Vec<_>>()
                        .join(",");
                    (*session, (clients.len(), names))
                })
                .collect(),
        ),
        session_last_attached: Arc::new(inner.session_last_attached.clone()),
        clients: Arc::new(
            inner
                .attached
                .iter()
                .filter(|(session, _)| inner.engine.state.sessions.contains_key(session))
                .flat_map(|(session, clients)| {
                    clients.iter().map(move |client| (*client, *session))
                })
                .map(|(client, session)| {
                    client_format_facts(inner, client, session).loop_row(
                        inner
                            .client_activity
                            .get(&client)
                            .copied()
                            .unwrap_or_default(),
                    )
                })
                .collect(),
        ),
        buffer: inner
            .paste_buffers
            .iter()
            .find(|buffer| buffer.automatic)
            .map(buffer_format_facts),
        ..FormatHookFacts::default()
    }
}

fn format_hook_facts_for_client(
    inner: &ServerState,
    client: ClientId,
    context: &ExecutionContext,
) -> FormatHookFacts {
    let mut facts = format_hook_facts(inner);
    // format.c creates a command's tree with the invoking client, so `#{Vc:}`
    // reads that client's environment even when the format's own client is the
    // command's target.
    if let Some(invoking) = format_provenance_client(context, client) {
        facts.client_environment = Arc::new(client_environment_rows(
            inner.client_environments.get(&invoking),
        ));
    }
    if !context.has_no_client()
        && let Some(client) = format_provenance_client(context, client)
            .and_then(|client| current_format_client(inner, client))
    {
        facts.client = client_attached_session(inner, client)
            .map(|session| client_format_facts(inner, client, session));
    }
    facts
}

fn format_provenance_client(
    context: &ExecutionContext,
    invoking_client: ClientId,
) -> Option<ClientId> {
    context
        .replay_client()
        .or_else(|| context.control_command_target().map(|(client, _)| client))
        .or((invoking_client != ClientId(u64::MAX)).then_some(invoking_client))
}

fn selected_deferred_client(
    inner: &ServerState,
    context: &ExecutionContext,
    invoking_client: ClientId,
) -> Option<ClientId> {
    if context.has_no_client() {
        return None;
    }
    context
        .control_command_target()
        .map(|(client, _)| client)
        .or_else(|| {
            format_provenance_client(context, invoking_client)
                .and_then(|client| current_format_client(inner, client))
        })
}

fn current_format_client(inner: &ServerState, invoking_client: ClientId) -> Option<ClientId> {
    if client_attached_session(inner, invoking_client).is_some() {
        return Some(invoking_client);
    }
    if let Some(session) = inner
        .client_origins
        .get(&invoking_client)
        .and_then(|pane| inner.engine.state.window_for_pane(*pane))
        .and_then(|window| inner.engine.state.windows.get(&window))
        .map(|window| window.session)
    {
        return best_client_on_session(inner, session).or_else(|| best_attached_client(inner));
    }
    inner
        .engine
        .state
        .most_recent_context()
        .and_then(|(session, _, _)| best_client_on_session(inner, session))
        .or_else(|| best_attached_client(inner))
}

fn buffer_path_client_context(
    inner: &ServerState,
    client: ClientId,
) -> Option<(SessionId, WindowId, PaneId)> {
    let session = client_attached_session(inner, client)?;
    let session_state = inner.engine.state.sessions.get(&session)?;
    let window = client_focused_window(inner, client, session_state);
    let pane = inner.engine.state.windows.get(&window)?.active_pane;
    Some((session, window, pane))
}

fn buffer_path_format_target(
    inner: &ServerState,
    invoking_client: Option<ClientId>,
    context: &ExecutionContext,
    target_client: Option<&str>,
) -> (
    Option<ClientId>,
    (Option<SessionId>, Option<WindowId>, Option<PaneId>),
) {
    let client = match target_client {
        Some(target) => resolve_display_panes_client(inner, target).ok(),
        None => invoking_client.and_then(|client| current_format_client(inner, client)),
    };
    let target = client
        .and_then(|client| buffer_path_client_context(inner, client))
        .or_else(|| {
            invoking_client
                .is_none()
                .then_some((context.session?, context.window?, context.pane?))
        })
        .or_else(|| inner.engine.state.most_recent_context());
    let target = target.map_or((None, None, None), |(session, window, pane)| {
        (Some(session), Some(window), Some(pane))
    });
    (client, target)
}

fn expand_buffer_path(
    inner: &mut ServerState,
    invoking_client: Option<ClientId>,
    context: &ExecutionContext,
    target_client: Option<&str>,
    command_name: &str,
    path: &str,
) -> String {
    let (format_client, (session, window, pane)) =
        buffer_path_format_target(inner, invoking_client, context, target_client);
    inner.engine.set_format_now(unix_timestamp());
    let mut format_context = format_client
        .and_then(|client| client_attached_session(inner, client))
        .map_or_else(
            || inner.engine.format_status_context(session, window, pane),
            |client_session| {
                inner
                    .engine
                    .format_status_context_for_client(session, window, pane, client_session)
            },
        );
    inner
        .config_files
        .clone_into(&mut format_context.config_files);
    let facts = format_hook_facts(inner);
    let mut hooks =
        DaemonFormatHooks::command_with_optional_variables(&facts, context.format_variables())
            .with_option_engine(&inner.engine)
            .with_command_item(command_name);
    expand_format_values(path, &format_context, &mut hooks)
}

fn resolve_buffer<'a>(
    inner: &'a ServerState,
    name: Option<&str>,
) -> Result<&'a PasteBuffer, ServerError> {
    find_buffer(inner, name).ok_or_else(|| {
        name.map_or_else(
            || ServerError::MissingTarget("paste buffer".to_owned()),
            |name| ServerError::MissingTarget(name.to_owned()),
        )
    })
}

const WAIT_FOR_USAGE: &str = "usage: wait-for [-L|-S|-U] channel";

fn next_wait_token(inner: &mut ServerState) -> u64 {
    inner.next_wait_token = inner.next_wait_token.wrapping_add(1).max(1);
    inner.next_wait_token
}

fn remove_wait_channel_if_unused(channels: &mut BTreeMap<String, WaitChannel>, name: &str) {
    if channels
        .get(name)
        .is_some_and(|channel| !channel.locked && channel.waiters.is_empty() && channel.woken)
    {
        channels.remove(name);
    }
}

fn remove_wait_item(inner: &mut ServerState, name: &str, token: u64) {
    let Some(channel) = inner.wait_channels.get_mut(name) else {
        return;
    };
    channel.waiters.retain(|item| item.token != token);
    channel.lockers.retain(|item| item.token != token);
    remove_wait_channel_if_unused(&mut inner.wait_channels, name);
}

fn wake_wait_items(wakes: impl IntoIterator<Item = crossbeam_channel::Sender<()>>) {
    for wake in wakes {
        let _ = wake.try_send(());
    }
}

fn take_all_wait_wakes(
    channels: &mut BTreeMap<String, WaitChannel>,
) -> Vec<crossbeam_channel::Sender<()>> {
    let mut wakes = Vec::new();
    for (_, mut channel) in std::mem::take(channels) {
        wakes.extend(channel.waiters.drain(..).map(|item| item.wake));
        wakes.extend(channel.lockers.drain(..).map(|item| item.wake));
    }
    wakes
}

fn remove_client_wait_items(channels: &mut BTreeMap<String, WaitChannel>, client: ClientId) {
    for channel in channels.values_mut() {
        channel.waiters.retain(|item| item.client != client);
        channel.lockers.retain(|item| item.client != client);
    }
}

#[derive(Clone)]
enum InsertedCommandSource {
    Shell(String),
    String(String),
    Block(String),
}

struct CommandQueueExecution {
    draining: bool,
    wait_yields: bool,
    detached: bool,
    deferred_shutdown: Cell<DeferredShutdown>,
    deferred_control_exit: Cell<Option<ClientId>>,
    yielded: Cell<CommandQueueYield>,
    yield_boundary: bool,
    shutdown_blocker: RefCell<Option<ShutdownBlocker>>,
    pending_event_hooks: RefCell<Vec<PendingHookEvent>>,
    deferred_shell_jobs: RefCell<Vec<DeferredShellJob>>,
    callback_parse_failures: RefCell<Vec<CallbackParseFailure>>,
    deferred_config_replay_issues: RefCell<Vec<DeferredConfigReplayIssue>>,
    reported_failures: Cell<bool>,
    suppress_after_hooks: Cell<bool>,
    suppress_output: Cell<bool>,
}

type DeferredShellJob = Box<dyn FnOnce(&Arc<Shared>)>;

impl CommandQueueExecution {
    fn is_draining(&self) -> bool {
        self.draining || self.deferred_shutdown.get() == DeferredShutdown::Force
    }

    fn has_yielded(&self) -> bool {
        self.yielded.get() != CommandQueueYield::None
    }

    fn note_reported_failure(&self) {
        self.reported_failures.set(true);
    }

    fn callback_group_action_since(
        &self,
        start: usize,
        routed_name: &str,
        terminal_depth: usize,
    ) -> Option<CallbackGroupAction> {
        let failures = self.callback_parse_failures.borrow();
        select_callback_group_action(&failures[start..], routed_name, terminal_depth)
    }

    fn handle_callback_group_actions_since(&self, start: usize) {
        for failure in &mut self.callback_parse_failures.borrow_mut()[start..] {
            if failure.owner.is_replay_callback() && failure.depth == 1 {
                failure.group_action = CallbackGroupAction::Handled;
            }
        }
    }

    fn nest_callback_parse_failures_since(&self, start: usize) {
        for failure in &mut self.callback_parse_failures.borrow_mut()[start..] {
            if failure.owner.is_replay_callback() {
                failure.depth += 1;
            }
        }
    }

    fn yield_queue(&self) {
        self.yielded.set(CommandQueueYield::Propagate);
    }

    fn yield_locally(&self) {
        if !self.has_yielded() {
            self.yielded.set(CommandQueueYield::Local);
        }
    }

    fn ensure_shutdown_blocker(&self, shared: &Arc<Shared>) -> bool {
        let mut blocker = self.shutdown_blocker.borrow_mut();
        if blocker.is_none() {
            *blocker = ShutdownBlocker::acquire(shared, self.detached);
        }
        blocker.is_some()
    }

    fn fork_shutdown_blocker(&self, detached: bool) -> Option<ShutdownBlocker> {
        self.shutdown_blocker
            .borrow()
            .as_ref()
            .map(|blocker| blocker.fork(detached))
    }
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum CallbackGroupAction {
    Continue,
    Fail,
    Handled,
}

impl CallbackGroupAction {
    fn for_command(name: &str) -> Option<Self> {
        match name {
            "if-shell" => Some(Self::Fail),
            "run-shell" => Some(Self::Continue),
            _ => None,
        }
    }
}

#[derive(Clone)]
struct CallbackParseFailure {
    message: String,
    group_action: CallbackGroupAction,
    owner: CallbackFailureOwner,
    control_event: Option<Arc<()>>,
    depth: usize,
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum CallbackFailureOwner {
    Source,
    RuntimeCommand,
    Hook,
    CommandErrorHook,
}

impl CallbackFailureOwner {
    fn is_replay_callback(self) -> bool {
        matches!(self, Self::Source | Self::RuntimeCommand)
    }
}

impl CallbackParseFailure {
    fn for_command(
        message: String,
        name: &str,
        control_event: Option<Arc<()>>,
        depth: usize,
    ) -> Option<Self> {
        Some(Self {
            message,
            group_action: CallbackGroupAction::for_command(name)?,
            owner: CallbackFailureOwner::Source,
            control_event,
            depth,
        })
    }

    fn runtime_command(message: String, label: &str) -> Self {
        let name = label
            .strip_prefix('<')
            .and_then(|label| label.strip_suffix('>'))
            .unwrap_or(label)
            .split_ascii_whitespace()
            .next()
            .unwrap_or(label);
        Self {
            message,
            group_action: CallbackGroupAction::for_command(name)
                .unwrap_or(CallbackGroupAction::Handled),
            owner: CallbackFailureOwner::RuntimeCommand,
            control_event: None,
            depth: 0,
        }
    }
}

fn select_callback_group_action(
    failures: &[CallbackParseFailure],
    routed_name: &str,
    terminal_depth: usize,
) -> Option<CallbackGroupAction> {
    let mut continuing = false;
    for failure in failures.iter().filter(|failure| {
        failure.owner.is_replay_callback()
            && failure.group_action != CallbackGroupAction::Handled
            && failure.depth == 1
    }) {
        match failure.group_action {
            CallbackGroupAction::Fail => return Some(CallbackGroupAction::Fail),
            CallbackGroupAction::Continue => continuing = true,
            CallbackGroupAction::Handled => unreachable!(),
        }
    }
    continuing
        .then_some(CallbackGroupAction::Continue)
        .or_else(|| {
            (terminal_depth == 1)
                .then(|| CallbackGroupAction::for_command(routed_name))
                .flatten()
        })
}

