#[cfg(test)]
const RUN_SHELL_POSITION_CONTEXT_PATTERN: &str = "N";

fn run_shell_position_context_name(position: usize) -> String {
    position.to_string()
}

fn parse_run_shell_args(args: &[String]) -> Result<ParsedRunShellArgs, ServerError> {
    let parsed =
        parse_buffer_command_args("run-shell", args, &['c', 'd', 's', 't'], &['b', 'C', 'E'])?;
    let delay_value = parsed.value('d');
    let delay = delay_value.map(parse_shell_delay).transpose()?;
    let positive_delay = delay_value
        .and_then(parse_shell_delay_seconds)
        .is_some_and(|seconds| seconds > 0.0);
    let positional_start = args.len().saturating_sub(parsed.positional.len());
    Ok(ParsedRunShellArgs {
        background: parsed.has('b'),
        command_mode: parsed.has('C'),
        show_stderr: parsed.has('E'),
        cwd: parsed.value('c').map(str::to_owned),
        delay,
        positive_delay,
        target: parsed.value('t').map(str::to_owned),
        positional: parsed.positional,
        positional_start,
    })
}

fn parse_if_shell_args(args: &[String]) -> Result<ParsedIfShellArgs, ServerError> {
    let parsed = parse_buffer_command_args("if-shell", args, &['t'], &['b', 'F'])?;
    let positional_start = args.len().saturating_sub(parsed.positional.len());
    Ok(ParsedIfShellArgs {
        background: parsed.has('b'),
        format: parsed.has('F'),
        target: parsed.value('t').map(str::to_owned),
        positional: parsed.positional,
        positional_start,
    })
}

fn parse_shell_delay(value: &str) -> Result<Duration, ServerError> {
    let seconds = parse_shell_delay_seconds(value)
        .ok_or_else(|| ServerError::InvalidCommand(format!("invalid delay time: {value}")))?;
    Duration::try_from_secs_f64(seconds)
        .map_err(|_| ServerError::InvalidCommand(format!("invalid delay time: {value}")))
}

fn parse_shell_delay_seconds(value: &str) -> Option<f64> {
    if value.is_empty() {
        return Some(0.0);
    }
    let value = value.trim_start_matches(char::is_whitespace);
    if value.is_empty() {
        return Some(0.0);
    }
    let (negative, unsigned) = value
        .strip_prefix('-')
        .map_or((false, value), |value| (true, value));
    let unsigned = unsigned.strip_prefix('+').unwrap_or(unsigned);
    let seconds = if let Some(hex) = unsigned
        .strip_prefix("0x")
        .or_else(|| unsigned.strip_prefix("0X"))
    {
        u64::from_str_radix(hex, 16).ok()? as f64
    } else {
        value.parse::<f64>().ok()?
    };
    let seconds = if negative { -seconds } else { seconds };
    (seconds.is_finite() && seconds >= 0.0).then_some(seconds)
}

fn typed_inserted_command_source(argument: &str, command_block: bool) -> InsertedCommandSource {
    if command_block && let Some(body) = command_block_body(argument) {
        return InsertedCommandSource::Block(body.to_owned());
    }
    InsertedCommandSource::String(argument.to_owned())
}

fn select_if_shell_branch(
    branches: &[InsertedCommandSource],
    truthy: bool,
) -> Option<&InsertedCommandSource> {
    if truthy {
        branches.first()
    } else {
        branches.get(1)
    }
}

fn merge_command_streams(response: CommandResponse, streams: &CommandStreams) -> CommandResponse {
    match response {
        CommandResponse::Success {
            request_id,
            mut output,
            exit_code,
            mut stderr,
        } => {
            append_inserted_output(&mut output, &streams.stdout);
            if !streams.control_error.is_empty() {
                return CommandResponse::Error {
                    request_id,
                    error: ServerError::InvalidCommand(streams.control_error.clone()),
                    output,
                };
            }
            stderr.push_str(&streams.stderr);
            let exit_code = if exit_code == 0 {
                streams.exit_code
            } else {
                exit_code
            };
            CommandResponse::Success {
                request_id,
                output,
                exit_code,
                stderr,
            }
        }
        CommandResponse::Error {
            request_id,
            error,
            mut output,
        } => {
            append_inserted_output(&mut output, &streams.stdout);
            append_inserted_output(&mut output, &streams.control_error);
            CommandResponse::Error {
                request_id,
                error,
                output,
            }
        }
    }
}

fn append_inserted_output(output: &mut String, addition: &str) {
    if addition.is_empty() {
        return;
    }
    if !output.is_empty() && !output.ends_with('\n') {
        output.push('\n');
    }
    output.push_str(addition);
}

fn prepend_command_output(mut output: String, error: DaemonError) -> DaemonError {
    if output.is_empty() {
        return error;
    }
    match error {
        DaemonError::CommandExit {
            output: error_output,
            exit_code,
        } => {
            append_inserted_output(&mut output, &error_output);
            DaemonError::CommandExit { output, exit_code }
        }
        DaemonError::ReportedCommandExit {
            output: error_output,
            exit_code,
        } => {
            append_inserted_output(&mut output, &error_output);
            DaemonError::ReportedCommandExit { output, exit_code }
        }
        DaemonError::CommandFailed {
            output: error_output,
            error,
        } => {
            append_inserted_output(&mut output, &error_output);
            DaemonError::CommandFailed { output, error }
        }
        error => DaemonError::CommandFailed {
            output,
            error: Box::new(error),
        },
    }
}

fn discard_all_command_output(error: DaemonError) -> DaemonError {
    match error {
        DaemonError::CommandExit { exit_code, .. } => DaemonError::CommandExit {
            output: String::new(),
            exit_code,
        },
        DaemonError::ReportedCommandExit { exit_code, .. } => DaemonError::ReportedCommandExit {
            output: String::new(),
            exit_code,
        },
        DaemonError::CommandFailed { error, .. } => discard_all_command_output(*error),
        error => error,
    }
}

fn inserted_execution(
    client: ClientId,
    kind: ClientKind,
    result: InsertedCommandResult,
) -> Result<Execution, DaemonError> {
    if matches!(kind, ClientKind::Command | ClientKind::Control)
        && client != ClientId(u64::MAX)
        && result.exit_code != 0
    {
        Err(DaemonError::CommandExit {
            output: result.output,
            exit_code: result.exit_code,
        })
    } else {
        Ok(Execution {
            output: result.output,
            effects: Vec::new(),
        })
    }
}

fn job_working_directory(
    inner: &ServerState,
    context: &ExecutionContext,
    requested: Option<&str>,
) -> PathBuf {
    if let Some(requested) = requested {
        return PathBuf::from(requested);
    }
    context
        .pane
        .and_then(|pane| inner.terminals.get(&pane))
        .and_then(|terminal| terminal_working_directory(terminal))
        .filter(|path| path.is_dir())
        .or_else(|| std::env::current_dir().ok().filter(|path| path.is_dir()))
        .unwrap_or_else(fallback_job_working_directory)
}

fn shell_job_working_directory(
    inner: &ServerState,
    invoking_client: ClientId,
    context: &ExecutionContext,
    requested: Option<&str>,
) -> PathBuf {
    if let Some(requested) = requested {
        return PathBuf::from(requested);
    }
    let client = (!context.has_no_client())
        .then(|| format_provenance_client(context, invoking_client))
        .flatten();
    let attached_session = client.and_then(|client| client_attached_session(inner, client));
    inner
        .startup_source_client_working_directory
        .clone()
        .or_else(|| {
            attached_session
                .is_none()
                .then(|| {
                    client.and_then(|client| inner.client_working_directories.get(&client).cloned())
                })
                .flatten()
        })
        .or_else(|| {
            context
                .session
                .and_then(|session| inner.engine.state.session_working_directory(session))
                .map(Path::to_owned)
        })
        .or_else(|| {
            attached_session
                .and_then(|session| inner.engine.state.session_working_directory(session))
                .map(Path::to_owned)
        })
        .unwrap_or_else(default_job_working_directory)
}

fn default_job_working_directory() -> PathBuf {
    home_directory().unwrap_or_else(|| PathBuf::from("/"))
}

fn fallback_job_working_directory() -> PathBuf {
    home_directory()
        .filter(|path| path.is_dir())
        .unwrap_or_else(|| PathBuf::from("/"))
}

fn existing_job_working_directory(path: &Path) -> Cow<'_, Path> {
    if path.is_dir() {
        Cow::Borrowed(path)
    } else {
        Cow::Owned(fallback_job_working_directory())
    }
}

fn daemon_error_text(error: &DaemonError) -> String {
    match error {
        DaemonError::CommandFailed { error, .. } => daemon_error_text(error),
        DaemonError::InsertedCommandParse(message) => message.clone(),
        DaemonError::Server(error) => server_error_text(error),
        error => error.to_string(),
    }
}

fn server_error_text(error: &ServerError) -> String {
    error.tmux_message()
}

fn discard_command_output(error: DaemonError) -> DaemonError {
    match error {
        DaemonError::CommandFailed { error, .. } => discard_command_output(*error),
        error => error,
    }
}

fn daemon_error_output(error: &DaemonError) -> Option<&str> {
    match error {
        DaemonError::CommandExit { output, .. }
        | DaemonError::ReportedCommandExit { output, .. }
        | DaemonError::CommandFailed { output, .. }
            if !output.is_empty() =>
        {
            Some(output)
        }
        _ => None,
    }
}

fn control_command_guard_for_execution(
    result: &Result<Execution, DaemonError>,
    mode: InsertedCommandMode,
) -> (String, bool, bool) {
    match result {
        Ok(execution) => (execution.output.clone(), false, false),
        Err(DaemonError::CommandExit { output, .. })
            if matches!(mode, InsertedCommandMode::CommandAlias { .. }) =>
        {
            (output.clone(), false, false)
        }
        Err(error) => {
            let mut output = daemon_error_output(error).unwrap_or_default().to_owned();
            let (error, sticky_failure, message) = control_command_guard_error(error);
            append_inserted_output(&mut output, &message);
            (output, error, sticky_failure)
        }
    }
}

fn control_command_guard_error(error: &DaemonError) -> (bool, bool, String) {
    match error {
        DaemonError::CommandFailed { error, .. } => control_command_guard_error(error),
        DaemonError::ReportedCommandExit { .. }
        | DaemonError::Server(ServerError::UnsupportedCommand(_)) => (false, false, String::new()),
        DaemonError::InsertedCommandParse(message)
        | DaemonError::Server(ServerError::CommandParse(message)) => (true, false, message.clone()),
        DaemonError::Server(error) => (true, true, error.tmux_message()),
        error => (true, true, daemon_error_text(error)),
    }
}

fn post_admission_callback_parse_depth(error: &DaemonError) -> usize {
    match error {
        DaemonError::CommandFailed { error, .. } => post_admission_callback_parse_depth(error),
        DaemonError::Server(error) => server_post_admission_callback_parse_depth(error),
        _ => 0,
    }
}

fn command_parse_error(error: &DaemonError) -> bool {
    match error {
        DaemonError::CommandFailed { error, .. } => command_parse_error(error),
        DaemonError::Server(ServerError::CommandParse(_)) => true,
        _ => false,
    }
}

fn server_post_admission_callback_parse_depth(error: &ServerError) -> usize {
    match error {
        ServerError::PostAdmissionCallback(error) if error.is_command_parse() => {
            1 + server_post_admission_callback_parse_depth(error)
        }
        _ => 0,
    }
}

fn hook_resolution_error(error: &DaemonError) -> bool {
    match error {
        DaemonError::CommandFailed { error, .. } => hook_resolution_error(error),
        DaemonError::Server(error) => hook_resolution_server_error(error),
        _ => false,
    }
}

fn hook_resolution_server_error(error: &ServerError) -> bool {
    match error {
        ServerError::PostAdmissionCallback(error) => hook_resolution_server_error(error),
        ServerError::MissingTarget(_)
        | ServerError::SessionNotFound(_)
        | ServerError::WindowNotFound(_)
        | ServerError::PaneNotFound(_)
        | ServerError::PaneNotAttached(_)
        | ServerError::PaneExited(_) => true,
        _ => false,
    }
}

fn uppercase_first(message: &mut String) {
    let Some(first) = message.chars().next() else {
        return;
    };
    let length = first.len_utf8();
    message.replace_range(..length, &first.to_uppercase().collect::<String>());
}

#[derive(Debug, Default)]
struct ParsedBufferCommandArgs {
    flags: BTreeSet<char>,
    values: BTreeMap<char, String>,
    repeated_values: BTreeMap<char, Vec<String>>,
    positional: Vec<String>,
}

impl ParsedBufferCommandArgs {
    fn has(&self, flag: char) -> bool {
        self.flags.contains(&flag)
    }

    fn value(&self, option: char) -> Option<&str> {
        self.values.get(&option).map(String::as_str)
    }

    fn values(&self, option: char) -> impl Iterator<Item = &str> {
        self.repeated_values
            .get(&option)
            .into_iter()
            .flatten()
            .map(String::as_str)
    }
}

fn parse_control_pane_state(value: &str) -> Option<(PaneId, &str)> {
    let (pane, state) = value.split_once(':')?;
    Some((pane.parse().ok()?, state))
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum ControlClientSizeUpdate {
    Client(TerminalGeometry),
    Window(WindowId, Option<TerminalGeometry>),
}

fn parse_control_dimensions(value: &str, separator: char) -> Option<(u64, u64)> {
    let (columns, rows) = value.split_once(separator)?;
    if columns.is_empty() || rows.is_empty() || rows.contains(separator) {
        return None;
    }
    Some((columns.parse().ok()?, rows.parse().ok()?))
}

fn checked_control_geometry(columns: u64, rows: u64) -> Result<TerminalGeometry, ServerError> {
    let in_range =
        |value| (u64::from(CONTROL_SIZE_MINIMUM)..=u64::from(WINDOW_SIZE_MAXIMUM)).contains(&value);
    if !in_range(columns) || !in_range(rows) {
        return Err(ServerError::InvalidCommand(
            "size too small or too big".to_owned(),
        ));
    }
    Ok(TerminalGeometry {
        columns: u16::try_from(columns).expect("validated control columns fit u16"),
        rows: u16::try_from(rows).expect("validated control rows fit u16"),
        cell_width_px: CONTROL_CELL_WIDTH_PX,
        cell_height_px: CONTROL_CELL_HEIGHT_PX,
    })
}

fn parse_control_client_size(value: &str) -> Result<ControlClientSizeUpdate, ServerError> {
    if let Some((window, size)) = value.split_once(':')
        && value.matches(':').count() == 1
        && let Ok(window) = window.parse::<WindowId>()
    {
        if size.is_empty() {
            return Ok(ControlClientSizeUpdate::Window(window, None));
        }
        let (columns, rows) = parse_control_dimensions(size, 'x')
            .ok_or_else(|| ServerError::InvalidCommand("bad size argument".to_owned()))?;
        return checked_control_geometry(columns, rows)
            .map(|geometry| ControlClientSizeUpdate::Window(window, Some(geometry)));
    }
    let dimensions = parse_control_dimensions(value, ',')
        .or_else(|| parse_control_dimensions(value, 'x'))
        .ok_or_else(|| ServerError::InvalidCommand("bad size argument".to_owned()))?;
    checked_control_geometry(dimensions.0, dimensions.1).map(ControlClientSizeUpdate::Client)
}

enum ControlSubscriptionUpdate<'a> {
    Remove(&'a str),
    Set {
        name: &'a str,
        scope: ControlSubscriptionScope,
        format: &'a str,
    },
}

fn parse_control_subscription(value: &str) -> ControlSubscriptionUpdate<'_> {
    let mut fields = value.splitn(3, ':');
    let name = fields.next().unwrap_or_default();
    let Some(what) = fields.next() else {
        return ControlSubscriptionUpdate::Remove(value);
    };
    let Some(format) = fields.next() else {
        return ControlSubscriptionUpdate::Remove(value);
    };
    let scope = match what {
        "%*" => ControlSubscriptionScope::AllPanes,
        "@*" => ControlSubscriptionScope::AllWindows,
        what if what.starts_with('%') => what.parse().map_or(
            ControlSubscriptionScope::Session,
            ControlSubscriptionScope::Pane,
        ),
        what if what.starts_with('@') => what.parse().map_or(
            ControlSubscriptionScope::Session,
            ControlSubscriptionScope::Window,
        ),
        _ => ControlSubscriptionScope::Session,
    };
    ControlSubscriptionUpdate::Set {
        name,
        scope,
        format,
    }
}

fn control_subscription_target(
    session: SessionId,
    window: Option<&zz_mux::Window>,
    pane: Option<PaneId>,
) -> ControlSubscriptionTarget {
    ControlSubscriptionTarget {
        session,
        window: window.map(|window| window.id),
        window_index: window.map(|window| window.index),
        pane,
    }
}

fn control_subscription_targets(
    inner: &ServerState,
    session: SessionId,
    scope: ControlSubscriptionScope,
) -> Vec<ControlSubscriptionTarget> {
    let Some(session_state) = inner.engine.state.sessions.get(&session) else {
        return Vec::new();
    };
    match scope {
        ControlSubscriptionScope::Session => {
            vec![control_subscription_target(session, None, None)]
        }
        ControlSubscriptionScope::Pane(pane) => {
            let Some(window) = inner
                .engine
                .state
                .window_for_pane(pane)
                .and_then(|window| inner.engine.state.windows.get(&window))
                .filter(|window| window.session == session)
            else {
                return Vec::new();
            };
            vec![control_subscription_target(
                session,
                Some(window),
                Some(pane),
            )]
        }
        ControlSubscriptionScope::Window(window) => inner
            .engine
            .state
            .windows
            .get(&window)
            .filter(|window| window.session == session)
            .map(|window| vec![control_subscription_target(session, Some(window), None)])
            .unwrap_or_default(),
        ControlSubscriptionScope::AllPanes => session_state
            .windows
            .iter()
            .filter_map(|window| inner.engine.state.windows.get(window))
            .flat_map(|window| {
                window
                    .panes
                    .keys()
                    .copied()
                    .map(|pane| control_subscription_target(session, Some(window), Some(pane)))
            })
            .collect(),
        ControlSubscriptionScope::AllWindows => session_state
            .windows
            .iter()
            .filter_map(|window| inner.engine.state.windows.get(window))
            .map(|window| control_subscription_target(session, Some(window), None))
            .collect(),
    }
}

fn apply_control_client_flags(output: &mut ControlClientOutput, flags: &str) {
    for raw in flags.split(',') {
        let (clear, flag) = raw
            .strip_prefix('!')
            .map_or((false, raw), |flag| (true, flag));
        match flag {
            "no-output" => {
                output.no_output = !clear;
                output.panes.clear();
            }
            "wait-exit" => output.wait_exit = !clear,
            "pause-after" => {
                output.pause_after_ms = (!clear).then_some(0);
            }
            _ => {
                let Some(value) = flag.strip_prefix("pause-after=") else {
                    continue;
                };
                let Some(milliseconds) = parse_pause_after_milliseconds(value) else {
                    continue;
                };
                output.pause_after_ms = (!clear).then_some(milliseconds);
            }
        }
    }
}

fn parse_pause_after_milliseconds(value: &str) -> Option<u64> {
    let mut bytes = value.bytes().skip_while(u8::is_ascii_whitespace).peekable();
    let negative = match bytes.peek() {
        Some(b'+') => {
            bytes.next();
            false
        }
        Some(b'-') => {
            bytes.next();
            true
        }
        _ => false,
    };
    let mut magnitude = 0_u64;
    let mut overflow = false;
    let mut parsed = false;
    while let Some(byte) = bytes.next_if(u8::is_ascii_digit) {
        parsed = true;
        let digit = u64::from(byte - b'0');
        match magnitude
            .checked_mul(10)
            .and_then(|value| value.checked_add(digit))
        {
            Some(value) if !overflow => magnitude = value,
            _ => {
                magnitude = u64::MAX;
                overflow = true;
            }
        }
    }
    if !parsed {
        return None;
    }
    let mut seconds = magnitude as u32;
    if negative && !overflow {
        seconds = seconds.wrapping_neg();
    }
    Some(u64::from(seconds.wrapping_mul(1000)))
}

fn parse_buffer_command_args(
    command: &str,
    args: &[String],
    value_options: &[char],
    flags: &[char],
) -> Result<ParsedBufferCommandArgs, ServerError> {
    let mut parsed = ParsedBufferCommandArgs::default();
    let mut index = 0;
    while let Some(argument) = args.get(index) {
        if argument == "--" {
            parsed.positional.extend(args[index + 1..].iter().cloned());
            break;
        }
        if !argument.starts_with('-') || argument == "-" {
            parsed.positional.extend(args[index..].iter().cloned());
            break;
        }

        let mut consumed_next = false;
        for (offset, option) in argument[1..].char_indices() {
            if value_options.contains(&option) {
                let value_start = 1 + offset + option.len_utf8();
                let value = if value_start < argument.len() {
                    argument[value_start..].to_owned()
                } else {
                    consumed_next = true;
                    args.get(index + 1).cloned().ok_or_else(|| {
                        ServerError::CommandParse(format!("{command} -{option} requires a value"))
                    })?
                };
                parsed.values.insert(option, value.clone());
                parsed
                    .repeated_values
                    .entry(option)
                    .or_default()
                    .push(value);
                break;
            }
            if flags.contains(&option) {
                parsed.flags.insert(option);
            } else {
                return Err(ServerError::CommandParse(format!(
                    "unsupported command: {command} -{option}"
                )));
            }
        }
        index += usize::from(consumed_next) + 1;
    }
    if let Some(spec) = zz_protocol::catalog_command_spec(command) {
        spec.validate_positional_minimum(parsed.positional.len())?;
        spec.validate_positional_maximum(parsed.positional.len())?;
    }
    Ok(parsed)
}

fn require_no_positionals(
    command: &str,
    parsed: &ParsedBufferCommandArgs,
) -> Result<(), ServerError> {
    if parsed.positional.is_empty() {
        Ok(())
    } else {
        Err(ServerError::CommandParse(format!(
            "{command} does not accept positional arguments"
        )))
    }
}

fn require_one_positional<'a>(
    command: &str,
    parsed: &'a ParsedBufferCommandArgs,
) -> Result<&'a str, ServerError> {
    let [value] = parsed.positional.as_slice() else {
        return Err(ServerError::CommandParse(format!(
            "{command} requires exactly one path"
        )));
    };
    Ok(value)
}

fn validate_paste_buffer_size(size: usize) -> Result<(), ServerError> {
    if size > MAX_PASTE_BUFFER_BYTES {
        Err(ServerError::InvalidCommand(format!(
            "paste buffer exceeds {MAX_PASTE_BUFFER_BYTES} bytes"
        )))
    } else {
        Ok(())
    }
}

fn validate_paste_buffer_name(name: &str) -> Result<(), ServerError> {
    if name.is_empty() {
        return Err(ServerError::InvalidCommand(
            "paste buffer name cannot be empty".to_owned(),
        ));
    }
    if name.len() > MAX_PASTE_BUFFER_NAME_BYTES {
        return Err(ServerError::InvalidCommand(format!(
            "paste buffer name exceeds {MAX_PASTE_BUFFER_NAME_BYTES} bytes"
        )));
    }
    if name.chars().any(char::is_control) {
        return Err(ServerError::InvalidCommand(
            "paste buffer name contains control characters".to_owned(),
        ));
    }
    Ok(())
}

fn insert_paste_buffer(
    inner: &mut ServerState,
    requested_name: Option<&str>,
    automatic_prefix: &str,
    data: Vec<u8>,
    replacement_delete: bool,
) -> Result<Vec<PendingHookEvent>, ServerError> {
    if data.is_empty() {
        return Ok(Vec::new());
    }
    let mut events = Vec::new();
    validate_paste_buffer_size(data.len())?;
    let (name, automatic) = if let Some(name) = requested_name {
        validate_paste_buffer_name(name)?;
        (name.to_owned(), false)
    } else {
        let mut name = None;
        for _ in 0..inner.paste_buffers.len().saturating_add(1) {
            let candidate = format!("{automatic_prefix}{}", inner.next_buffer_id);
            inner.next_buffer_id = inner.next_buffer_id.wrapping_add(1);
            validate_paste_buffer_name(&candidate)?;
            if !inner
                .paste_buffers
                .iter()
                .any(|buffer| buffer.name == candidate)
            {
                name = Some(candidate);
                break;
            }
        }
        let name = name.ok_or_else(|| {
            ServerError::InvalidCommand("no automatic paste buffer names available".to_owned())
        })?;
        while inner
            .paste_buffers
            .iter()
            .filter(|buffer| buffer.automatic)
            .count()
            >= inner.automatic_paste_buffer_limit.0
        {
            let Some(index) = inner
                .paste_buffers
                .iter()
                .rposition(|buffer| buffer.automatic)
            else {
                break;
            };
            let removed = inner.paste_buffers.remove(index);
            events.push(PendingHookEvent::paste_buffer(
                "paste-buffer-deleted",
                removed.name,
            ));
        }
        (name, true)
    };

    let utf8 = std::str::from_utf8(&data).is_ok();
    inner.paste_buffers.retain(|buffer| {
        if buffer.name == name {
            if replacement_delete {
                events.push(PendingHookEvent::paste_buffer(
                    "paste-buffer-deleted",
                    buffer.name.clone(),
                ));
            }
            false
        } else {
            true
        }
    });
    inner.paste_buffers.insert(
        0,
        PasteBuffer {
            name: name.clone(),
            data: Arc::from(data),
            created: SystemTime::now(),
            automatic,
            utf8,
        },
    );
    events.push(PendingHookEvent::paste_buffer("paste-buffer-changed", name));
    Ok(events)
}

fn rename_paste_buffer(
    inner: &mut ServerState,
    requested_name: Option<&str>,
    new_name: &str,
) -> Result<Vec<PendingHookEvent>, ServerError> {
    let mut source_index = match requested_name {
        Some(name) => inner
            .paste_buffers
            .iter()
            .position(|buffer| buffer.name == name)
            .ok_or_else(|| ServerError::InvalidCommand(format!("unknown buffer: {name}")))?,
        None => inner
            .paste_buffers
            .iter()
            .position(|buffer| buffer.automatic)
            .ok_or_else(|| ServerError::InvalidCommand("no buffer".to_owned()))?,
    };
    if new_name.is_empty() {
        return Err(ServerError::InvalidCommand("new name is empty".to_owned()));
    }
    validate_paste_buffer_name(new_name)?;
    if inner.paste_buffers[source_index].name == new_name {
        return Ok(Vec::new());
    }

    let mut events = Vec::new();
    if let Some(destination_index) = inner
        .paste_buffers
        .iter()
        .position(|buffer| buffer.name == new_name)
    {
        let removed = inner.paste_buffers.remove(destination_index);
        events.push(PendingHookEvent::paste_buffer(
            "paste-buffer-deleted",
            removed.name,
        ));
        if destination_index < source_index {
            source_index -= 1;
        }
    }

    let source = &mut inner.paste_buffers[source_index];
    let old_name = std::mem::replace(&mut source.name, new_name.to_owned());
    source.automatic = false;
    events.push(PendingHookEvent::paste_buffer(
        "paste-buffer-deleted",
        old_name,
    ));
    events.push(PendingHookEvent::paste_buffer(
        "paste-buffer-changed",
        new_name.to_owned(),
    ));
    Ok(events)
}

/// Where a buffer path that is not absolute hangs from. The pin asks
/// `server_client_get_cwd(c, NULL)` inside `file_get_path`: the config client
/// during startup, an unattached client's own cwd, then that client's attached
/// session cwd, then home.
fn client_file_working_directory(inner: &ServerState, client: Option<ClientId>) -> PathBuf {
    if let Some(startup) = inner.startup_source_client_working_directory.clone() {
        return startup;
    }
    let attached = client.and_then(|client| client_attached_session(inner, client));
    if attached.is_none()
        && let Some(cwd) = client.and_then(|client| inner.client_working_directories.get(&client))
    {
        return cwd.clone();
    }
    attached
        .and_then(|session| inner.engine.state.session_working_directory(session))
        .map_or_else(default_job_working_directory, Path::to_owned)
}

/// The absolute path a buffer command names, expanded once in the daemon the
/// way `file_get_path` does: a leading `~/` against the server's own home, and
/// anything else relative against the invoking client's working directory.
fn buffer_file_path(inner: &ServerState, client: Option<ClientId>, path: &str) -> PathBuf {
    let expanded = expand_path(path);
    if expanded.is_absolute() {
        return expanded;
    }
    client_file_working_directory(inner, client).join(expanded)
}

fn read_paste_buffer_file(path: &Path) -> Result<Vec<u8>, ServerError> {
    let file = fs::File::open(path).map_err(|error| buffer_file_error(path, &error))?;
    if file
        .metadata()
        .map_err(|error| buffer_file_error(path, &error))?
        .len()
        > u64::try_from(MAX_PASTE_BUFFER_BYTES).expect("paste buffer limit fits in u64")
    {
        return Err(ServerError::InvalidCommand(format!(
            "{}: paste buffer exceeds {MAX_PASTE_BUFFER_BYTES} bytes",
            path.display()
        )));
    }
    let mut data = Vec::new();
    file.take(
        u64::try_from(MAX_PASTE_BUFFER_BYTES)
            .expect("paste buffer limit fits in u64")
            .saturating_add(1),
    )
    .read_to_end(&mut data)
    .map_err(|error| buffer_file_error(path, &error))?;
    validate_paste_buffer_size(data.len())?;
    Ok(data)
}

fn write_paste_buffer_file(path: &Path, data: &[u8], append: bool) -> Result<(), ServerError> {
    let mut options = fs::OpenOptions::new();
    options.write(true).create(true);
    if append {
        options.append(true);
    } else {
        options.truncate(true);
    }
    let mut file = options
        .open(path)
        .map_err(|error| buffer_file_error(path, &error))?;
    file.write_all(data)
        .and_then(|()| file.flush())
        .map_err(|error| buffer_file_error(path, &error))
}

/// The pin reports a buffer file failure as `cmdq_error(item, "%s: %s",
/// strerror(cf->error), cf->path)` in both cmd-load-buffer.c and
/// cmd-save-buffer.c: the reason, then the path it expanded.
fn buffer_file_error(path: &Path, error: &std::io::Error) -> ServerError {
    client_file_failure(&crate::strerror_text(error), path)
}

fn client_file_failure(reason: &str, path: &Path) -> ServerError {
    ServerError::InvalidCommand(format!("{reason}: {}", path.display()))
}

#[derive(Debug)]
struct ParsedCapturePane {
    target: Option<String>,
    buffer_name: Option<String>,
    start: Option<String>,
    end: Option<String>,
    options: CaptureOptions,
    print: bool,
    quiet: bool,
}

fn parse_capture_pane_args(args: &[String]) -> Result<ParsedCapturePane, ServerError> {
    let args = parse_buffer_command_args(
        "capture-pane",
        args,
        &['b', 'E', 'S', 't'],
        &['a', 'e', 'J', 'M', 'N', 'p', 'T', 'q'],
    )?;
    require_no_positionals("capture-pane", &args)?;
    let options = CaptureOptions {
        alternate: args.has('a'),
        escape_sequences: args.has('e'),
        join_wrapped: args.has('J'),
        mode: args.has('M'),
        preserve_trailing: args.has('J') || args.has('N'),
        ..CaptureOptions::default()
    };
    let parsed = ParsedCapturePane {
        target: args.value('t').map(str::to_owned),
        buffer_name: args.value('b').map(str::to_owned),
        start: args.value('S').map(str::to_owned),
        end: args.value('E').map(str::to_owned),
        options,
        print: args.has('p'),
        quiet: args.has('q'),
    };
    Ok(parsed)
}

fn resolve_capture_boundary(
    engine: &MuxEngine,
    value: Option<&str>,
    start: bool,
    target: &ExecutionContext,
    active_session: Option<SessionId>,
    format_client: FormatClient,
    hooks: &mut impl StatusHooks,
) -> CaptureBoundary {
    let Some(value) = value else {
        return default_capture_boundary(start);
    };
    if value == "-" {
        return if start {
            CaptureBoundary::HistoryStart
        } else {
            CaptureBoundary::VisibleEnd
        };
    }
    let expanded = engine.expand_pane_format(value, target, active_session, format_client, hooks);
    expanded
        .parse::<i64>()
        .ok()
        .filter(|line| *line >= i64::from(i32::MIN) && *line <= i64::from(i16::MAX))
        .map_or_else(
            || default_capture_boundary(start),
            CaptureBoundary::Relative,
        )
}

fn default_capture_boundary(start: bool) -> CaptureBoundary {
    if start {
        CaptureBoundary::Relative(0)
    } else {
        CaptureBoundary::VisibleEnd
    }
}

#[derive(Debug, Default, PartialEq, Eq)]
struct ContextReference {
    path: String,
    start: Option<u32>,
    end: Option<u32>,
}

impl ContextReference {
    fn parse(value: &str) -> Result<Self, ServerError> {
        let invalid = |message: &str| ServerError::InvalidCommand(message.to_owned());
        let (path, range) = match value.rsplit_once(':') {
            Some((path, range)) if !path.is_empty() && parse_line_range(range).is_some() => {
                (path, parse_line_range(range))
            }
            _ => (value, None),
        };
        if path.is_empty() || path.len() > MAX_CONTEXT_PATH_BYTES {
            return Err(invalid("--context path must be 1..=4096 bytes"));
        }
        if path.chars().any(char::is_control) {
            return Err(invalid(
                "--context path must not contain control characters",
            ));
        }
        let (start, end) = range.unwrap_or((None, None));
        if let (Some(start), Some(end)) = (start, end)
            && start > end
        {
            return Err(invalid("--context line range must not run backwards"));
        }
        Ok(Self {
            path: path.to_owned(),
            start,
            end,
        })
    }

    fn header(&self) -> String {
        match (self.start, self.end) {
            (Some(start), Some(end)) => format!("{}:{start}-{end}", self.path),
            (Some(start), None) => format!("{}:{start}", self.path),
            _ => self.path.clone(),
        }
    }
}

fn parse_line_range(value: &str) -> Option<(Option<u32>, Option<u32>)> {
    if let Some((start, end)) = value.split_once('-') {
        return Some((Some(start.parse().ok()?), Some(end.parse().ok()?)));
    }
    Some((Some(value.parse().ok()?), None))
}

