    #[test]
    fn control_hook_inventory_carries_every_rendering_variable() {
        let mut engine = MuxEngine::default();
        let (session, window, pane) = engine
            .state
            .create_session("inventory")
            .expect("hook inventory session");
        let snapshot = MuxHookSnapshot::capture(&engine);
        let session_state = &snapshot.sessions[&session];
        let window_state = &snapshot.windows[&window];
        let pane_state = &snapshot.panes[&pane];
        let require = |event: PendingHookEvent, keys: &[&str]| {
            for key in keys {
                assert!(
                    event.variables.contains_key(*key),
                    "{} lacks {key}",
                    event.name
                );
            }
        };

        for name in ["session-created", "session-closed", "session-renamed"] {
            require(
                PendingHookEvent::session(name, session, session_state, &snapshot),
                &["hook_session", "hook_session_name"],
            );
        }
        for name in ["window-linked", "window-unlinked", "session-window-changed"] {
            require(
                PendingHookEvent::winlink(
                    name,
                    session,
                    session_state,
                    window,
                    window_state,
                    &snapshot,
                ),
                &[
                    "hook_session",
                    "hook_session_name",
                    "hook_window",
                    "hook_window_name",
                ],
            );
        }
        for name in [
            "window-renamed",
            "window-layout-changed",
            "window-resized",
            "window-pane-changed",
        ] {
            require(
                PendingHookEvent::window(name, window, window_state, &snapshot),
                &[
                    "hook_session",
                    "hook_session_name",
                    "hook_window",
                    "hook_window_name",
                    "hook_pane",
                ],
            );
        }
        for name in [
            "pane-title-changed",
            "pane-mode-changed",
            "pane-died",
            "pane-exited",
            "alert-bell",
        ] {
            require(
                PendingHookEvent::pane(name, pane, pane_state, &snapshot),
                &[
                    "hook_session",
                    "hook_session_name",
                    "hook_window",
                    "hook_window_name",
                    "hook_pane",
                ],
            );
        }
        for name in [
            "client-attached",
            "client-session-changed",
            "client-detached",
        ] {
            let event = PendingHookEvent::client(
                name,
                snapshot.session_context(session),
                ClientId(7),
                None,
            );
            require(event.clone(), &["hook_client"]);
            assert!(!event.variables.contains_key("hook_session"));
            assert!(!event.variables.contains_key("hook_session_name"));
        }
        for name in ["paste-buffer-changed", "paste-buffer-deleted"] {
            require(
                PendingHookEvent::paste_buffer(name, "named".to_owned()),
                &["hook_paste_buffer"],
            );
        }
    }

    fn install_client_event_log_hooks(
        shared: &Arc<Shared>,
        context: &mut ExecutionContext,
        names: &[&str],
    ) {
        for name in names {
            shared
                .execute(
                    ClientId(u64::MAX),
                    ClientKind::Command,
                    context,
                    &CommandInvocation::new(
                        "set-hook",
                        [
                            "-g",
                            *name,
                            "display-message '#{hook}|#{hook_client}|#{session_id}|#{window_id}|#{pane_id}'",
                        ],
                    ),
                )
                .expect("install client event hook");
        }
    }

    fn client_event_log(shared: &Shared) -> Vec<String> {
        shared
            .inner
            .lock()
            .message_log
            .iter()
            .map(|message| message.text.clone())
            .collect()
    }

    #[test]
    fn client_hook_name_matches_client_format_name_fallbacks() {
        let shared = Arc::new(Shared::new(1));
        let (client, _) = shared.register_subscribed(
            ClientKind::Interactive,
            Some("macbook".to_owned()),
            None,
            OutboundMailbox::new(),
        );
        let mut inner = shared.inner.lock();

        assert_eq!(client_format_name(&inner, client), "macbook");
        inner.client_ttys.insert(client, String::new());
        assert_eq!(client_format_name(&inner, client), "macbook");
        inner.client_ttys.insert(client, "/dev/pts/40".to_owned());
        assert_eq!(client_format_name(&inner, client), "/dev/pts/40");
        inner.client_ttys.remove(&client);
        inner.client_names.insert(client, String::new());
        inner.client_pids.insert(client, 4242);
        assert_eq!(client_format_name(&inner, client), "client-4242");
        inner.client_pids.insert(client, 0);
        assert_eq!(
            client_format_name(&inner, client),
            format!("device-{}", client.0)
        );
    }

