    #[test]
    fn control_output_age_pause_kill_and_fair_pacing_are_deterministic() {
        let now = Instant::now();
        assert_eq!(
            control_output_age_action(
                Some(1000),
                now.checked_sub(Duration::from_millis(999)).unwrap(),
                now,
            ),
            ControlOutputAgeAction::Output(999)
        );
        assert_eq!(
            control_output_age_action(
                Some(1000),
                now.checked_sub(Duration::from_secs(1)).unwrap(),
                now,
            ),
            ControlOutputAgeAction::Pause
        );
        assert_eq!(
            control_output_age_action(None, now.checked_sub(CONTROL_MAXIMUM_AGE).unwrap(), now,),
            ControlOutputAgeAction::Kill
        );

        let shared = Arc::new(Shared::new(1));
        let mailbox = OutboundMailbox::new();
        let (client, _) =
            shared.register_subscribed(ClientKind::Control, None, None, Arc::clone(&mailbox));
        take_reliable_messages(&mailbox);
        let flood = PaneId(1);
        let quiet = PaneId(2);
        {
            let mut inner = shared.inner.lock();
            let output = inner
                .control_outputs
                .get_mut(&client)
                .expect("control output");
            output.pause_after_ms = Some(10_000);
            for (pane, bytes) in [
                (flood, Arc::<[u8]>::from(vec![b'x'; 20_000])),
                (quiet, Arc::<[u8]>::from(b"quiet".as_slice())),
            ] {
                output
                    .panes
                    .entry(pane)
                    .or_default()
                    .pending
                    .push_back(PendingControlOutput {
                        bytes,
                        offset: 0,
                        enqueued_at: now.checked_sub(Duration::from_millis(5)).unwrap(),
                    });
            }
        }
        shared.pump_control_output_at(now);
        let output = take_reliable_messages(&mailbox)
            .into_iter()
            .filter_map(|message| match message {
                ProtocolMessage::Event(Event {
                    payload:
                        EventPayload::PaneOutputAged {
                            pane,
                            age_ms,
                            bytes,
                        },
                    ..
                }) => Some((pane, age_ms, bytes)),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(output.len() >= 2);
        assert!(output.iter().all(|(_, _, bytes)| bytes.len() <= 2730));
        assert!(output.iter().take(2).any(|(pane, _, _)| *pane == quiet));
        let flood_ages = output
            .iter()
            .filter_map(|(pane, age, _)| (*pane == flood).then_some(*age))
            .collect::<Vec<_>>();
        assert!(flood_ages.windows(2).all(|ages| ages[0] <= ages[1]));

        let paused_mailbox = OutboundMailbox::new();
        let (paused, _) = shared.register_subscribed(
            ClientKind::Control,
            None,
            None,
            Arc::clone(&paused_mailbox),
        );
        take_reliable_messages(&paused_mailbox);
        {
            let mut inner = shared.inner.lock();
            let output = inner
                .control_outputs
                .get_mut(&paused)
                .expect("paused output");
            output.pause_after_ms = Some(1000);
            output
                .panes
                .entry(flood)
                .or_default()
                .pending
                .push_back(PendingControlOutput {
                    bytes: Arc::from(b"old".as_slice()),
                    offset: 0,
                    enqueued_at: now.checked_sub(Duration::from_secs(1)).unwrap(),
                });
        }
        shared.pump_control_output_at(now);
        assert!(
            take_reliable_messages(&paused_mailbox)
                .iter()
                .any(|message| matches!(
                    message,
                    ProtocolMessage::Event(Event {
                        payload: EventPayload::PaneOutputState { pane, paused: true },
                        ..
                    }) if *pane == flood
                ))
        );

        let killed_mailbox = OutboundMailbox::new();
        let (killed, _) = shared.register_subscribed(
            ClientKind::Control,
            None,
            None,
            Arc::clone(&killed_mailbox),
        );
        {
            let mut inner = shared.inner.lock();
            inner
                .control_outputs
                .get_mut(&killed)
                .expect("killed output")
                .panes
                .entry(flood)
                .or_default()
                .pending
                .push_back(PendingControlOutput {
                    bytes: Arc::from(b"ancient".as_slice()),
                    offset: 0,
                    enqueued_at: now.checked_sub(CONTROL_MAXIMUM_AGE).unwrap(),
                });
        }
        shared.pump_control_output_at(now);
        assert!(
            take_reliable_messages(&killed_mailbox)
                .iter()
                .any(|message| matches!(
                    message,
                    ProtocolMessage::Event(Event {
                        payload: EventPayload::ControlExit { reason },
                        ..
                    }) if reason == "too far behind"
                ))
        );
    }

    #[test]
    fn configuration_override_updates_state_provenance_and_broadcast() {
        let shared = Arc::new(Shared::new(44));
        let mailbox = OutboundMailbox::new();
        let (client, hello) = shared.register_subscribed(
            ClientKind::Interactive,
            None,
            Some(TerminalColorScheme::Dark),
            Arc::clone(&mailbox),
        );
        assert_eq!(
            hello
                .appearance_provenance
                .source(zz_terminal::AppearanceConfigKey::Background),
            zz_terminal::AppearanceSource::Default
        );

        shared.set_config_overrides(
            client,
            ClientKind::Interactive,
            &[("background".to_owned(), "#123456".to_owned())],
        );

        let inner = shared.inner.lock();
        assert_eq!(
            inner.appearance.background,
            zz_terminal::Color::rgb(0x12, 0x34, 0x56)
        );
        assert_eq!(
            inner
                .appearance_provenance
                .source(zz_terminal::AppearanceConfigKey::Background),
            zz_terminal::AppearanceSource::Override
        );
        drop(inner);
        let state = mailbox.state.lock();
        assert!(state.reliable.iter().any(|frame| {
            matches!(
                decode_protocol_frame(frame),
                Ok(ProtocolMessage::Event(Event {
                    payload: EventPayload::AppearanceChanged {
                        appearance,
                        provenance,
                    },
                    ..
                })) if appearance.background == zz_terminal::Color::rgb(0x12, 0x34, 0x56)
                    && provenance.source(zz_terminal::AppearanceConfigKey::Background)
                        == zz_terminal::AppearanceSource::Override
            )
        }));
    }

    #[test]
    fn mux_override_beats_mux_config_file_and_survives_reload_user_config() {
        let directory = tempfile::tempdir().expect("temporary directory");
        let mux_config = directory.path().join("mux.conf");
        fs::write(&mux_config, "set -g prefix C-b\nset -g mode-keys emacs\n")
            .expect("mux config fixture");

        let shared = Arc::new(Shared::new(45));
        let mailbox = OutboundMailbox::new();
        let (client, hello) = shared.register_subscribed(
            ClientKind::Interactive,
            None,
            Some(TerminalColorScheme::Dark),
            Arc::clone(&mailbox),
        );
        assert_eq!(
            hello
                .mux_options
                .get(MuxOptionKey::Prefix)
                .expect("prefix in hello")
                .source,
            MuxOptionSource::Default
        );

        let mut context = ExecutionContext::default();
        shared
            .load_config_file(&mux_config, &mut context, 0)
            .expect("initial mux config replay");
        shared.set_config_overrides(
            client,
            ClientKind::Interactive,
            &[
                ("prefix".to_owned(), "C-a".to_owned()),
                ("mode-keys".to_owned(), "vi".to_owned()),
            ],
        );
        {
            let inner = shared.inner.lock();
            assert_eq!(inner.engine.keys.prefix(), "C-a");
            assert_eq!(
                inner
                    .mux_options
                    .get(MuxOptionKey::Prefix)
                    .expect("effective prefix"),
                &zz_protocol::MuxOptionValue {
                    value: "C-a".to_owned(),
                    source: MuxOptionSource::Override,
                }
            );
            assert_eq!(inner.engine.mux_option_value(MuxOptionKey::ModeKeys), "vi");
        }

        shared
            .reload_user_config_with_mux_file(client, &mut context, Some(&mux_config))
            .expect("reload user configuration");
        let inner = shared.inner.lock();
        assert_eq!(inner.engine.keys.prefix(), "C-a");
        assert_eq!(inner.engine.mux_option_value(MuxOptionKey::ModeKeys), "vi");
        assert_eq!(
            inner
                .mux_options
                .get(MuxOptionKey::Prefix)
                .expect("replayed prefix")
                .source,
            MuxOptionSource::Override
        );
        drop(inner);

        let state = mailbox.state.lock();
        assert!(state.reliable.iter().any(|frame| {
            matches!(
                decode_protocol_frame(frame),
                Ok(ProtocolMessage::Event(Event {
                    payload: EventPayload::MuxOptionsChanged { options },
                    ..
                })) if options.get(MuxOptionKey::Prefix).is_some_and(|entry| {
                    entry.value == "C-a" && entry.source == MuxOptionSource::Override
                })
            )
        }));
    }

    #[test]
    fn reload_user_config_resets_key_tables_to_the_file() {
        let directory = tempfile::tempdir().expect("temporary directory");
        let mux_config = directory.path().join("mux.conf");
        fs::write(&mux_config, "bind-key F2 new-window\n").expect("mux config fixture");

        let shared = Arc::new(Shared::new(49));
        let mut context = ExecutionContext::default();
        shared
            .load_config_file(&mux_config, &mut context, 0)
            .expect("source mux config");
        shared
            .execute(
                ClientId(7),
                ClientKind::Command,
                &mut context,
                &CommandInvocation::new("bind-key", ["F3", "kill-pane"]),
            )
            .expect("interactive bind");
        {
            let inner = shared.inner.lock();
            assert!(inner.engine.keys.get("prefix", "F2").is_some());
            assert!(inner.engine.keys.get("prefix", "F3").is_some());
        }

        fs::write(&mux_config, "bind-key F4 new-window\n").expect("rewrite mux config");
        shared
            .reload_user_config_with_mux_file(ClientId(7), &mut context, Some(&mux_config))
            .expect("reload user configuration");
        let inner = shared.inner.lock();
        assert!(inner.engine.keys.get("prefix", "F2").is_none());
        assert!(inner.engine.keys.get("prefix", "F3").is_none());
        assert!(inner.engine.keys.get("prefix", "F4").is_some());
    }

