    #[test]
    fn nested_source_replay_keeps_the_explicit_client_base() {
        let directory = tempfile::tempdir().expect("temporary directory");
        let client_base = directory.path().join("client cwd [literal]*? with spaces");
        let entry_directory = client_base.join("a");
        fs::create_dir_all(&entry_directory).expect("nested source directory");
        fs::write(
            client_base.join("leaf.conf"),
            "set-option -g @nested-client-base root\n",
        )
        .expect("client-base leaf");
        fs::write(
            entry_directory.join("leaf.conf"),
            "set-option -g @nested-client-base decoy\n",
        )
        .expect("containing-file decoy");
        let entry = entry_directory.join("entry.conf");
        fs::write(
            &entry,
            "set-option -g @nested-replay-started yes\nsource-file leaf.conf\n",
        )
        .expect("nested source entry");

        let clientless = Arc::new(Shared::new(47));
        clientless
            .load_config_file(&entry, &mut ExecutionContext::default(), 0)
            .expect("clientless nested source replay");
        assert_eq!(
            read_global_option(&clientless, "@nested-client-base"),
            "decoy"
        );

        let shared = Arc::new(Shared::new(48));
        let mut source_invocations = SourceInvocationAccounting::default();
        shared
            .load_config_file_with_report_for_terminal(
                &entry,
                &mut ExecutionContext::default(),
                0,
                &mut ConfigLoadReport::default(),
                ClientTerminal::NoClient,
                Some(&client_base),
                &mut source_invocations,
            )
            .expect("nested source replay");

        assert_eq!(read_global_option(&shared, "@nested-replay-started"), "yes");
        assert_eq!(read_global_option(&shared, "@nested-client-base"), "root");
    }

    #[test]
    fn attached_source_file_uses_selected_session_cwd() {
        let directory = tempfile::tempdir().expect("temporary directory");
        let command_cwd = directory.path().join("command cwd [literal]*? with spaces");
        let session_cwd = directory.path().join("session cwd [literal]*? with spaces");
        let target_cwd = directory.path().join("target cwd [literal]*? with spaces");
        for cwd in [&command_cwd, &session_cwd, &target_cwd] {
            fs::create_dir_all(cwd).expect("source cwd");
        }
        fs::write(
            command_cwd.join("relative.conf"),
            "set-option -g @attached-source-base command-decoy\n",
        )
        .expect("command cwd decoy");
        fs::write(
            session_cwd.join("relative.conf"),
            "set-option -g @attached-source-base session-selected\n",
        )
        .expect("session cwd source");
        fs::write(
            target_cwd.join("relative.conf"),
            "set-option -g @attached-source-base target-decoy\n",
        )
        .expect("source target decoy");

        let shared = Arc::new(Shared::new(48));
        let command = ClientId(7);
        let mut command_context = ExecutionContext::default();
        command_context.set_client_working_directory(Some(command_cwd.clone()));
        shared
            .execute(
                command,
                ClientKind::Command,
                &mut command_context,
                &CommandInvocation::new(
                    "new-session",
                    [
                        "-d",
                        "-c",
                        command_cwd.to_str().expect("utf-8 command cwd"),
                        "-s",
                        "attached-source",
                    ],
                ),
            )
            .expect("attached source session");
        shared
            .execute(
                command,
                ClientKind::Command,
                &mut command_context,
                &CommandInvocation::new(
                    "new-session",
                    [
                        "-d",
                        "-c",
                        target_cwd.to_str().expect("utf-8 target cwd"),
                        "-s",
                        "source-target",
                    ],
                ),
            )
            .expect("source target session");

        let mailbox = OutboundMailbox::new();
        let (interactive, _) =
            shared.register_subscribed(ClientKind::Interactive, None, None, Arc::clone(&mailbox));
        shared
            .inner
            .lock()
            .client_working_directories
            .insert(interactive, command_cwd.clone());
        let mut interactive_context = ExecutionContext::default();
        shared
            .execute(
                interactive,
                ClientKind::Interactive,
                &mut interactive_context,
                &CommandInvocation::new(
                    "attach-session",
                    [
                        "-c",
                        session_cwd.to_str().expect("utf-8 session cwd"),
                        "-t",
                        "=attached-source",
                    ],
                ),
            )
            .expect("attach with selected session cwd");
        take_reliable_messages(&mailbox);
        {
            let inner = shared.inner.lock();
            assert_eq!(
                inner.client_working_directories.get(&interactive),
                Some(&command_cwd)
            );
            let session = inner
                .engine
                .state
                .resolve_session(Some("=attached-source"), None)
                .expect("attached source session id");
            assert_eq!(
                inner.engine.state.session_working_directory(session),
                Some(session_cwd.as_path())
            );
        }

        let response = shared.execute_command_request(
            interactive,
            ClientKind::Interactive,
            &mut interactive_context,
            1,
            &CommandInvocation::new("source-file", ["-t", "=source-target:0.0", "relative.conf"]),
        );
        assert_eq!(
            response,
            CommandResponse::Success {
                request_id: 1,
                output: String::new(),
                exit_code: 0,
                stderr: String::new(),
            }
        );
        assert_eq!(
            read_global_option(&shared, "@attached-source-base"),
            "session-selected"
        );
    }

    #[test]
    fn config_assignments_hidden_readback_expansion_and_conditions_match_the_pin() {
        let directory = tempfile::tempdir().expect("temporary directory");
        let mux_config = directory.path().join("mux.conf");
        fs::write(
            &mux_config,
            "CFGVAR=fromconfig\n\
             %hidden CFGHID=hiddencfg\n\
             JOINED=$CFGVAR-${CFGVAR}\n\
             ORDER=first\n\
             set-environment -g ORDER command\n\
             ORDER=last\n\
             %if \"#{==:x,x}\"\n\
             set-environment -g TRUE_BRANCH selected\n\
             %else\n\
             set-environment -g TRUE_BRANCH wrong\n\
             %endif\n\
             %if \"#(printf spawned)\"\n\
             set-environment -g NOJOB wrong\n\
             %else\n\
             set-environment -g NOJOB empty\n\
             %endif\n",
        )
        .expect("mux config fixture");

        let shared = Arc::new(Shared::new(48));
        let mut context = ExecutionContext::default();
        shared
            .load_config_file(&mux_config, &mut context, 0)
            .expect("source mux config");

        for (args, expected) in [
            (&["-g", "CFGVAR"] as &[&str], "CFGVAR=fromconfig"),
            (&["-gh", "CFGHID"], "CFGHID=hiddencfg"),
            (&["-g", "CFGHID"], ""),
            (&["-g", "JOINED"], "JOINED=fromconfig-fromconfig"),
            (&["-g", "ORDER"], "ORDER=command"),
            (&["-g", "TRUE_BRANCH"], "TRUE_BRANCH=selected"),
            (&["-g", "NOJOB"], "NOJOB=empty"),
        ] {
            let output = shared
                .execute(
                    ClientId(7),
                    ClientKind::Command,
                    &mut context,
                    &CommandInvocation::new("show-environment", args.iter().copied()),
                )
                .expect("show config environment")
                .output;
            assert_eq!(output, expected, "{args:?}");
        }
    }

    #[cfg(unix)]
    #[test]
    fn config_shell_commands_block_and_execute_in_order_without_an_output_sink() {
        let directory = tempfile::tempdir().expect("temporary directory");
        let ready = directory.path().join("ready");
        let ready = shell_quote(&ready);
        let missing = shell_quote(&directory.path().join("missing-tpm"));
        let unexpected = directory.path().join("unexpected-tpm-run");
        let config = directory.path().join("mux.conf");
        fs::write(
            &config,
            format!(
                "run-shell \"sleep 0.05; printf ready > {ready}\"\n\
                 if-shell \"test -f {ready}\" \"set-option -g @phase ready\" \
                 \"set-option -g @phase missed\"\n\
                 if-shell \"test -d {missing}\" \
                 \"run-shell 'printf unexpected > {}'\"\n\
                 run-shell \"printf hidden\"\n",
                unexpected.display()
            ),
        )
        .expect("shell config fixture");

        let shared = Arc::new(Shared::new(1));
        let mut context = ExecutionContext::default();
        let started = Instant::now();
        shared
            .load_config_file(&config, &mut context, 0)
            .expect("blocking shell config");
        assert!(started.elapsed() >= Duration::from_millis(40));
        let phase = shared
            .execute(
                ClientId(7),
                ClientKind::Command,
                &mut context,
                &CommandInvocation::new("show-options", ["-gqv", "@phase"]),
            )
            .expect("config branch result");
        assert_eq!(phase.output, "ready");
        assert!(!unexpected.exists());
        assert!(shared.inner.lock().command_outputs.is_empty());
    }

    #[cfg(unix)]
    #[test]
    fn source_file_globs_follow_the_posix_dialect_losslessly() {
        use std::os::unix::ffi::OsStrExt as _;

        assert_eq!(
            source_working_directory_glob_prefix(Path::new("/tmp/client [literal]*?\\ cwd"))
                .as_os_str()
                .as_bytes(),
            b"/tmp/client\\ \\[literal\\]\\*\\?\\\\\\ cwd"
        );
        assert_eq!(
            resolve_source_path("~/literal.conf", Some(Path::new("/tmp/client cwd"))),
            PathBuf::from("/tmp/client\\ cwd/~/literal.conf")
        );
        assert_eq!(
            expand_relative(Path::new("/tmp/nested source/entry.conf"), "~/literal.conf"),
            PathBuf::from("/tmp/nested\\ source/~/literal.conf")
        );

        let directory = tempfile::tempdir().expect("temporary directory");
        let escaped = directory.path().join("escaped [literal]*?\\ cwd");
        fs::create_dir(&escaped).expect("escaped-character directory");
        let literal_star = escaped.join("literal*.conf");
        fs::write(&literal_star, "").expect("literal-star file");
        fs::write(escaped.join("literalX.conf"), "").expect("wildcard peer");
        let matches = source_glob_matches(&resolve_source_path("literal\\*.conf", Some(&escaped)));
        assert_eq!(matches.paths, [literal_star]);
        assert!(matches.errors.is_empty());

        let nested_literal_parent = directory.path().join("nested[1]");
        let nested_pattern_peer = directory.path().join("nested1");
        fs::create_dir(&nested_literal_parent).expect("literal nested-source parent");
        fs::create_dir(&nested_pattern_peer).expect("pattern nested-source peer");
        let nested_entry = nested_literal_parent.join("entry.conf");
        fs::write(&nested_entry, "").expect("nested-source entry");
        let nested_literal_leaf = nested_literal_parent.join("leaf.conf");
        fs::write(&nested_literal_leaf, "").expect("literal nested-source leaf");
        fs::write(nested_pattern_peer.join("leaf.conf"), "")
            .expect("misleading nested-source peer");
        let matches = source_glob_matches(&expand_relative(&nested_entry, "leaf.conf"));
        assert_eq!(matches.paths, [nested_literal_leaf]);
        assert!(matches.errors.is_empty());

        let hidden = directory.path().join("hidden");
        fs::create_dir(&hidden).expect("hidden-file directory");
        let visible = hidden.join("visible.conf");
        fs::write(&visible, "").expect("visible file");
        fs::write(hidden.join(".hidden.conf"), "").expect("hidden file");
        let matches = source_glob_matches(&resolve_source_path("*.conf", Some(&hidden)));
        assert_eq!(matches.paths, [visible]);
        assert!(matches.errors.is_empty());

        let double_star = directory.path().join("double-star");
        let one = double_star.join("one");
        let deep = one.join("deep");
        fs::create_dir_all(&deep).expect("double-star directories");
        fs::write(double_star.join("root.conf"), "").expect("root file");
        let one_file = one.join("one.conf");
        fs::write(&one_file, "").expect("one-component file");
        fs::write(deep.join("deep.conf"), "").expect("deep file");
        let matches = source_glob_matches(&resolve_source_path("**/*.conf", Some(&double_star)));
        assert_eq!(matches.paths, [one_file]);
        assert!(matches.errors.is_empty());

        let triple_star = directory.path().join("triple-star");
        fs::create_dir(&triple_star).expect("triple-star directory");
        let alpha = triple_star.join("alpha.conf");
        fs::write(&alpha, "").expect("triple-star match");
        fs::write(triple_star.join("alpha.txt"), "").expect("triple-star miss");
        let matches = source_glob_matches(&resolve_source_path("***.conf", Some(&triple_star)));
        assert_eq!(matches.paths, [alpha]);
        assert!(matches.errors.is_empty());

        let prefix_siblings = directory.path().join("prefix-siblings");
        let mut expected = Vec::new();
        for name in ["zz-client-ffi", "zz-client", "zz"] {
            let child = prefix_siblings.join(name);
            fs::create_dir_all(&child).expect("prefix-sibling directory");
            let path = child.join("match.conf");
            fs::write(&path, "").expect("prefix-sibling match");
            expected.push(path);
        }
        let SourceGlobMatches { mut paths, errors } =
            source_glob_matches(&prefix_siblings.join("zz*/match.conf"));
        paths.sort();
        expected.sort();
        assert_eq!(paths, expected);
        assert!(errors.is_empty());

        let bracket = directory.path().join("bracket");
        fs::create_dir(&bracket).expect("bracket directory");
        let literal_bracket = bracket.join("literal[.conf");
        fs::write(&literal_bracket, "").expect("literal-bracket file");
        let matches = source_glob_matches(&resolve_source_path("literal[.conf", Some(&bracket)));
        assert_eq!(matches.paths, [literal_bracket]);
        assert!(matches.errors.is_empty());
        let matches = source_glob_matches(&resolve_source_path("missing[.conf", Some(&bracket)));
        assert!(matches.paths.is_empty());
        assert!(matches.errors.is_empty());

        #[cfg(target_os = "linux")]
        {
            use std::os::unix::ffi::OsStringExt as _;

            let non_utf8_name = std::ffi::OsString::from_vec(b"non-utf8-\xff.conf".to_vec());
            let non_utf8 = directory.path().join(&non_utf8_name);
            fs::write(&non_utf8, "").expect("non-UTF-8 file");
            let matches = source_glob_matches(&directory.path().join("non-utf8-?.conf"));
            assert_eq!(matches.paths, [non_utf8]);
            assert!(matches.errors.is_empty());
        }

        let nul = std::ffi::OsStr::from_bytes(b"/tmp/source\0glob");
        let matches = source_glob_matches(Path::new(nul));
        assert!(matches.paths.is_empty());
        assert_eq!(matches.errors.len(), 1);
        assert_eq!(
            source_glob_error_warning(Path::new("declared.conf"), &matches.errors[0]),
            format!("{}: declared.conf", matches.errors[0])
        );
    }

    #[test]
    fn source_file_globs_nested_sources_and_refuses_standard_input() {
        let directory = tempfile::tempdir().expect("temporary directory");
        let top = directory.path().join("top");
        let nested = directory.path().join("nested");
        fs::create_dir_all(&top).expect("top-level source directory");
        fs::create_dir_all(&nested).expect("nested source directory");
        fs::write(
            top.join("10-first.conf"),
            "set -g prefix C-a\nbind-key F2 new-window\n",
        )
        .expect("first top-level source");
        fs::write(
            top.join("20-second.conf"),
            "set -g prefix C-z\nbind-key F3 kill-pane\n",
        )
        .expect("second top-level source");
        fs::write(nested.join("10-first.conf"), "bind-key F4 new-window\n")
            .expect("first nested source");
        fs::write(nested.join("20-second.conf"), "bind-key F5 kill-pane\n")
            .expect("second nested source");
        let entry = directory.path().join("entry.conf");
        fs::write(
            &entry,
            format!("source-file '{}'\n", nested.join("*.conf").display()),
        )
        .expect("nested source entry");

        let shared = Arc::new(Shared::new(50));
        let mailbox = OutboundMailbox::new();
        let (client, _) =
            shared.register_subscribed(ClientKind::Interactive, None, None, Arc::clone(&mailbox));
        let mut context = ExecutionContext::default();
        shared
            .execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new("new-session", ["-s", "source-glob"]),
            )
            .expect("source-file session");
        take_reliable_messages(&mailbox);

        let top_pattern = top.join("*.conf").display().to_string();
        shared
            .execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new("source-file", [&top_pattern]),
            )
            .expect("top-level source glob");
        shared
            .execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new("source-file", [entry.display().to_string()]),
            )
            .expect("nested source glob");
        let formatted = directory.path().join("formatted");
        fs::create_dir_all(&formatted).expect("formatted source directory");
        fs::write(
            formatted.join("source-glob-0-0-10.conf"),
            "bind-key F9 new-window\n",
        )
        .expect("first formatted source");
        fs::write(
            formatted.join("source-glob-0-0-20.conf"),
            "bind-key F10 new-window\n",
        )
        .expect("second formatted source");
        let formatted_pattern = formatted
            .join("#{session_name}-#{window_index}-#{pane_index}-*.conf")
            .display()
            .to_string();
        shared
            .execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new("source-file", ["-F", &formatted_pattern]),
            )
            .expect("format-expanded source glob");
        {
            let inner = shared.inner.lock();
            assert_eq!(inner.engine.keys.prefix(), "C-z");
            for key in ["F2", "F3", "F4", "F5", "F9", "F10"] {
                assert!(inner.engine.keys.get("prefix", key).is_some(), "{key}");
            }
        }

        let verbose_directory = directory.path().join("verbose");
        fs::create_dir_all(&verbose_directory).expect("verbose source directory");
        fs::write(
            verbose_directory.join("loaded.conf"),
            "bind-key F8 new-window\n",
        )
        .expect("verbose nested source");
        let verbose_entry = directory.path().join("verbose-entry.conf");
        fs::write(
            &verbose_entry,
            "source-file -v 'verbose/*.conf'\nbind-key F7 new-window\n",
        )
        .expect("verbose source entry");
        let mut report = ConfigLoadReport::default();
        shared
            .load_config_file_with_report(&verbose_entry, &mut context, 0, &mut report)
            .expect("verbose nested source loads");
        {
            let inner = shared.inner.lock();
            assert!(inner.engine.keys.get("prefix", "F7").is_some());
            assert!(inner.engine.keys.get("prefix", "F8").is_some());
        }
        assert_eq!(
            report.verbose_lines(),
            [format!(
                "{}:1: bind-key F8 new-window",
                verbose_directory.join("loaded.conf").display()
            )]
        );
        assert!(report.summary().is_none());

        take_reliable_messages(&mailbox);
        let missing = directory
            .path()
            .join("missing-*.conf")
            .display()
            .to_string();
        shared
            .execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new("source-file", ["-q", &missing]),
            )
            .expect("quiet no-match source glob");
        assert!(!take_reliable_messages(&mailbox).iter().any(|message| {
            matches!(
                message,
                ProtocolMessage::Event(Event {
                    payload: EventPayload::ClientMessage { .. },
                    ..
                })
            )
        }));

        let malformed = directory.path().join("[").display().to_string();
        let after_error = directory.path().join("after-error.conf");
        fs::write(&after_error, "bind-key F6 new-window\n").expect("post-error source");
        shared
            .execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new(
                    "source-file",
                    ["-q", &malformed, &after_error.display().to_string()],
                ),
            )
            .expect("glob no-match continues to later sources");
        assert!(
            shared
                .inner
                .lock()
                .engine
                .keys
                .get("prefix", "F6")
                .is_some()
        );
        let missing_warning = format!("No such file or directory: {missing}");
        assert!(!take_reliable_messages(&mailbox).iter().any(|message| {
            matches!(
                message,
                ProtocolMessage::Event(Event {
                    payload: EventPayload::ClientMessage {
                        kind: ClientMessageKind::Warning,
                        ..
                    },
                    ..
                })
            )
        }));

        assert!(matches!(
            shared.execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new("source-file", [&missing]),
            ),
            Err(DaemonError::CommandExit {
                output,
                exit_code: 1,
            }) if output.is_empty()
        ));
        assert!(take_reliable_messages(&mailbox).iter().any(|message| {
            matches!(
                message,
                ProtocolMessage::Event(Event {
                    payload: EventPayload::ClientMessage {
                        kind: ClientMessageKind::Warning,
                        text,
                        ..
                    },
                    ..
                }) if text == &missing_warning
            )
        }));

        assert!(matches!(
            shared.execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new("source-file", ["-q", "-"]),
            ),
            Err(DaemonError::CommandExit {
                output,
                exit_code: 1,
            }) if output.is_empty()
        ));
        assert!(take_reliable_messages(&mailbox).iter().any(|message| {
            matches!(
                message,
                ProtocolMessage::Event(Event {
                    payload: EventPayload::ClientMessage {
                        kind: ClientMessageKind::Warning,
                        text,
                        ..
                    },
                    ..
                }) if text.contains("source-file from standard input is not supported")
            )
        }));
    }

    #[test]
    fn source_file_diagnostics_split_streams_for_command_clients_only() {
        let directory = tempfile::tempdir().expect("temporary directory");
        let bad = directory.path().join("bad.conf");
        fs::write(&bad, "wibble\nwibble\n").expect("invalid source fixture");
        let bad = bad.display().to_string();
        let missing = directory.path().join("missing.conf").display().to_string();
        let good = directory.path().join("good.conf");
        fs::write(&good, "").expect("valid source fixture");
        let good = good.display().to_string();
        let verbose_leaf = directory.path().join("verbose-leaf.conf");
        fs::write(&verbose_leaf, "set-option -g @verbose-source loaded\n")
            .expect("verbose source leaf");
        let verbose = directory.path().join("verbose.conf");
        fs::write(&verbose, "source-file -v verbose-leaf.conf\n").expect("verbose source");
        let verbose = verbose.display().to_string();

        let shared = Arc::new(Shared::new(63));
        let mailbox = OutboundMailbox::new();
        let (interactive, _) =
            shared.register_subscribed(ClientKind::Interactive, None, None, Arc::clone(&mailbox));
        let command = ClientId(u64::from(u16::MAX));
        let mut context = ExecutionContext::default();

        let invalid = shared.execute_command_request(
            command,
            ClientKind::Command,
            &mut context,
            1,
            &CommandInvocation::new("source-file", [&bad]),
        );
        assert_eq!(
            invalid,
            CommandResponse::Success {
                request_id: 1,
                output: format!("{bad}:1: unknown command: wibble\n"),
                exit_code: 1,
                stderr: String::new(),
            }
        );

        let quiet = shared.execute_command_request(
            command,
            ClientKind::Command,
            &mut context,
            2,
            &CommandInvocation::new("source-file", ["-q", &missing]),
        );
        assert_eq!(
            quiet,
            CommandResponse::Success {
                request_id: 2,
                output: String::new(),
                exit_code: 0,
                stderr: String::new(),
            }
        );

        let loud = shared.execute_command_request(
            command,
            ClientKind::Command,
            &mut context,
            3,
            &CommandInvocation::new("source-file", [&bad, &missing]),
        );
        assert_eq!(
            loud,
            CommandResponse::Success {
                request_id: 3,
                output: format!("{bad}:1: unknown command: wibble\n"),
                exit_code: 1,
                stderr: format!("No such file or directory: {missing}\n"),
            }
        );

        let verbose_response = shared.execute_command_request(
            command,
            ClientKind::Command,
            &mut context,
            4,
            &CommandInvocation::new("source-file", [&verbose]),
        );
        assert_eq!(
            verbose_response,
            CommandResponse::Success {
                request_id: 4,
                output: format!(
                    "{}:1: set-option -g @verbose-source loaded\n",
                    verbose_leaf.display()
                ),
                exit_code: 0,
                stderr: String::new(),
            }
        );

        let control = ClientId(u64::from(u16::MAX) - 1);
        let control_loud = shared.execute_command_request(
            control,
            ClientKind::Control,
            &mut context,
            5,
            &CommandInvocation::new("source-file", [&missing]),
        );
        assert_eq!(
            control_loud,
            CommandResponse::Error {
                request_id: 5,
                error: ServerError::InvalidCommand(format!("No such file or directory: {missing}")),
                output: String::new(),
            }
        );
        let control_partial = shared.execute_command_request(
            control,
            ClientKind::Control,
            &mut context,
            6,
            &CommandInvocation::new("source-file", [&good, &missing]),
        );
        assert_eq!(
            control_partial,
            CommandResponse::Success {
                request_id: 6,
                output: format!("No such file or directory: {missing}\n"),
                exit_code: 1,
                stderr: String::new(),
            }
        );

        assert!(shared.inner.lock().command_streams.is_empty());

        take_reliable_messages(&mailbox);
        let mut interactive_context = ExecutionContext::default();
        let attended = shared.execute_command_request(
            interactive,
            ClientKind::Interactive,
            &mut interactive_context,
            7,
            &CommandInvocation::new("source-file", [&bad, &missing]),
        );
        assert_eq!(
            attended,
            CommandResponse::Success {
                request_id: 7,
                output: format!("{bad}:1: unknown command: wibble\n"),
                exit_code: 0,
                stderr: String::new(),
            }
        );
        let warnings = take_reliable_messages(&mailbox)
            .into_iter()
            .filter_map(|message| match message {
                ProtocolMessage::Event(Event {
                    payload:
                        EventPayload::ClientMessage {
                            kind: ClientMessageKind::Warning,
                            text,
                            ..
                        },
                    ..
                }) => Some(text),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert_eq!(
            warnings,
            [
                format!("No such file or directory: {missing}"),
                format!("{bad}:1: unknown command: wibble"),
            ]
        );
    }

    #[test]
    fn source_file_qualifies_post_admission_parse_errors() {
        let directory = tempfile::tempdir().expect("temporary directory");
        let shared = Arc::new(Shared::new(64));
        let client = ClientId(u64::from(u16::MAX));

        for (request_id, (name, contents)) in (1_u64..).zip([
            (
                "if-shell.conf",
                "if-shell -F 1 \"{ display-message -p quoted }\"\n",
            ),
            (
                "run-shell.conf",
                "run-shell -C \"{ display-message -p quoted }\"\n",
            ),
            (
                "nested-if-shell.conf",
                "if-shell -F 1 \"if-shell -F 1 \\\"{ display-message -p quoted }\\\"\"\n",
            ),
            (
                "nested-run-shell.conf",
                "run-shell -C \"run-shell -C \\\"{ display-message -p quoted }\\\"\"\n",
            ),
        ]) {
            let path = directory.path().join(name);
            fs::write(&path, contents).expect("source fixture");
            let path = path.display().to_string();
            let mut context = ExecutionContext::default();

            assert_eq!(
                shared.execute_command_request(
                    client,
                    ClientKind::Command,
                    &mut context,
                    request_id,
                    &CommandInvocation::new("source-file", [&path]),
                ),
                CommandResponse::Success {
                    request_id,
                    output: String::new(),
                    exit_code: 1,
                    stderr: format!("{path}:1: syntax error\n"),
                }
            );
        }

        let inner = directory.path().join("inner.conf");
        fs::write(&inner, "if-shell -F 1 \"{ display-message -p quoted }\"\n")
            .expect("inner source fixture");
        let outer = directory.path().join("outer.conf");
        fs::write(
            &outer,
            format!("if-shell -F 1 \"source-file '{}'\"\n", inner.display()),
        )
        .expect("outer source fixture");
        let inner = inner.display().to_string();
        let outer = outer.display().to_string();
        let mut context = ExecutionContext::default();

        assert_eq!(
            shared.execute_command_request(
                client,
                ClientKind::Command,
                &mut context,
                5,
                &CommandInvocation::new("source-file", [&outer]),
            ),
            CommandResponse::Success {
                request_id: 5,
                output: String::new(),
                exit_code: 1,
                stderr: format!("{inner}:1: syntax error\n"),
            }
        );
    }

    #[test]
    fn source_file_callback_parse_errors_preserve_replay_groups() {
        let directory = tempfile::tempdir().expect("temporary directory");
        let shared = Arc::new(Shared::new(64));
        let client = ClientId(u64::from(u16::MAX));

        for (request_id, name, first, before, same, next, keeps_same) in [
            (
                1,
                "if-shell.conf",
                "if-shell -F 1 \"{ display-message -p quoted }\"",
                "@callback-if-before",
                "@callback-if-same",
                "@callback-if-next",
                false,
            ),
            (
                2,
                "run-shell.conf",
                "run-shell -C \"{ display-message -p quoted }\"",
                "@callback-run-before",
                "@callback-run-same",
                "@callback-run-next",
                true,
            ),
            (
                3,
                "nested-if-shell.conf",
                "if-shell -F 1 { if-shell -F 1 \"{ display-message -p quoted }\" }",
                "@nested-callback-if-before",
                "@nested-callback-if-same",
                "@nested-callback-if-next",
                true,
            ),
            (
                4,
                "nested-run-shell.conf",
                "run-shell -C { run-shell -C \"{ display-message -p quoted }\" }",
                "@nested-callback-run-before",
                "@nested-callback-run-same",
                "@nested-callback-run-next",
                true,
            ),
        ] {
            let path = directory.path().join(name);
            fs::write(
                &path,
                format!(
                    "set-option -g {before} yes ; {first} ; set-option -g {same} yes\n\
                     set-option -g {next} yes\n"
                ),
            )
            .expect("source fixture");
            let path = path.display().to_string();
            let mut context = ExecutionContext::default();

            assert_eq!(
                shared.execute_command_request(
                    client,
                    ClientKind::Command,
                    &mut context,
                    request_id,
                    &CommandInvocation::new("source-file", [&path]),
                ),
                CommandResponse::Success {
                    request_id,
                    output: String::new(),
                    exit_code: 1,
                    stderr: format!("{path}:1: syntax error\n"),
                }
            );
            assert_eq!(read_global_option(&shared, before), "yes", "{name} prefix");
            assert_eq!(
                read_global_option(&shared, same),
                if keeps_same { "yes" } else { "" },
                "{name} same-line group"
            );
            assert_eq!(read_global_option(&shared, next), "yes", "{name} next line");
        }

        let quoted = directory.path().join("quoted-nested-run-shell.conf");
        fs::write(
            &quoted,
            r#"set-option -g @quoted-outer-before yes ; run-shell -C "set-option -g @quoted-inner-before yes ; run-shell -C \"{ display-message -p quoted }\" ; set-option -g @quoted-inner-same yes" ; set-option -g @quoted-outer-same yes
set-option -g @quoted-next yes
"#,
        )
        .expect("quoted nested run-shell source fixture");
        let quoted = quoted.display().to_string();
        let mut context = ExecutionContext::default();

        assert_eq!(
            shared.execute_command_request(
                client,
                ClientKind::Command,
                &mut context,
                5,
                &CommandInvocation::new("source-file", [&quoted]),
            ),
            CommandResponse::Success {
                request_id: 5,
                output: String::new(),
                exit_code: 1,
                stderr: format!("{quoted}:1: syntax error\n"),
            }
        );
        for name in [
            "@quoted-outer-before",
            "@quoted-inner-before",
            "@quoted-inner-same",
            "@quoted-outer-same",
            "@quoted-next",
        ] {
            assert_eq!(read_global_option(&shared, name), "yes", "{name} state");
        }

        shared
            .execute(
                client,
                ClientKind::Command,
                &mut context,
                &CommandInvocation::new(
                    "set-option",
                    ["-s", "command-alias[100]", "rr=run-shell -C"],
                ),
            )
            .expect("runtime run-shell alias");
        let aliased = directory.path().join("aliased-nested-run-shell.conf");
        fs::write(
            &aliased,
            r#"run-shell -C "set-option -g @alias-inner-before yes ; rr \"{ display-message -p quoted }\" ; set-option -g @alias-inner-same yes"
set-option -g @alias-next yes
"#,
        )
        .expect("aliased nested run-shell source fixture");
        let aliased = aliased.display().to_string();

        assert_eq!(
            shared.execute_command_request(
                client,
                ClientKind::Command,
                &mut context,
                6,
                &CommandInvocation::new("source-file", [&aliased]),
            ),
            CommandResponse::Success {
                request_id: 6,
                output: String::new(),
                exit_code: 1,
                stderr: format!("{aliased}:1: syntax error\n"),
            }
        );
        for name in ["@alias-inner-before", "@alias-inner-same", "@alias-next"] {
            assert_eq!(read_global_option(&shared, name), "yes", "{name} state");
        }

        for (index, alias) in [
            "aliasif=if-shell -F 1 \"{ display-message -p quoted }\" ; set-option -g @alias-if-same yes",
            "aliasrun=run-shell -C \"{ display-message -p quoted }\" ; set-option -g @alias-run-same yes",
        ]
        .into_iter()
        .enumerate()
        {
            shared
                .execute(
                    client,
                    ClientKind::Command,
                    &mut context,
                    &CommandInvocation::new(
                        "set-option",
                        [
                            "-s",
                            &format!("command-alias[{}]", index + 101),
                            alias,
                        ],
                    ),
                )
                .expect("callback command alias group");
        }
        for (request_id, name, command, same, next, keeps_same) in [
            (
                7,
                "alias-group-if-shell.conf",
                "aliasif",
                "@alias-if-same",
                "@alias-if-next",
                false,
            ),
            (
                8,
                "alias-group-run-shell.conf",
                "aliasrun",
                "@alias-run-same",
                "@alias-run-next",
                true,
            ),
        ] {
            let path = directory.path().join(name);
            fs::write(&path, format!("{command}\nset-option -g {next} yes\n"))
                .expect("callback alias group source fixture");
            let path = path.display().to_string();

            assert_eq!(
                shared.execute_command_request(
                    client,
                    ClientKind::Command,
                    &mut context,
                    request_id,
                    &CommandInvocation::new("source-file", [&path]),
                ),
                CommandResponse::Success {
                    request_id,
                    output: String::new(),
                    exit_code: 1,
                    stderr: format!("{path}:1: syntax error\n"),
                }
            );
            assert_eq!(
                read_global_option(&shared, same),
                if keeps_same { "yes" } else { "" },
                "{name} same-group state"
            );
            assert_eq!(read_global_option(&shared, next), "yes", "{name} next line");
        }

        let alias_if_group = directory.path().join("alias-if-caller-group.conf");
        fs::write(
            &alias_if_group,
            "set-option -g @alias-if-caller-before yes ; aliasif ; set-option -g @alias-if-caller-same yes\n\
             set-option -g @alias-if-caller-next yes\n",
        )
        .expect("if-shell alias caller group source fixture");
        let alias_if_group = alias_if_group.display().to_string();
        assert_eq!(
            shared.execute_command_request(
                client,
                ClientKind::Command,
                &mut context,
                9,
                &CommandInvocation::new("source-file", [&alias_if_group]),
            ),
            CommandResponse::Success {
                request_id: 9,
                output: String::new(),
                exit_code: 1,
                stderr: format!("{alias_if_group}:1: syntax error\n"),
            }
        );
        assert_eq!(
            read_global_option(&shared, "@alias-if-caller-before"),
            "yes"
        );
        assert_eq!(read_global_option(&shared, "@alias-if-caller-same"), "");
        assert_eq!(read_global_option(&shared, "@alias-if-caller-next"), "yes");

        let alias_run_string = directory.path().join("alias-run-caller-string.conf");
        fs::write(
            &alias_run_string,
            r#"run-shell -C "set-option -g @alias-run-caller-before yes ; aliasrun ; set-option -g @alias-run-caller-same yes"
set-option -g @alias-run-caller-next yes
"#,
        )
        .expect("run-shell alias caller string source fixture");
        let alias_run_string = alias_run_string.display().to_string();
        assert_eq!(
            shared.execute_command_request(
                client,
                ClientKind::Command,
                &mut context,
                10,
                &CommandInvocation::new("source-file", [&alias_run_string]),
            ),
            CommandResponse::Success {
                request_id: 10,
                output: String::new(),
                exit_code: 1,
                stderr: format!("{alias_run_string}:1: syntax error\n"),
            }
        );
        for name in [
            "@alias-run-caller-before",
            "@alias-run-caller-same",
            "@alias-run-caller-next",
        ] {
            assert_eq!(read_global_option(&shared, name), "yes", "{name} state");
        }

        shared
            .execute(
                client,
                ClientKind::Command,
                &mut context,
                &CommandInvocation::new(
                    "set-option",
                    [
                        "-s",
                        "command-alias[103]",
                        "aliasmixed=run-shell -C \"{ display-message -p quoted }\" ; if-shell -F 1 \"{ display-message -p quoted }\" ; set-option -g @alias-mixed-body yes",
                    ],
                ),
            )
            .expect("mixed callback command alias");
        let alias_mixed = directory.path().join("alias-mixed-caller-string.conf");
        fs::write(
            &alias_mixed,
            r#"run-shell -C "set-option -g @alias-mixed-before yes ; aliasmixed ; set-option -g @alias-mixed-outer yes"
set-option -g @alias-mixed-next yes
"#,
        )
        .expect("mixed callback alias caller string fixture");
        let alias_mixed = alias_mixed.display().to_string();
        let diagnostic = format!("{alias_mixed}:1: syntax error");

        assert_eq!(
            shared.execute_command_request(
                client,
                ClientKind::Command,
                &mut context,
                11,
                &CommandInvocation::new("source-file", [&alias_mixed]),
            ),
            CommandResponse::Success {
                request_id: 11,
                output: String::new(),
                exit_code: 1,
                stderr: format!("{diagnostic}\n{diagnostic}\n"),
            }
        );
        assert_eq!(read_global_option(&shared, "@alias-mixed-before"), "yes");
        assert_eq!(read_global_option(&shared, "@alias-mixed-body"), "");
        assert_eq!(read_global_option(&shared, "@alias-mixed-outer"), "");
        assert_eq!(read_global_option(&shared, "@alias-mixed-next"), "yes");
    }

    #[test]
    fn source_mixed_depth_alias_callback_failures_prune_caller_group() {
        let directory = tempfile::tempdir().expect("temporary directory");
        let shared = Arc::new(Shared::new(64));
        let command = ClientId(u64::from(u16::MAX));
        let mut context = ExecutionContext::default();
        shared
            .execute(
                command,
                ClientKind::Command,
                &mut context,
                &CommandInvocation::new("new-session", ["-d", "-s", "mixed-depth-alias"]),
            )
            .expect("mixed-depth alias session");
        shared
            .execute(
                command,
                ClientKind::Command,
                &mut context,
                &CommandInvocation::new(
                    "set-option",
                    [
                        "-s",
                        "command-alias[100]",
                        r#"deepmixed=run-shell -C "run-shell -C \"{ display-message -p quoted }\"" ; if-shell -F 1 "{ display-message -p quoted }" ; set-option -g @deep-mixed-alias-body yes"#,
                    ],
                ),
            )
            .expect("mixed-depth callback alias");

        let command_path = directory.path().join("command.conf");
        fs::write(
            &command_path,
            "set-option -g @deep-mixed-command-before yes ; deepmixed ; set-option -g @deep-mixed-command-same yes\n\
             set-option -g @deep-mixed-command-later yes\n",
        )
        .expect("mixed-depth Command source fixture");
        let command_path = command_path.display().to_string();
        let diagnostic = format!("{command_path}:1: syntax error");
        assert_eq!(
            shared.execute_command_request(
                command,
                ClientKind::Command,
                &mut context,
                1,
                &CommandInvocation::new("source-file", [&command_path]),
            ),
            CommandResponse::Success {
                request_id: 1,
                output: String::new(),
                exit_code: 1,
                stderr: format!("{diagnostic}\n{diagnostic}\n"),
            }
        );
        assert_eq!(
            read_global_option(&shared, "@deep-mixed-command-before"),
            "yes"
        );
        assert_eq!(read_global_option(&shared, "@deep-mixed-alias-body"), "");
        assert_eq!(read_global_option(&shared, "@deep-mixed-command-same"), "");
        assert_eq!(
            read_global_option(&shared, "@deep-mixed-command-later"),
            "yes"
        );

        let mailbox = OutboundMailbox::new();
        let (control, _) =
            shared.register_subscribed(ClientKind::Control, None, None, Arc::clone(&mailbox));
        shared
            .attach(
                control,
                context.session.expect("mixed-depth alias session id"),
            )
            .expect("attach mixed-depth Control client");
        take_reliable_messages(&mailbox);

        for (direct_argv, request_id) in [(false, 2), (true, 3)] {
            let prefix = if direct_argv { "argv" } else { "stdin" };
            let before = format!("@deep-mixed-{prefix}-before");
            let same = format!("@deep-mixed-{prefix}-same");
            let later = format!("@deep-mixed-{prefix}-later");
            let path = directory.path().join(format!("control-{prefix}.conf"));
            fs::write(
                &path,
                format!(
                    "set-option -g {before} yes ; deepmixed ; set-option -g {same} yes\n\
                     set-option -g {later} yes\n"
                ),
            )
            .expect("mixed-depth Control source fixture");
            let invocation = if direct_argv {
                CommandInvocation::new("source-file", [path.display().to_string()])
            } else {
                control_stdin_command("source-file", [path.display().to_string()])
            };
            assert_eq!(
                shared.execute_command_request(
                    control,
                    ClientKind::Control,
                    &mut context,
                    request_id,
                    &invocation,
                ),
                CommandResponse::Success {
                    request_id,
                    output: String::new(),
                    exit_code: 1,
                    stderr: String::new(),
                }
            );
            assert_eq!(
                read_global_option(&shared, &before),
                "yes",
                "{prefix} before"
            );
            assert_eq!(read_global_option(&shared, &same), "", "{prefix} same");
            assert_eq!(read_global_option(&shared, &later), "yes", "{prefix} later");
            take_reliable_messages(&mailbox);
        }

        assert!(shared.inner.lock().command_streams.is_empty());
    }

