    #[test]
    fn runtime_source_invocations_release_between_sequential_commands() {
        fn fan_out(directory: &Path, name: &str, leaves: usize) -> PathBuf {
            let entry = directory.join(format!("{name}.conf"));
            let mut body = String::new();
            for index in 1..=leaves {
                let leaf = directory.join(format!("{name}-leaf{index}.conf"));
                fs::write(&leaf, format!("set-option -g @{name} {index}\n"))
                    .expect("runtime source leaf");
                let _ = writeln!(body, "source-file '{}'", leaf.display());
            }
            fs::write(&entry, body).expect("runtime source entry");
            entry
        }

        let directory = tempfile::tempdir().expect("temporary directory");
        let shared = Arc::new(Shared::new(67));
        let client = ClientId(u64::MAX);
        let mut context = ExecutionContext::default();

        let breadth = fan_out(directory.path(), "runtime-breadth", 60);
        let response = shared.execute_command_request(
            client,
            ClientKind::Command,
            &mut context,
            1,
            &CommandInvocation::new("source-file", [breadth.display().to_string()]),
        );
        assert_eq!(
            response,
            CommandResponse::Success {
                request_id: 1,
                output: String::new(),
                exit_code: 0,
                stderr: String::new(),
            }
        );
        assert_eq!(read_global_option(&shared, "@runtime-breadth"), "60");

        let half = MAX_SOURCE_INVOCATIONS - 10;
        for (request_id, name) in [(2, "runtime-first"), (3, "runtime-second")] {
            let entry = fan_out(directory.path(), name, half);
            let response = shared.execute_command_request(
                client,
                ClientKind::Command,
                &mut context,
                request_id,
                &CommandInvocation::new("source-file", [entry.display().to_string()]),
            );
            assert_eq!(
                response,
                CommandResponse::Success {
                    request_id,
                    output: String::new(),
                    exit_code: 0,
                    stderr: String::new(),
                }
            );
            assert_eq!(
                read_global_option(&shared, &format!("@{name}")),
                half.to_string()
            );
        }
    }

    #[test]
    fn nested_source_invocations_stop_at_the_pinned_depth_limit_on_every_channel() {
        fn chain(directory: &Path, invocations: usize) -> PathBuf {
            for level in 1..=invocations {
                let nested = if level < invocations {
                    format!(
                        "source-file '{}'\n",
                        directory.join(format!("f{}.conf", level + 1)).display()
                    )
                } else {
                    format!(
                        "source-file '{}' '{}'\nsource-file -q '{}'\n",
                        directory.join("leaf-a.conf").display(),
                        directory.join("leaf-b.conf").display(),
                        directory.join("leaf-a.conf").display()
                    )
                };
                let body = format!(
                    "set-option -g @depth {level}\n{nested}set-option -g @after{level} yes\n"
                );
                fs::write(directory.join(format!("f{level}.conf")), body).expect("chain level");
            }
            fs::write(directory.join("leaf-a.conf"), "set-option -g @leaf yes\n")
                .expect("chain leaf");
            fs::write(directory.join("leaf-b.conf"), "set-option -g @leaf yes\n")
                .expect("chain leaf");
            directory.join("f1.conf")
        }

        fn read_global(shared: &Arc<Shared>, name: &str) -> String {
            shared
                .execute(
                    ClientId(u64::from(u16::MAX)),
                    ClientKind::Command,
                    &mut ExecutionContext::default(),
                    &CommandInvocation::new("show-options", ["-gv", name]),
                )
                .expect("read global option")
                .output
        }

        fn source_messages(
            mailbox: &OutboundMailbox,
            expected_kind: ClientMessageKind,
        ) -> Vec<String> {
            take_reliable_messages(mailbox)
                .into_iter()
                .filter_map(|message| match message {
                    ProtocolMessage::Event(Event {
                        payload: EventPayload::ClientMessage { kind, text, .. },
                        ..
                    }) if kind == expected_kind => Some(text),
                    _ => None,
                })
                .collect()
        }

        let shared = Arc::new(Shared::new(67));
        let command = ClientId(u64::from(u16::MAX));
        let mut context = ExecutionContext::default();

        let allowed_directory = tempfile::tempdir().expect("temporary directory");
        let allowed = chain(allowed_directory.path(), MAX_SOURCE_INVOCATIONS - 1);
        let response = shared.execute_command_request(
            command,
            ClientKind::Command,
            &mut context,
            1,
            &CommandInvocation::new("source-file", [allowed.display().to_string()]),
        );
        assert_eq!(
            response,
            CommandResponse::Success {
                request_id: 1,
                output: String::new(),
                exit_code: 0,
                stderr: String::new(),
            }
        );
        assert_eq!(
            read_global(&shared, "@depth"),
            (MAX_SOURCE_INVOCATIONS - 1).to_string()
        );
        assert_eq!(read_global(&shared, "@leaf"), "yes");

        let refused_directory = tempfile::tempdir().expect("temporary directory");
        let refused = chain(refused_directory.path(), MAX_SOURCE_INVOCATIONS);
        let response = shared.execute_command_request(
            command,
            ClientKind::Command,
            &mut context,
            2,
            &CommandInvocation::new("source-file", [refused.display().to_string()]),
        );
        assert_eq!(
            response,
            CommandResponse::Success {
                request_id: 2,
                output: String::new(),
                exit_code: 1,
                stderr: format!("{NESTED_SOURCE_LIMIT_ERROR}\n{NESTED_SOURCE_LIMIT_ERROR}\n"),
            }
        );
        assert_eq!(
            read_global(&shared, "@depth"),
            MAX_SOURCE_INVOCATIONS.to_string()
        );
        assert_eq!(
            read_global(&shared, &format!("@after{MAX_SOURCE_INVOCATIONS}")),
            "yes"
        );

        let interactive_mailbox = OutboundMailbox::new();
        let (interactive, _) = shared.register_subscribed(
            ClientKind::Interactive,
            None,
            None,
            Arc::clone(&interactive_mailbox),
        );
        take_reliable_messages(&interactive_mailbox);
        let response = shared.execute_command_request(
            interactive,
            ClientKind::Interactive,
            &mut ExecutionContext::default(),
            3,
            &CommandInvocation::new("source-file", [refused.display().to_string()]),
        );
        assert_eq!(
            response,
            CommandResponse::Success {
                request_id: 3,
                output: String::new(),
                exit_code: 0,
                stderr: String::new(),
            }
        );
        assert_eq!(
            source_messages(&interactive_mailbox, ClientMessageKind::Warning),
            ["Too many nested files", "Too many nested files"]
        );

        let control_mailbox = OutboundMailbox::new();
        let (control, _) = shared.register_subscribed(
            ClientKind::Control,
            None,
            None,
            Arc::clone(&control_mailbox),
        );
        take_reliable_messages(&control_mailbox);
        let response = shared.execute_command_request(
            control,
            ClientKind::Control,
            &mut ExecutionContext::default(),
            4,
            &CommandInvocation::new("source-file", [refused.display().to_string()]),
        );
        assert_eq!(
            response,
            CommandResponse::Success {
                request_id: 4,
                output: String::new(),
                exit_code: 1,
                stderr: String::new(),
            }
        );
        let failures = control_command_guards(take_reliable_messages(&control_mailbox))
            .into_iter()
            .filter(|(_, error, _)| *error)
            .collect::<Vec<_>>();
        assert_eq!(
            failures,
            [
                (NESTED_SOURCE_LIMIT_ERROR.to_owned(), true, false),
                (NESTED_SOURCE_LIMIT_ERROR.to_owned(), true, false),
            ]
        );
    }

    #[test]
    fn config_diagnostics_pin_the_control_mode_sniffer_wording() {
        let mut report = ConfigLoadReport::default();
        report.note_invalid_at("/tmp/mux.conf", 1, "unknown command: wibble");
        assert_eq!(
            report.message().as_deref(),
            Some("/tmp/mux.conf:1: unknown command: wibble")
        );
        assert_eq!(
            report.diagnostics(),
            ["/tmp/mux.conf:1: unknown command: wibble"]
        );

        let mut report = ConfigLoadReport::default();
        report.note_skip("focus-events");
        assert_eq!(
            report.skipped_summary().as_deref(),
            Some("skipped 1 unsupported tmux command: focus-events")
        );
        assert_eq!(report.message(), report.skipped_summary());
        report.note_skip("status-keys");
        assert_eq!(
            report.skipped_summary().as_deref(),
            Some("skipped 2 unsupported tmux commands: focus-events, status-keys")
        );

        let mut report = ConfigLoadReport::default();
        report.note_skip("focus-events");
        report.note_invalid_at("/tmp/mux.conf", 3, "unknown command: wibble");
        assert_eq!(
            report.message().as_deref(),
            Some(
                "skipped 1 unsupported tmux command: focus-events; \
                 1 invalid line: /tmp/mux.conf:3: unknown command: wibble"
            )
        );

        assert_eq!(
            source_glob_error_warning(Path::new("/tmp/["), "Pattern syntax error"),
            "Pattern syntax error: /tmp/["
        );
        assert_eq!(
            STANDARD_INPUT_SOURCE_WARNING,
            "source-file from standard input is not supported"
        );
        assert_eq!(
            missing_source_error(Path::new("/tmp/mux.conf")),
            "No such file or directory: /tmp/mux.conf"
        );
    }

    #[test]
    fn startup_causes_obey_wire_count_item_and_aggregate_bounds() {
        let mut per_item = ConfigLoadReport::startup();
        per_item.note_startup_cause(&"界".repeat(MAX_STARTUP_CONFIG_CAUSE_BYTES));
        let causes = per_item.take_startup_causes().expect("bounded item");
        assert_eq!(causes.len(), 1);
        assert!(causes[0].len() <= MAX_STARTUP_CONFIG_CAUSE_BYTES);
        assert!(causes[0].is_char_boundary(causes[0].len()));

        let mut count = ConfigLoadReport::startup();
        for _ in 0..=MAX_STARTUP_CONFIG_CAUSES {
            count.note_startup_cause("x");
        }
        assert_eq!(
            count.take_startup_causes().expect("bounded count").len(),
            MAX_STARTUP_CONFIG_CAUSES
        );

        let mut aggregate = ConfigLoadReport::startup();
        let full = "x".repeat(MAX_STARTUP_CONFIG_CAUSE_BYTES);
        for _ in 0..=MAX_STARTUP_CONFIG_CAUSES_BYTES / MAX_STARTUP_CONFIG_CAUSE_BYTES {
            aggregate.note_startup_cause(&full);
        }
        let causes = aggregate.take_startup_causes().expect("bounded aggregate");
        assert_eq!(
            causes.iter().map(String::len).sum::<usize>(),
            MAX_STARTUP_CONFIG_CAUSES_BYTES
        );
    }

    #[test]
    fn startup_config_preview_is_safe_utf8_and_explicitly_truncated() {
        let causes = vec![format!(
            "BEGIN\x1b\r\u{0085}\t\n{}{}END",
            "界".repeat(30_000),
            "\n".repeat(100_001)
        )];
        let preview = startup_config_preview(&causes);

        assert!(preview.len() <= MAX_STARTUP_CONFIG_PREVIEW_BYTES);
        assert!(preview.starts_with("BEGIN"));
        assert!(preview.ends_with(
            "\n... startup diagnostics truncated; restart in Control mode for full output"
        ));
        assert!(!preview.contains("END"));
        assert!(
            preview
                .chars()
                .filter(|character| character.is_control())
                .all(|character| matches!(character, '\n' | '\t'))
        );
        assert!(std::str::from_utf8(preview.as_bytes()).is_ok());
    }

    #[test]
    fn config_report_routes_bound_command_failures_as_runtime_errors() {
        let directory = tempfile::tempdir().expect("temporary directory");
        let mux_config = directory.path().join("mux.conf");
        fs::write(
            &mux_config,
            "bind F2 new-window\nbind x not-a-command\nbind r run-shell x\nbind F3 kill-pane\n",
        )
        .expect("mux config fixture");
        let defaults = KeyTables::default();
        let default_x = defaults.get("prefix", "x").cloned();

        let shared = Arc::new(Shared::new(52));
        let mailbox = OutboundMailbox::new();
        let (client, _) =
            shared.register_subscribed(ClientKind::Interactive, None, None, Arc::clone(&mailbox));
        let mut context = ExecutionContext::default();
        shared
            .reload_user_config_with_mux_file(client, &mut context, Some(&mux_config))
            .expect("reload mixed config");
        {
            let inner = shared.inner.lock();
            assert!(inner.engine.keys.get("prefix", "F2").is_some());
            assert!(inner.engine.keys.get("prefix", "F3").is_some());
            assert_eq!(inner.engine.keys.get("prefix", "x"), default_x.as_ref());
            assert_eq!(
                inner.engine.keys.get("prefix", "r").unwrap().commands,
                [CommandInvocation::new("run-shell", ["x"])]
            );
        }
        let messages = take_reliable_messages(&mailbox);
        assert!(messages.iter().any(|message| {
            matches!(
                message,
                ProtocolMessage::Event(Event {
                    payload: EventPayload::ClientMessage {
                        kind: ClientMessageKind::Warning,
                        text,
                        ..
                    },
                    ..
                }) if text == "Unknown command: not-a-command"
            )
        }));
        assert!(messages.iter().any(|message| {
            matches!(
                message,
                ProtocolMessage::Event(Event {
                    payload: EventPayload::ClientMessage {
                        kind: ClientMessageKind::Success,
                        text,
                        ..
                    },
                    ..
                }) if text == "Reloaded zz configuration"
            )
        }));
        assert!(!messages.iter().any(|message| {
            matches!(
                message,
                ProtocolMessage::Event(Event {
                    payload: EventPayload::ClientMessage { text, .. },
                    ..
                }) if text.contains("invalid line")
                    || text.contains("run-shell")
                    || text.contains("unsupported tmux command")
            )
        }));
    }

