    #[test]
    fn capture_boundaries_use_the_selected_format_client() {
        let mut engine = MuxEngine::default();
        let (session, _, pane) = engine.state.create_session("capture-format").unwrap();
        let (other, _, _) = engine.state.create_session("capture-other").unwrap();
        let target = ExecutionContext::for_pane(&engine.state, pane).unwrap();

        for (format_client, expected) in [
            (
                FormatClient::Attached(session),
                CaptureBoundary::Relative(1),
            ),
            (FormatClient::Attached(other), CaptureBoundary::Relative(0)),
            (FormatClient::NoClient, CaptureBoundary::VisibleEnd),
        ] {
            assert_eq!(
                {
                    let mut hooks = InertFormatHooks::default();
                    resolve_capture_boundary(
                        &engine,
                        Some("#{session_active}"),
                        false,
                        &target,
                        Some(session),
                        format_client,
                        &mut hooks,
                    )
                },
                expected
            );
        }
    }

    #[test]
    fn daemon_argument_parser_handles_compact_options_and_explicit_boundaries() {
        let args = ["-bCE", "-c/tmp", "-s::", "--", "-literal"].map(str::to_owned);
        let parsed =
            parse_buffer_command_args("run-shell", &args, &['c', 'd', 's', 't'], &['b', 'C', 'E'])
                .expect("daemon arguments");
        assert!(parsed.has('b'));
        assert!(parsed.has('C'));
        assert!(parsed.has('E'));
        assert_eq!(parsed.value('c'), Some("/tmp"));
        assert_eq!(parsed.value('s'), Some("::"));
        assert_eq!(parsed.positional, ["-literal"]);

        let parsed = parse_buffer_command_args(
            "load-buffer",
            &["path", "-b", "late"].map(str::to_owned),
            &['b', 't'],
            &[],
        )
        .expect_err("positional maximum");
        assert_eq!(
            parsed,
            ServerError::CommandParse(
                "command load-buffer: too many arguments (need at most 1)".to_owned()
            )
        );

        let error =
            parse_buffer_command_args("paste-buffer", &["-x".to_owned()], &['b', 't'], &['d', 'p'])
                .expect_err("unsupported option");
        assert!(matches!(
            error,
            ServerError::CommandParse(command)
                if command == "unsupported command: paste-buffer -x"
        ));
    }

    #[test]
    fn load_and_save_buffers_preserve_binary_bytes_and_append() {
        let directory = tempfile::tempdir().expect("temporary directory");
        let input = directory.path().join("input.bin");
        let output = directory.path().join("output.bin");
        let bytes = b"head\0middle\n\xfftail";
        fs::write(&input, bytes).expect("binary fixture");

        let shared = Arc::new(Shared::new(1));
        let context = ExecutionContext::default();
        shared
            .buffer_command(
                &context,
                "load-buffer",
                &["-bbinary".to_owned(), input.to_string_lossy().into_owned()],
            )
            .expect("load binary buffer");
        {
            let inner = shared.inner.lock();
            let buffer = resolve_buffer(&inner, Some("binary")).expect("named buffer");
            assert_eq!(buffer.data.as_ref(), bytes);
            assert!(!buffer.automatic);
        }

        let error = shared
            .buffer_command(
                &context,
                "show-buffer",
                &["-b", "binary"].map(str::to_owned),
            )
            .expect_err("binary output cannot cross the text command response");
        assert!(matches!(
            error,
            DaemonError::Server(ServerError::InvalidCommand(message))
                if message.contains("non-UTF-8") && message.contains("save-buffer")
        ));

        shared
            .buffer_command(
                &context,
                "save-buffer",
                &["-b", "binary", output.to_string_lossy().as_ref()].map(str::to_owned),
            )
            .expect("save binary buffer");
        assert_eq!(fs::read(&output).expect("saved bytes"), bytes);

        fs::write(&output, b"prefix:").expect("append prefix");
        shared
            .buffer_command(
                &context,
                "save-buffer",
                &["-a", "-bbinary", output.to_string_lossy().as_ref()].map(str::to_owned),
            )
            .expect("append binary buffer");
        let mut expected = b"prefix:".to_vec();
        expected.extend_from_slice(bytes);
        assert_eq!(fs::read(&output).expect("appended bytes"), expected);
    }

    #[test]
    fn buffer_file_paths_expand_once_in_the_selected_client_context() {
        let directory = tempfile::tempdir().expect("temporary directory");
        let shared = Arc::new(Shared::new(1));
        let (
            source_session,
            source_window,
            source_pane,
            target_session,
            target_window,
            target_pane,
        ) = {
            let mut inner = shared.inner.lock();
            let (source_session, source_window, source_pane) = inner
                .engine
                .state
                .create_session("source-session")
                .expect("source session");
            let (target_session, target_window, target_pane) = inner
                .engine
                .state
                .create_session("target-session")
                .expect("target session");
            inner
                .engine
                .state
                .rename_window(target_window, "target-window")
                .expect("target window name");
            inner
                .engine
                .state
                .update_pane_title(target_pane, "target-pane")
                .expect("target pane title");
            (
                source_session,
                source_window,
                source_pane,
                target_session,
                target_window,
                target_pane,
            )
        };
        let (source_client, _) = shared.register_subscribed(
            ClientKind::Interactive,
            Some("source-client".to_owned()),
            None,
            OutboundMailbox::new(),
        );
        let (target_client, _) = shared.register_subscribed(
            ClientKind::Interactive,
            Some("target-client".to_owned()),
            None,
            OutboundMailbox::new(),
        );
        let (command_client, _) =
            shared.register_subscribed(ClientKind::Command, None, None, OutboundMailbox::new());
        shared
            .attach(source_client, source_session)
            .expect("attach source client");
        shared
            .attach(target_client, target_session)
            .expect("attach target client");
        shared
            .inner
            .lock()
            .client_origins
            .insert(command_client, source_pane);
        let mut command_context =
            ExecutionContext::new(Some(source_session), Some(source_window), Some(source_pane));
        let mut target_context =
            ExecutionContext::new(Some(target_session), Some(target_window), Some(target_pane));

        {
            let mut inner = shared.inner.lock();
            assert_eq!(
                expand_buffer_path(
                    &mut inner,
                    Some(command_client),
                    &command_context,
                    Some("target-client"),
                    "load-buffer",
                    "#{session_name}=[#{session_active}]",
                ),
                "target-session=[1]"
            );
            assert_eq!(
                expand_buffer_path(
                    &mut inner,
                    Some(command_client),
                    &command_context,
                    None,
                    "load-buffer",
                    "#{session_name}=[#{session_active}]",
                ),
                "source-session=[1]"
            );
            assert_eq!(
                expand_buffer_path(
                    &mut inner,
                    Some(command_client),
                    &command_context,
                    Some("missing-client"),
                    "load-buffer",
                    "[#{session_active}]",
                ),
                "[]"
            );
        }

        for (index, value) in ["zzload=load-buffer", "zzsave=save-buffer"]
            .into_iter()
            .enumerate()
        {
            shared
                .execute(
                    command_client,
                    ClientKind::Command,
                    &mut command_context,
                    &CommandInvocation::new(
                        "set-option",
                        ["-s", &format!("command-alias[{}]", index + 50), value],
                    ),
                )
                .expect("install buffer command alias");
        }

        let targeted_template = directory
            .path()
            .join("#{session_name}-#{window_name}-#{pane_title}-#{command}-#{path_tag}")
            .to_string_lossy()
            .into_owned();
        for (spelling, tag) in [
            ("load-buffer", "canonical"),
            ("loadb", "alias"),
            ("loa", "prefix"),
            ("zzload", "user-alias"),
        ] {
            let input = directory.path().join(format!(
                "target-session-target-window-target-pane-load-buffer-{tag}"
            ));
            fs::write(&input, tag).expect("formatted load fixture");
            command_context
                .format_variables
                .insert("path_tag".to_owned(), tag.to_owned());
            shared
                .execute(
                    command_client,
                    ClientKind::Command,
                    &mut command_context,
                    &CommandInvocation::new(
                        spelling,
                        [
                            "-b".to_owned(),
                            tag.to_owned(),
                            "-t".to_owned(),
                            "target-client".to_owned(),
                            targeted_template.clone(),
                        ],
                    ),
                )
                .unwrap_or_else(|error| panic!("{spelling}: {error}"));
        }
        {
            let inner = shared.inner.lock();
            for tag in ["canonical", "alias", "prefix", "user-alias"] {
                assert_eq!(
                    resolve_buffer(&inner, Some(tag))
                        .expect("loaded formatted buffer")
                        .data
                        .as_ref(),
                    tag.as_bytes()
                );
            }
        }

        let origin_input = directory.path().join("source-session-load-buffer-origin");
        fs::write(&origin_input, b"origin client").expect("origin client fixture");
        shared
            .execute(
                command_client,
                ClientKind::Command,
                &mut command_context,
                &CommandInvocation::new(
                    "load-buffer",
                    [
                        "-b".to_owned(),
                        "origin".to_owned(),
                        directory
                            .path()
                            .join("#{session_name}-#{command}-origin")
                            .to_string_lossy()
                            .into_owned(),
                    ],
                ),
            )
            .expect("command origin client target");

        let non_time_input = directory.path().join("target-session-%Y");
        fs::write(&non_time_input, b"non-time format").expect("non-time fixture");
        shared
            .execute(
                command_client,
                ClientKind::Command,
                &mut command_context,
                &CommandInvocation::new(
                    "load-buffer",
                    [
                        "-b".to_owned(),
                        "non-time".to_owned(),
                        "-t".to_owned(),
                        "target-client".to_owned(),
                        directory
                            .path()
                            .join("#{session_name}-%Y")
                            .to_string_lossy()
                            .into_owned(),
                    ],
                ),
            )
            .expect("buffer path does not apply strftime");

        command_context
            .format_variables
            .insert("command".to_owned(), "explicit-#{session_name}".to_owned());
        let one_pass = directory.path().join("explicit-#{session_name}");
        fs::write(&one_pass, b"one pass").expect("one-pass fixture");
        shared
            .execute(
                command_client,
                ClientKind::Command,
                &mut command_context,
                &CommandInvocation::new(
                    "loadb",
                    [
                        "-b".to_owned(),
                        "one-pass".to_owned(),
                        "-t".to_owned(),
                        "target-client".to_owned(),
                        directory
                            .path()
                            .join("#{command}")
                            .to_string_lossy()
                            .into_owned(),
                    ],
                ),
            )
            .expect("explicit command state load");
        command_context.format_variables.remove("command");

        let missing_target_input = directory.path().join("target-session-missing-target");
        fs::write(&missing_target_input, b"quiet target miss").expect("quiet miss fixture");
        let mut source_context =
            ExecutionContext::new(Some(source_session), Some(source_window), Some(source_pane));
        shared
            .execute(
                source_client,
                ClientKind::Interactive,
                &mut source_context,
                &CommandInvocation::new(
                    "load-buffer",
                    [
                        "-b".to_owned(),
                        "quiet-target".to_owned(),
                        "-t".to_owned(),
                        "missing-client".to_owned(),
                        directory
                            .path()
                            .join("#{session_name}-missing-target")
                            .to_string_lossy()
                            .into_owned(),
                    ],
                ),
            )
            .expect("missing target falls back quietly");

        let empty = directory.path().join("target-session-empty");
        fs::write(&empty, []).expect("formatted empty fixture");
        shared
            .execute(
                command_client,
                ClientKind::Command,
                &mut command_context,
                &CommandInvocation::new(
                    "load-buffer",
                    [
                        "-b".to_owned(),
                        String::new(),
                        "-t".to_owned(),
                        "target-client".to_owned(),
                        directory
                            .path()
                            .join("#{session_name}-empty")
                            .to_string_lossy()
                            .into_owned(),
                    ],
                ),
            )
            .expect("formatted empty load");
        assert!(resolve_buffer(&shared.inner.lock(), Some("")).is_err());

        let missing_path = directory.path().join("missing-target-session");
        let error = shared
            .execute(
                command_client,
                ClientKind::Command,
                &mut command_context,
                &CommandInvocation::new(
                    "load-buffer",
                    [
                        "-t".to_owned(),
                        "target-client".to_owned(),
                        directory
                            .path()
                            .join("missing-#{session_name}")
                            .to_string_lossy()
                            .into_owned(),
                    ],
                ),
            )
            .expect_err("expanded missing path");
        assert!(matches!(
            error,
            DaemonError::Server(ServerError::InvalidCommand(message))
                if message.contains(missing_path.to_string_lossy().as_ref())
                    && !message.contains("#{session_name}")
        ));

        command_context
            .format_variables
            .insert("path".to_owned(), String::new());
        let error = shared
            .execute(
                command_client,
                ClientKind::Command,
                &mut command_context,
                &CommandInvocation::new("load-buffer", ["#{path}"]),
            )
            .expect_err("empty expanded load path");
        assert!(matches!(
            error,
            DaemonError::Server(ServerError::InvalidCommand(message))
                if message.ends_with(": ") || message.contains(": /")
        ));
        command_context
            .format_variables
            .insert("path".to_owned(), "-".to_owned());
        let error = shared
            .execute(
                command_client,
                ClientKind::Command,
                &mut command_context,
                &CommandInvocation::new("load-buffer", ["#{path}"]),
            )
            .expect_err("formatted stdin path");
        assert!(matches!(
            error,
            DaemonError::Server(ServerError::UnsupportedCommand(message))
                if message == "load-buffer from standard input"
        ));
        command_context.format_variables.remove("path");

        shared
            .execute(
                command_client,
                ClientKind::Command,
                &mut command_context,
                &CommandInvocation::new("set-buffer", ["-b", "saved", "saved payload"]),
            )
            .expect("seed saved buffer");
        command_context
            .format_variables
            .insert("path".to_owned(), String::new());
        let error = shared
            .execute(
                command_client,
                ClientKind::Command,
                &mut command_context,
                &CommandInvocation::new("save-buffer", ["-b", "saved", "#{path}"]),
            )
            .expect_err("empty expanded save path");
        assert!(matches!(
            error,
            DaemonError::Server(ServerError::InvalidCommand(message))
                if message.ends_with(": ") || message.contains(": /")
        ));
        command_context.format_variables.remove("path");
        let origin_output = directory.path().join("source-session-save-buffer-origin");
        shared
            .execute(
                command_client,
                ClientKind::Command,
                &mut command_context,
                &CommandInvocation::new(
                    "save-buffer",
                    [
                        "-b".to_owned(),
                        "saved".to_owned(),
                        directory
                            .path()
                            .join("#{session_name}-#{command}-origin")
                            .to_string_lossy()
                            .into_owned(),
                    ],
                ),
            )
            .expect("save through command origin client");
        assert_eq!(
            fs::read(origin_output).expect("origin client save"),
            b"saved payload"
        );
        for (spelling, tag) in [
            ("save-buffer", "canonical"),
            ("saveb", "alias"),
            ("sa", "prefix"),
            ("zzsave", "user-alias"),
        ] {
            target_context
                .format_variables
                .insert("path_tag".to_owned(), tag.to_owned());
            let output = directory.path().join(format!(
                "target-session-target-window-target-pane-save-buffer-{tag}"
            ));
            shared
                .execute(
                    target_client,
                    ClientKind::Interactive,
                    &mut target_context,
                    &CommandInvocation::new(
                        spelling,
                        [
                            "-b".to_owned(),
                            "saved".to_owned(),
                            targeted_template.clone(),
                        ],
                    ),
                )
                .unwrap_or_else(|error| panic!("{spelling}: {error}"));
            assert_eq!(fs::read(output).expect("formatted save"), b"saved payload");
        }

        target_context
            .format_variables
            .insert("command".to_owned(), "explicit-#{session_name}".to_owned());
        let explicit_save = directory.path().join("save-explicit-#{session_name}");
        shared
            .execute(
                target_client,
                ClientKind::Interactive,
                &mut target_context,
                &CommandInvocation::new(
                    "saveb",
                    [
                        "-b".to_owned(),
                        "saved".to_owned(),
                        directory
                            .path()
                            .join("save-#{command}")
                            .to_string_lossy()
                            .into_owned(),
                    ],
                ),
            )
            .expect("explicit command state save");
        assert_eq!(
            fs::read(explicit_save).expect("explicit formatted save"),
            b"saved payload"
        );
        target_context.format_variables.remove("command");
        target_context
            .format_variables
            .insert("path".to_owned(), "-".to_owned());
        let error = shared
            .execute(
                target_client,
                ClientKind::Interactive,
                &mut target_context,
                &CommandInvocation::new("save-buffer", ["-b", "saved", "#{path}"]),
            )
            .expect_err("formatted stdout path");
        assert!(matches!(
            error,
            DaemonError::Server(ServerError::UnsupportedCommand(message))
                if message == "save-buffer to standard output"
        ));

        let empty_shared = Arc::new(Shared::new(1));
        assert!(matches!(
            empty_shared.buffer_command(
                &ExecutionContext::default(),
                "save-buffer",
                &["-".to_owned()],
            ),
            Err(DaemonError::Server(ServerError::MissingTarget(target)))
                if target == "paste buffer"
        ));
    }

    #[test]
    fn set_buffer_append_updates_named_buffers_but_creates_automatic_buffers_without_a_name() {
        let shared = Arc::new(Shared::new(1));
        let context = ExecutionContext::default();
        for arguments in [
            vec!["-b", "named", "alpha"],
            vec!["automatic"],
            vec!["-abnamed", "--", "-omega"],
            vec!["-a", "new automatic"],
        ] {
            let arguments = arguments.into_iter().map(str::to_owned).collect::<Vec<_>>();
            shared
                .buffer_command(&context, "set-buffer", &arguments)
                .expect("set buffer");
        }

        let inner = shared.inner.lock();
        assert_eq!(inner.paste_buffers.len(), 3);
        assert_eq!(inner.paste_buffers[0].data.as_ref(), b"new automatic");
        assert!(inner.paste_buffers[0].automatic);
        let named = resolve_buffer(&inner, Some("named")).expect("named buffer");
        assert_eq!(named.data.as_ref(), b"alpha-omega");
        assert!(!named.automatic);
    }

    #[test]
    fn set_buffer_rename_replaces_destinations_ignores_data_and_uses_the_top_automatic() {
        let shared = Arc::new(Shared::new(1));
        let context = ExecutionContext::default();
        for arguments in [
            vec!["-b", "source", "alpha"],
            vec!["-b", "destination", "beta"],
            vec!["top automatic"],
        ] {
            shared
                .buffer_command(
                    &context,
                    "set-buffer",
                    &arguments.into_iter().map(str::to_owned).collect::<Vec<_>>(),
                )
                .expect("seed buffer");
        }

        shared
            .buffer_command(
                &context,
                "set-buffer",
                &[
                    "-b",
                    "source",
                    "-n",
                    "destination",
                    "ignored replacement data",
                ]
                .map(str::to_owned),
            )
            .expect("rename over destination");
        {
            let inner = shared.inner.lock();
            assert!(resolve_buffer(&inner, Some("source")).is_err());
            let renamed = resolve_buffer(&inner, Some("destination")).expect("renamed buffer");
            assert_eq!(renamed.data.as_ref(), b"alpha");
            assert_eq!(inner.paste_buffers.len(), 2);
        }

        shared
            .buffer_command(
                &context,
                "set-buffer",
                &["-an", "named-top", "ignored"].map(str::to_owned),
            )
            .expect("rename top automatic");
        {
            let inner = shared.inner.lock();
            let renamed = resolve_buffer(&inner, Some("named-top")).expect("named top buffer");
            assert_eq!(renamed.data.as_ref(), b"top automatic");
            assert!(!renamed.automatic);
            assert!(!inner.paste_buffers.iter().any(|buffer| buffer.automatic));
        }

        assert!(matches!(
            shared.buffer_command(
                &context,
                "set-buffer",
                &["-n", "nowhere", "ignored"].map(str::to_owned),
            ),
            Err(DaemonError::Server(ServerError::InvalidCommand(message)))
                if message == "no buffer"
        ));
        assert!(matches!(
            shared.buffer_command(
                &context,
                "set-buffer",
                &["-b", "missing", "-n", "", "ignored"].map(str::to_owned),
            ),
            Err(DaemonError::Server(ServerError::InvalidCommand(message)))
                if message == "unknown buffer: missing"
        ));
    }

    #[test]
    fn buffer_formats_read_named_rows_and_the_top_automatic_buffer() {
        let shared = Arc::new(Shared::new(1));
        let mut context = {
            let mut inner = shared.inner.lock();
            let (_, _, pane) = inner
                .engine
                .state
                .create_session("w")
                .expect("format target session");
            ExecutionContext::for_pane(&inner.engine.state, pane).expect("format target pane")
        };
        shared
            .buffer_command(
                &context,
                "set-buffer",
                &["-b", "named", "alpha"].map(str::to_owned),
            )
            .expect("set named buffer");
        let named = shared
            .buffer_command(
                &context,
                "list-buffers",
                &[
                    "-F".to_owned(),
                    "#{command}|#{buffer_name}|#{buffer_size}|#{buffer_sample}|#{!!:#{buffer_created}}"
                        .to_owned(),
                ],
            )
            .expect("format named buffer");
        assert_eq!(named.output, "list-buffers|named|5|alpha|1");

        shared
            .buffer_command(&context, "set-buffer", &["bravo".to_owned()])
            .expect("set automatic buffer");
        let displayed = shared
            .execute(
                ClientId(1),
                ClientKind::Command,
                &mut context,
                &CommandInvocation::new(
                    "display-message",
                    [
                        "-p",
                        "#{buffer_name}|#{buffer_size}|#{buffer_sample}|#{!!:#{buffer_created}}",
                    ],
                ),
            )
            .expect("format automatic buffer");
        assert_eq!(displayed.output, "buffer0|5|bravo|1");

        for (arguments, expected) in [
            (vec!["-F", "#{buffer_name}"], "buffer0\nnamed"),
            (vec!["-r", "-F", "#{buffer_name}"], "buffer0\nnamed"),
            (
                vec!["-O", "name", "-r", "-F", "#{buffer_name}"],
                "named\nbuffer0",
            ),
            (
                vec![
                    "-f",
                    "#{&&:#{==:#{command},list-buffers},#{==:#{buffer_name},named}}",
                    "-F",
                    "#{command}:#{buffer_name}",
                ],
                "list-buffers:named",
            ),
        ] {
            let listed = shared
                .buffer_command(
                    &context,
                    "list-buffers",
                    &arguments.into_iter().map(str::to_owned).collect::<Vec<_>>(),
                )
                .expect("sort and filter buffers");
            assert_eq!(listed.output, expected);
        }

        let pane = context.pane.expect("format target pane").to_string();
        let targeted = shared
            .execute(
                ClientId(1),
                ClientKind::Command,
                &mut context,
                &CommandInvocation::new(
                    "display-message",
                    [
                        "-p",
                        "-t",
                        pane.as_str(),
                        "#{buffer_name}|#{buffer_size}|#{buffer_sample}|#{!!:#{buffer_created}}",
                    ],
                ),
            )
            .expect("format automatic buffer with a pane target");
        assert_eq!(targeted.output, "buffer0|5|bravo|1");
    }

    #[test]
    fn unnamed_buffer_commands_target_the_newest_automatic_buffer() {
        let shared = Arc::new(Shared::new(1));
        let context = ExecutionContext::default();
        for arguments in [
            vec!["-b", "named-old", "named old"],
            vec!["automatic"],
            vec!["-b", "named-new", "named new"],
        ] {
            shared
                .buffer_command(
                    &context,
                    "set-buffer",
                    &arguments.into_iter().map(str::to_owned).collect::<Vec<_>>(),
                )
                .expect("set buffer");
        }

        let shown = shared
            .buffer_command(&context, "show-buffer", &[])
            .expect("show automatic buffer");
        assert_eq!(shown.output, "automatic");
        shared
            .buffer_command(&context, "delete-buffer", &[])
            .expect("delete automatic buffer");
        let inner = shared.inner.lock();
        assert_eq!(inner.paste_buffers.len(), 2);
        assert!(inner.paste_buffers.iter().all(|buffer| !buffer.automatic));
        assert_eq!(inner.paste_buffers[0].name, "named-new");
        drop(inner);
        assert!(matches!(
            shared.buffer_command(&context, "show-buffer", &[]),
            Err(DaemonError::Server(ServerError::MissingTarget(target)))
                if target == "paste buffer"
        ));
    }

    #[cfg(unix)]
    #[test]
    fn paste_buffer_reaches_a_detached_terminal_actor() {
        let shared = Arc::new(Shared::new(1));
        let mut context = ExecutionContext::default();
        shared
            .execute(
                ClientId(7),
                ClientKind::Command,
                &mut context,
                &CommandInvocation::new("new-session", ["-d", "-s", "detached"]),
            )
            .expect("detached session");
        let pane = context.pane.expect("terminal pane");
        shared
            .execute(
                ClientId(7),
                ClientKind::Command,
                &mut context,
                &CommandInvocation::new("set-buffer", ["printf 'ZZ_DETACHED_BUFFER_OK\\n'\n"]),
            )
            .expect("shell buffer");
        shared
            .execute(
                ClientId(7),
                ClientKind::Command,
                &mut context,
                &CommandInvocation::new("paste-buffer", ["-t", &pane.to_string()]),
            )
            .expect("paste without an interactive attachment");

        let deadline = Instant::now() + Duration::from_secs(30);
        loop {
            let captured = shared
                .execute(
                    ClientId(7),
                    ClientKind::Command,
                    &mut context,
                    &CommandInvocation::new("capture-pane", ["-p", "-t", &pane.to_string()]),
                )
                .expect("capture detached terminal")
                .output;
            if captured.contains("ZZ_DETACHED_BUFFER_OK") {
                break;
            }
            assert!(
                Instant::now() < deadline,
                "detached terminal did not receive paste-buffer"
            );
            thread::sleep(Duration::from_millis(10));
        }

        let buffered = shared
            .execute(
                ClientId(7),
                ClientKind::Command,
                &mut context,
                &CommandInvocation::new(
                    "capture-pane",
                    ["-b", "detached-capture", "-t", &pane.to_string()],
                ),
            )
            .expect("capture detached terminal into a named buffer");
        assert!(buffered.output.is_empty());
        let shown = shared
            .execute(
                ClientId(7),
                ClientKind::Command,
                &mut context,
                &CommandInvocation::new("show-buffer", ["-b", "detached-capture"]),
            )
            .expect("show captured named buffer")
            .output;
        assert!(shown.contains("ZZ_DETACHED_BUFFER_OK"));
    }

    #[cfg(unix)]
    #[test]
    fn seeded_global_environment_and_session_markers_reach_terminal_spawn() {
        let shared = Arc::new(Shared::new(1));
        shared.inner.lock().engine.seed_global_environment([
            ("PHASE4D_SEEDED", "daemon"),
            ("HIDDENPROBE", "daemonval"),
            ("TERM", "inherited-term"),
        ]);
        let mut context = ExecutionContext::default();
        shared
            .execute(
                ClientId(7),
                ClientKind::Command,
                &mut context,
                &CommandInvocation::new(
                    "set-environment",
                    ["-g", "-h", "HIDDENPROBE", "newhidden"],
                ),
            )
            .expect("hidden global environment");
        shared
            .execute(
                ClientId(7),
                ClientKind::Command,
                &mut context,
                &CommandInvocation::new("new-session", ["-d", "-s", "seeded-environment"]),
            )
            .expect("session");
        let pane = context.pane.expect("terminal pane");
        let session = context.session.expect("terminal session");
        let expected_tmux = tmux_environment(&shared.socket_path, Some(session));
        assert_eq!(
            shared.inner.lock().terminal_spawns[&pane].terminal_type,
            Some("tmux-256color".to_owned())
        );
        {
            let inner = shared.inner.lock();
            let environment = &inner.terminal_spawns[&pane].env;
            assert!(environment.contains(&("TMUX".to_owned(), Some(expected_tmux.clone()))));
            assert!(environment.contains(&("TMUX_PANE".to_owned(), Some(pane.to_string()))));
        }
        shared
            .execute(
                ClientId(7),
                ClientKind::Command,
                &mut context,
                &CommandInvocation::new(
                    "set-buffer",
                    [
                        "printf 'PHASE4D_SEEDED=[%s] DISPLAY=[%s] HP=[%s] TERM=[%s]\\n' \"$PHASE4D_SEEDED\" \"${DISPLAY-unset}\" \"${HIDDENPROBE-}\" \"$TERM\"; printf 'TMUX=[%s]\\nTMUX_PANE=[%s]\\n' \"$TMUX\" \"$TMUX_PANE\"\n",
                    ],
                ),
            )
            .expect("shell probe");
        shared
            .execute(
                ClientId(7),
                ClientKind::Command,
                &mut context,
                &CommandInvocation::new("paste-buffer", ["-t", &pane.to_string()]),
            )
            .expect("paste shell probe");

        let deadline = Instant::now() + Duration::from_secs(30);
        loop {
            let captured = shared
                .execute(
                    ClientId(7),
                    ClientKind::Command,
                    &mut context,
                    &CommandInvocation::new("capture-pane", ["-p", "-t", &pane.to_string()]),
                )
                .expect("capture terminal")
                .output;
            if captured
                .contains("PHASE4D_SEEDED=[daemon] DISPLAY=[unset] HP=[] TERM=[tmux-256color]")
                && captured.contains(&format!("TMUX=[{expected_tmux}]"))
                && captured.contains(&format!("TMUX_PANE=[{pane}]"))
            {
                break;
            }
            assert!(
                Instant::now() < deadline,
                "seeded environment did not reach terminal spawn"
            );
            thread::sleep(Duration::from_millis(10));
        }
        shared
            .execute(
                ClientId(7),
                ClientKind::Command,
                &mut context,
                &CommandInvocation::new("respawn-pane", ["-k", "-t", &pane.to_string()]),
            )
            .expect("respawn terminal pane");
        let inner = shared.inner.lock();
        let environment = &inner.terminal_spawns[&pane].env;
        assert!(environment.contains(&("TMUX".to_owned(), Some(expected_tmux))));
        assert!(environment.contains(&("TMUX_PANE".to_owned(), Some(pane.to_string()))));
    }

    #[cfg(unix)]
    #[test]
    fn new_session_creation_environment_reaches_the_first_terminal() {
        let shared = Arc::new(Shared::new(1));
        shared
            .inner
            .lock()
            .engine
            .seed_global_environment([("DISPLAY", "client")]);
        let mut context = ExecutionContext::default();
        let spawned_value = |pane: PaneId, name: &str| {
            shared.inner.lock().terminal_spawns[&pane]
                .env
                .iter()
                .rev()
                .find_map(|(candidate, value)| (candidate == name).then(|| value.clone()))
                .flatten()
        };

        shared
            .execute(
                ClientId(7),
                ClientKind::Command,
                &mut context,
                &CommandInvocation::new(
                    "new-session",
                    [
                        "-d",
                        "-s",
                        "creation-environment",
                        "-e",
                        "DISPLAY=first",
                        "-e",
                        "MALFORMED",
                        "-e",
                        "=ignored",
                        "-e",
                        "DISPLAY=last",
                        "--",
                        "sleep",
                        "30",
                    ],
                ),
            )
            .expect("session environment");
        let pane = context.pane.expect("first pane");
        assert_eq!(spawned_value(pane, "DISPLAY").as_deref(), Some("last"));
        assert!(
            !shared.inner.lock().terminal_spawns[&pane]
                .env
                .iter()
                .any(|(name, _)| name.is_empty())
        );
        assert_eq!(
            shared
                .execute(
                    ClientId(7),
                    ClientKind::Command,
                    &mut context,
                    &CommandInvocation::new(
                        "show-environment",
                        ["-t", "creation-environment", "DISPLAY"],
                    ),
                )
                .unwrap()
                .output,
            "DISPLAY=last"
        );
        assert_eq!(
            shared
                .execute(
                    ClientId(7),
                    ClientKind::Command,
                    &mut context,
                    &CommandInvocation::new(
                        "show-environment",
                        ["-t", "creation-environment", ""],
                    ),
                )
                .unwrap()
                .output,
            "=ignored"
        );

        shared
            .execute(
                ClientId(7),
                ClientKind::Command,
                &mut context,
                &CommandInvocation::new(
                    "new-session",
                    ["-d", "-E", "-s", "creation-unseeded", "--", "sleep", "30"],
                ),
            )
            .expect("unseeded session");
        let pane = context.pane.expect("unseeded first pane");
        assert_eq!(spawned_value(pane, "DISPLAY").as_deref(), Some("client"));
        assert!(
            shared
                .execute(
                    ClientId(7),
                    ClientKind::Command,
                    &mut context,
                    &CommandInvocation::new("show-environment", ["-t", "creation-unseeded"],),
                )
                .unwrap()
                .output
                .is_empty()
        );

        shared
            .execute(
                ClientId(7),
                ClientKind::Command,
                &mut context,
                &CommandInvocation::new(
                    "new-session",
                    [
                        "-d",
                        "-E",
                        "-s",
                        "creation-explicit",
                        "-e",
                        "DISPLAY=explicit",
                        "--",
                        "sleep",
                        "30",
                    ],
                ),
            )
            .expect("explicit unseeded session");
        let pane = context.pane.expect("explicit first pane");
        assert_eq!(spawned_value(pane, "DISPLAY").as_deref(), Some("explicit"));
    }

    #[cfg(unix)]
    #[test]
    fn new_and_split_window_apply_local_environment_and_spawn_empty_panes() {
        let shared = Arc::new(Shared::new(1));
        let mut context = ExecutionContext::default();
        shared
            .execute(
                ClientId(7),
                ClientKind::Command,
                &mut context,
                &CommandInvocation::new(
                    "new-session",
                    ["-d", "-s", "pane-spawn-options", "--", "sleep", "30"],
                ),
            )
            .expect("session");
        let source = context.pane.expect("source pane");

        let window = shared
            .execute(
                ClientId(7),
                ClientKind::Command,
                &mut context,
                &CommandInvocation::new(
                    "new-window",
                    [
                        "-d",
                        "-t",
                        "pane-spawn-options",
                        "-e",
                        "PANE_ONLY=first",
                        "-e",
                        "MALFORMED",
                        "-e",
                        "=ignored",
                        "-e",
                        "PANE_ONLY=last",
                        "-e",
                        "TMUX=overlay",
                        "-e",
                        "TMUX_PANE=bogus",
                        "-e",
                        "PWD=/bogus",
                        "--",
                        "sleep",
                        "30",
                    ],
                ),
            )
            .expect("environment window");
        let window_pane = window
            .effects
            .iter()
            .find_map(|effect| match effect {
                MuxEffect::PaneCreated { pane, .. } => Some(*pane),
                _ => None,
            })
            .expect("window pane");
        {
            let inner = shared.inner.lock();
            let spawn = &inner.terminal_spawns[&window_pane];
            let expected_pane = window_pane.to_string();
            let value = |name: &str| {
                spawn
                    .env
                    .iter()
                    .rev()
                    .find_map(|(candidate, value)| (candidate == name).then_some(value.as_deref()))
                    .flatten()
            };
            assert_eq!(value("PANE_ONLY"), Some("last"));
            assert_eq!(value("TMUX"), Some("overlay"));
            assert_eq!(value("TMUX_PANE"), Some(expected_pane.as_str()));
            assert_eq!(
                value("PWD"),
                spawn.working_directory.as_deref().and_then(Path::to_str)
            );
            assert!(!spawn.env.iter().any(|(name, _)| name.is_empty()));
            assert!(!spawn.env.iter().any(|(name, _)| name == "MALFORMED"));
        }

        let split = shared
            .execute(
                ClientId(7),
                ClientKind::Command,
                &mut context,
                &CommandInvocation::new(
                    "split-window",
                    [
                        "-d",
                        "-t",
                        &source.to_string(),
                        "-e",
                        "SPLIT_ONLY=first",
                        "-e",
                        "SPLIT_ONLY=last",
                        "--",
                        "sleep",
                        "30",
                    ],
                ),
            )
            .expect("environment split");
        let split_pane = split
            .effects
            .iter()
            .find_map(|effect| match effect {
                MuxEffect::PaneCreated { pane, .. } => Some(*pane),
                _ => None,
            })
            .expect("split pane");
        {
            let inner = shared.inner.lock();
            let environment = &inner.terminal_spawns[&split_pane].env;
            assert_eq!(
                environment.iter().rev().find_map(|(name, value)| {
                    (name == "SPLIT_ONLY").then_some(value.as_deref())
                }),
                Some(Some("last"))
            );
        }
        assert!(matches!(
            shared.execute(
                ClientId(7),
                ClientKind::Command,
                &mut context,
                &CommandInvocation::new(
                    "show-environment",
                    ["-t", "pane-spawn-options", "PANE_ONLY"],
                ),
            ),
            Err(DaemonError::Server(ServerError::InvalidCommand(message)))
                if message == "unknown variable: PANE_ONLY"
        ));

        let source_target = source.to_string();
        for (name, arguments, keeps_empty_argument) in [
            (
                "new-window",
                vec!["-d", "-t", "pane-spawn-options", "-E"],
                false,
            ),
            (
                "new-window",
                vec!["-d", "-t", "pane-spawn-options", "-E", ""],
                true,
            ),
            (
                "split-window",
                vec!["-d", "-t", source_target.as_str(), "-E"],
                false,
            ),
        ] {
            let execution = shared
                .execute(
                    ClientId(7),
                    ClientKind::Command,
                    &mut context,
                    &CommandInvocation::new(name, arguments),
                )
                .expect("empty pane");
            let pane = execution
                .effects
                .iter()
                .find_map(|effect| match effect {
                    MuxEffect::PaneCreated { pane, .. } => Some(*pane),
                    _ => None,
                })
                .expect("empty pane id");
            let inner = shared.inner.lock();
            assert_eq!(inner.terminals[&pane].process_id(), None);
            assert!(!inner.engine.state.pane(pane).unwrap().dead);
            assert_eq!(
                inner.terminal_spawns[&pane]
                    .command
                    .as_deref()
                    .is_some_and(|command| command == [""]),
                keeps_empty_argument
            );
        }
    }

    fn paste_upload_fixture(
        directory: &Path,
        name: &str,
    ) -> (Arc<Shared>, Arc<OutboundMailbox>, ClientId, PaneId) {
        let mut shared = Shared::new(1);
        shared.paste_directory = directory.to_path_buf();
        let shared = Arc::new(shared);
        let mailbox = OutboundMailbox::new();
        let (client, _) =
            shared.register_subscribed(ClientKind::Interactive, None, None, Arc::clone(&mailbox));
        let mut context = ExecutionContext::default();
        shared
            .execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new("new-session", ["-s", name]),
            )
            .expect("new session");
        let session = context.session.expect("session");
        let pane = context.pane.expect("pane");
        shared.attach(client, session).expect("attach session");
        (shared, mailbox, client, pane)
    }

    fn client_message_texts(messages: Vec<ProtocolMessage>) -> Vec<String> {
        messages
            .into_iter()
            .filter_map(|message| match message {
                ProtocolMessage::Event(Event {
                    payload:
                        EventPayload::ClientMessage {
                            kind: ClientMessageKind::Error,
                            text,
                            ..
                        },
                    ..
                }) => Some(text),
                _ => None,
            })
            .collect()
    }

    fn wait_for_pasted_path(shared: &Arc<Shared>, client: ClientId, pane: PaneId, file_name: &str) {
        let mut context = ExecutionContext::default();
        let deadline = Instant::now() + Duration::from_secs(5);
        loop {
            let captured = shared
                .execute(
                    client,
                    ClientKind::Interactive,
                    &mut context,
                    &CommandInvocation::new("capture-pane", ["-p", "-t", &pane.to_string()]),
                )
                .expect("capture pane")
                .output;
            if captured.contains(file_name) {
                break;
            }
            assert!(
                Instant::now() < deadline,
                "the uploaded image path never reached the pane; captured {captured:?}"
            );
            thread::sleep(Duration::from_millis(20));
        }
    }

    #[cfg(unix)]
    #[test]
    fn paste_path_image_upload_writes_a_private_file_stages_preview_and_pastes_the_path() {
        use std::os::unix::fs::PermissionsExt as _;

        let directory = tempfile::tempdir().expect("temporary directory");
        let (shared, mailbox, client, pane) =
            paste_upload_fixture(&directory.path().join("paste"), "paste-upload");
        let terminal = Arc::clone(&shared.inner.lock().terminals[&pane]);
        terminal.resize(200, 10, 8, 18);
        wait_for_terminal_dimensions(&terminal, TerminalViewId(client.0), 200, 10);
        take_reliable_messages(&mailbox);

        let image = [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a];
        shared.begin_paste_upload(
            client,
            ClientKind::Interactive,
            1,
            pane,
            PasteUploadPurpose::PastePath,
            "png".to_owned(),
            6,
        );
        shared.extend_paste_upload(client, 1, &image[..3]);
        assert!(
            shared.inner.lock().paste_uploads.contains_key(&(client, 1)),
            "a partial upload should stay open"
        );
        shared.extend_paste_upload(client, 1, &image[3..]);
        assert!(
            shared.inner.lock().paste_uploads.is_empty(),
            "reaching the declared total should finish the upload"
        );

        let file_name = format!("paste-{client}-1.png");
        let written = shared.paste_directory.join(&file_name);
        assert_eq!(fs::read(&written).expect("uploaded image"), image);
        assert_eq!(
            fs::metadata(&written)
                .expect("upload metadata")
                .permissions()
                .mode()
                & 0o777,
            0o600,
        );
        assert_eq!(
            fs::metadata(&shared.paste_directory)
                .expect("upload directory metadata")
                .permissions()
                .mode()
                & 0o777,
            0o700,
        );
        {
            let pasted_images = shared.pasted_images.lock();
            let stored = pasted_images.get(&pane).expect("pane image state");
            assert_eq!(stored.pending.len(), 1);
            assert_eq!(stored.pending_bytes, image.len());
            assert_eq!(stored.pending[0].format, PastedImageFormat::Png);
            assert_eq!(stored.pending[0].bytes.as_ref(), image);
            assert!(stored.images.is_empty());
        }
        assert!(
            client_message_texts(take_reliable_messages(&mailbox)).is_empty(),
            "a completed upload should not report an error"
        );

        wait_for_pasted_path(&shared, client, pane, &file_name);
    }

