    #[test]
    fn key_binding_command_groups_continue_after_a_failed_physical_line() {
        let shared = Arc::new(Shared::new(1));
        let (session, _, pane) = switch_test_session(&shared, "grouped");
        let (client, _) = shared.register_subscribed(
            ClientKind::Interactive,
            Some("writer".to_owned()),
            None,
            OutboundMailbox::new(),
        );
        shared.attach(client, session).expect("attach");
        let mut context = ExecutionContext::for_pane(&shared.inner.lock().engine.state, pane)
            .expect("binding context");

        let first_group = SourceSpan {
            source: "<bind-key>".to_owned(),
            line: 1,
            column: 1,
        };
        let second_group = SourceSpan {
            source: "<bind-key>".to_owned(),
            line: 2,
            column: 1,
        };
        shared
            .execute_key_commands(
                client,
                ClientKind::Interactive,
                &mut context,
                pane,
                &[
                    CommandInvocation::new("kill-pane", ["-t", "missing"])
                        .with_source(first_group.clone()),
                    CommandInvocation::new(
                        "set-environment",
                        ["-g", "BIND_GROUP_CONTINUED", "yes"],
                    )
                    .with_source(second_group),
                ],
                false,
            )
            .expect_err("first physical group fails");
        assert_eq!(
            shared
                .inner
                .lock()
                .engine
                .global_environment_variable("BIND_GROUP_CONTINUED")
                .as_deref(),
            Some("yes")
        );

        shared
            .execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new("set-environment", ["-g", "-u", "BIND_GROUP_CONTINUED"]),
            )
            .expect("clear group marker");
        shared
            .execute_key_commands(
                client,
                ClientKind::Interactive,
                &mut context,
                pane,
                &[
                    CommandInvocation::new("kill-pane", ["-t", "missing"])
                        .with_source(first_group.clone()),
                    CommandInvocation::new("set-environment", ["-g", "BIND_GROUP_CONTINUED", "no"])
                        .with_source(first_group),
                ],
                false,
            )
            .expect_err("one command group fails");
        assert_eq!(
            shared
                .inner
                .lock()
                .engine
                .global_environment_variable("BIND_GROUP_CONTINUED"),
            None
        );
    }

    #[test]
    fn key_binding_command_exits_are_queue_status_not_input_errors() {
        let directory = tempfile::tempdir().expect("temporary directory");
        let missing = directory.path().join("missing.conf");
        let shared = Arc::new(Shared::new(1));
        let (session, _, pane) = switch_test_session(&shared, "binding-command-exit");
        let mailbox = OutboundMailbox::new();
        let (client, _) = shared.register_subscribed(
            ClientKind::Interactive,
            Some("writer".to_owned()),
            None,
            Arc::clone(&mailbox),
        );
        shared.attach(client, session).expect("attach");
        take_reliable_messages(&mailbox);
        let mut context = ExecutionContext::for_pane(&shared.inner.lock().engine.state, pane)
            .expect("binding context");
        let first_group = SourceSpan {
            source: "<bind-key>".to_owned(),
            line: 1,
            column: 1,
        };
        let second_group = SourceSpan {
            source: "<bind-key>".to_owned(),
            line: 2,
            column: 1,
        };
        let third_group = SourceSpan {
            source: "<bind-key>".to_owned(),
            line: 3,
            column: 1,
        };

        shared
            .execute_key_commands(
                client,
                ClientKind::Interactive,
                &mut context,
                pane,
                &[
                    CommandInvocation::new("source-file", [missing.display().to_string()])
                        .with_source(first_group.clone()),
                    CommandInvocation::new(
                        "set-environment",
                        ["-g", "BIND_COMMAND_EXIT_SAME_GROUP", "no"],
                    )
                    .with_source(first_group.clone()),
                    CommandInvocation::new(
                        "set-environment",
                        ["-g", "BIND_COMMAND_EXIT_NEXT_GROUP", "yes"],
                    )
                    .with_source(second_group.clone()),
                ],
                false,
            )
            .expect("command exit stays inside the key queue");
        {
            let inner = shared.inner.lock();
            assert_eq!(
                inner
                    .engine
                    .global_environment_variable("BIND_COMMAND_EXIT_SAME_GROUP"),
                None
            );
            assert_eq!(
                inner
                    .engine
                    .global_environment_variable("BIND_COMMAND_EXIT_NEXT_GROUP"),
                Some("yes".to_owned())
            );
        }
        assert!(take_reliable_messages(&mailbox).iter().any(|message| {
            matches!(
                message,
                ProtocolMessage::Event(Event {
                    payload: EventPayload::ClientMessage {
                        kind: ClientMessageKind::Warning,
                        text,
                        ..
                    },
                    ..
                }) if text == &missing_source_error(&missing)
            )
        }));

        let error = shared
            .execute_key_commands(
                client,
                ClientKind::Interactive,
                &mut context,
                pane,
                &[
                    CommandInvocation::new("source-file", [missing.display().to_string()])
                        .with_source(first_group),
                    CommandInvocation::new("kill-pane", ["-t", "missing"])
                        .with_source(second_group),
                    CommandInvocation::new(
                        "set-environment",
                        ["-g", "BIND_COMMAND_EXIT_AFTER_ERROR", "yes"],
                    )
                    .with_source(third_group),
                ],
                false,
            )
            .expect_err("later server error escapes the key queue");
        assert_eq!(daemon_error_text(&error), "can't find pane: missing");
        assert_eq!(
            shared
                .inner
                .lock()
                .engine
                .global_environment_variable("BIND_COMMAND_EXIT_AFTER_ERROR"),
            Some("yes".to_owned())
        );
    }

    #[test]
    fn terminal_mouse_is_rejected_only_for_sized_clients_when_mouse_is_off() {
        let shared = Arc::new(Shared::new(1));
        let (a, _, pane) = switch_test_session(&shared, "A");
        let mailbox = OutboundMailbox::new();
        let (client, _) = shared.register_subscribed(
            ClientKind::Interactive,
            Some("tui".to_owned()),
            None,
            Arc::clone(&mailbox),
        );
        shared.attach(client, a).expect("attach");
        let wheel_for = |pane: PaneId| InputMessage::TerminalView {
            pane,
            action: TerminalViewAction::ScrollWheel {
                lines: 3,
                input: TerminalMouseInput::new(
                    TerminalMousePhase::Press,
                    Some(TerminalMouseButton::ScrollDown),
                    PointerCellEvent {
                        column: 1,
                        row: 1,
                        click_count: 1,
                        rectangle: false,
                    },
                    24,
                    18,
                    128,
                    72,
                    8,
                    18,
                    Modifiers::default(),
                    false,
                ),
            },
        };
        let wheel = wheel_for(pane);
        {
            let inner = shared.inner.lock();
            assert!(!terminal_mouse_rejected(&inner, client, &wheel));
        }
        shared.inner.lock().client_sizes.insert(client, (80, 24));
        {
            let inner = shared.inner.lock();
            assert!(!terminal_mouse_rejected(&inner, client, &wheel));
        }
        shared
            .execute(
                ClientId(u64::MAX),
                ClientKind::Command,
                &mut ExecutionContext::default(),
                &CommandInvocation::new("set-option", ["-g", "mouse", "off"]),
            )
            .expect("turn mouse off");
        {
            let inner = shared.inner.lock();
            assert!(terminal_mouse_rejected(&inner, client, &wheel));
            let focus = InputMessage::TerminalView {
                pane,
                action: TerminalViewAction::Focus(true),
            };
            assert!(!terminal_mouse_rejected(&inner, client, &focus));
        }
        let rejected_sort = {
            let mut inner = shared.inner.lock();
            inner.engine.state.sessions.get_mut(&a).unwrap().activity = Some(11);
            inner.engine.state.sessions[&a].sort_activity
        };
        shared
            .input(
                client,
                ClientKind::Interactive,
                &mut ExecutionContext::default(),
                wheel_for(pane),
            )
            .expect("reject mouse input after recording activity");
        {
            let inner = shared.inner.lock();
            assert!(inner.engine.state.sessions[&a].sort_activity > rejected_sort);
            assert_ne!(inner.engine.state.sessions[&a].activity, Some(11));
        }
        shared.inner.lock().client_sizes.remove(&client);
        {
            let inner = shared.inner.lock();
            assert!(!terminal_mouse_rejected(&inner, client, &wheel));
        }

        shared.inner.lock().client_sizes.insert(client, (80, 24));
        let mut context = ExecutionContext::default();
        shared
            .execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new("new-session", ["-d", "-s", "tracked"]),
            )
            .expect("real session");
        let tracked_pane = context.pane.expect("real pane");
        let terminal = Arc::clone(&shared.inner.lock().terminals[&tracked_pane]);
        {
            let inner = shared.inner.lock();
            assert!(
                terminal_mouse_rejected(&inner, client, &wheel_for(tracked_pane)),
                "a live pane without app mouse tracking still rejects"
            );
        }
        terminal.send_text("printf '\\033[?1002hMOUSEON\\n'\n");
        let deadline = Instant::now() + Duration::from_secs(10);
        while !terminal.latest_viewport().mouse_tracking {
            assert!(
                Instant::now() < deadline,
                "pane never reported mouse tracking"
            );
            thread::sleep(Duration::from_millis(10));
        }
        {
            let inner = shared.inner.lock();
            assert!(
                !terminal_mouse_rejected(&inner, client, &wheel_for(tracked_pane)),
                "an app-requested mouse pane accepts forwarded events while the option is off"
            );
        }
    }

