    #[test]
    fn native_command_prompt_precedes_pane_input_and_runs_command_sequences() {
        let shared = Arc::new(Shared::new(1));
        let mailbox = OutboundMailbox::new();
        let (client, _) =
            shared.register_subscribed(ClientKind::Interactive, None, None, Arc::clone(&mailbox));
        let mut context = ExecutionContext::default();
        shared
            .execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new("new-session", [] as [&str; 0]),
            )
            .expect("new session");
        let session = context.session.expect("session");
        let source = context.pane.expect("source pane");
        shared.attach(client, session).expect("attach session");
        take_reliable_messages(&mailbox);

        shared
            .input(
                client,
                ClientKind::Interactive,
                &mut context,
                InputMessage::Key {
                    pane: source,
                    input: test_key(
                        KeyCode::Character('b'),
                        Modifiers::new(false, true, false, false),
                        None,
                    ),
                    text_follows: false,
                },
            )
            .expect("prefix key");
        shared
            .input(
                client,
                ClientKind::Interactive,
                &mut context,
                InputMessage::Key {
                    pane: source,
                    input: test_key(KeyCode::Character(':'), Modifiers::default(), Some(":")),
                    text_follows: true,
                },
            )
            .expect("command-prompt binding");
        shared
            .input(
                client,
                ClientKind::Interactive,
                &mut context,
                InputMessage::Text {
                    pane: source,
                    text: ":".to_owned(),
                },
            )
            .expect("suppress committed binding text");
        {
            let inner = shared.inner.lock();
            assert_eq!(
                inner.command_prompts[&client].input, "",
                "the binding character must not leak into the prompt"
            );
            assert!(
                !inner.suppressed_text.contains_key(&client),
                "consumed committed text must not leave suppression bookkeeping behind"
            );
        }
        let opened = take_reliable_messages(&mailbox);
        assert!(opened.iter().any(|message| matches!(
            message,
            ProtocolMessage::Event(Event {
                payload: EventPayload::CommandPrompt { state: Some(state) },
                ..
            }) if state.input.is_empty()
        )));
        shared.send_resync(client, &mailbox);
        let resync = take_reliable_messages(&mailbox);
        assert!(resync.iter().any(|message| matches!(
            message,
            ProtocolMessage::Event(Event {
                payload: EventPayload::Snapshot(_),
                ..
            })
        )));
        assert!(resync.iter().any(|message| matches!(
            message,
            ProtocolMessage::Event(Event {
                payload: EventPayload::CommandPrompt { state: Some(state) },
                ..
            }) if state.input.is_empty()
        )));

        let command = "new-window -n prompted; split-window -h";
        shared
            .input(
                client,
                ClientKind::Interactive,
                &mut context,
                InputMessage::Text {
                    pane: source,
                    text: command.to_owned(),
                },
            )
            .expect("prompt text");
        shared
            .input(
                client,
                ClientKind::Interactive,
                &mut context,
                InputMessage::Key {
                    pane: source,
                    input: test_key(KeyCode::Enter, Modifiers::default(), None),
                    text_follows: false,
                },
            )
            .expect("submit prompt");

        {
            let inner = shared.inner.lock();
            let session_state = &inner.engine.state.sessions[&session];
            assert_eq!(session_state.windows.len(), 2);
            let active = &inner.engine.state.windows[&session_state.active_window];
            assert_eq!(active.name, "prompted");
            assert_eq!(active.panes.len(), 2);
            assert!(!inner.command_prompts.contains_key(&client));
            assert_eq!(
                inner.command_history.last().map(String::as_str),
                Some(command)
            );
        }
        let messages = take_reliable_messages(&mailbox);
        assert!(messages.iter().any(|message| matches!(
            message,
            ProtocolMessage::Event(Event {
                payload: EventPayload::CommandPrompt { state: None },
                ..
            })
        )));

        shared
            .execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new("command-prompt", [] as [&str; 0]),
            )
            .expect("reopen prompt");
        let pane = context.pane.expect("active pane");
        shared
            .input(
                client,
                ClientKind::Interactive,
                &mut context,
                InputMessage::Key {
                    pane,
                    input: test_key(KeyCode::ArrowUp, Modifiers::default(), None),
                    text_follows: false,
                },
            )
            .expect("prompt history");
        assert_eq!(shared.inner.lock().command_prompts[&client].input, command);
    }

    #[test]
    fn command_prompt_templates_and_output_use_native_view_mode() {
        let shared = Arc::new(Shared::new(1));
        let mailbox = OutboundMailbox::new();
        let (client, _) =
            shared.register_subscribed(ClientKind::Interactive, None, None, Arc::clone(&mailbox));
        let mut context = ExecutionContext::default();
        shared
            .execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new("new-session", [] as [&str; 0]),
            )
            .expect("new session");
        let session = context.session.expect("session");
        shared.attach(client, session).expect("attach session");
        take_reliable_messages(&mailbox);

        shared
            .execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new("command-prompt", ["-I", "scratch", "new-window -n %%"]),
            )
            .expect("template prompt");
        let pane = context.pane.expect("active pane");
        shared
            .input(
                client,
                ClientKind::Interactive,
                &mut context,
                InputMessage::Key {
                    pane,
                    input: test_key(KeyCode::Enter, Modifiers::default(), None),
                    text_follows: false,
                },
            )
            .expect("submit template");
        assert_eq!(
            shared.inner.lock().engine.state.windows[&context.window.unwrap()].name,
            "scratch"
        );

        take_reliable_messages(&mailbox);
        shared
            .execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new("command-prompt", ["-I", "list-panes"]),
            )
            .expect("output prompt");
        let pane = context.pane.expect("active pane");
        shared
            .input(
                client,
                ClientKind::Interactive,
                &mut context,
                InputMessage::Key {
                    pane,
                    input: test_key(KeyCode::Enter, Modifiers::default(), None),
                    text_follows: false,
                },
            )
            .expect("submit output command");
        let message = take_command_output_message(&mailbox);
        let ProtocolMessage::Event(Event {
            payload:
                EventPayload::CommandOutput {
                    pane: output_pane,
                    viewport: Some(viewport),
                    ..
                },
            ..
        }) = message
        else {
            panic!("expected native command-output viewport");
        };
        assert_eq!(output_pane, pane);
        assert!(matches!(
            viewport.mode,
            zz_terminal::TerminalMode::View { .. }
        ));
        assert!(viewport_text(&viewport).contains("[history "));
        assert!(
            shared.inner.lock().key_engines[&client]
                .active_table()
                .is_some()
        );

        shared
            .input(
                client,
                ClientKind::Interactive,
                &mut context,
                InputMessage::ResizeCommandOutput {
                    columns: 20,
                    rows: 4,
                    cell_width_px: 8,
                    cell_height_px: 18,
                },
            )
            .expect("resize output view");
        let resized = take_command_output_message(&mailbox);
        assert!(matches!(
            resized,
            ProtocolMessage::Event(Event {
                payload: EventPayload::CommandOutput {
                    viewport: Some(TerminalViewport {
                        columns: 20,
                        rows: 4,
                        ..
                    }),
                    ..
                },
                ..
            })
        ));

        let output_id = current_command_output_id(&shared, client);
        shared
            .input(
                client,
                ClientKind::Interactive,
                &mut context,
                InputMessage::Text {
                    pane,
                    text: "q".to_owned(),
                },
            )
            .expect("close output view");
        wait_for_command_output_close(&mailbox, output_id);
        let inner = shared.inner.lock();
        assert!(!inner.command_outputs.contains_key(&client));
        assert_eq!(inner.key_engines[&client].active_table(), None);
    }

    #[test]
    fn command_output_ids_advance_and_stay_with_each_actor() {
        let shared = Arc::new(Shared::new(1));
        let mailbox = OutboundMailbox::new();
        let (client, _) =
            shared.register_subscribed(ClientKind::Interactive, None, None, Arc::clone(&mailbox));
        let (session, pane, _) = output_view_session_fixture(&shared, "output-ids", "pane");
        shared
            .attach(client, session)
            .expect("attach output client");
        take_reliable_messages(&mailbox);

        shared
            .open_command_output(client, Some(pane), "first".to_owned(), "one\ntwo")
            .expect("open first command output");
        let first_id = command_output_message_id(&take_command_output_message(&mailbox));
        assert_ne!(first_id, 0);
        let first_terminal = Arc::clone(&shared.inner.lock().command_outputs[&client].terminal);
        let first_viewport = first_terminal
            .latest_viewport_for(TerminalViewId(client.0))
            .expect("first command-output viewport");
        shared.publish_command_output(client, pane, &first_terminal, &first_viewport);
        assert_eq!(
            command_output_message_id(&take_command_output_message(&mailbox)),
            first_id
        );
        shared.send_resync(client, &mailbox);
        assert_eq!(
            command_output_message_id(&take_command_output_message(&mailbox)),
            first_id
        );
        take_reliable_messages(&mailbox);

        shared
            .open_command_output(client, Some(pane), "second".to_owned(), "three\nfour")
            .expect("replace command output");
        let (second_id, second_terminal) = {
            let inner = shared.inner.lock();
            let output = &inner.command_outputs[&client];
            (output.output_id, Arc::clone(&output.terminal))
        };
        assert!(second_id > first_id);
        wait_for_command_output_close(&mailbox, first_id);
        assert_eq!(
            command_output_message_id(&take_command_output_message(&mailbox)),
            second_id
        );
        shared.close_command_output(client, &first_terminal);
        assert_eq!(
            shared.inner.lock().command_outputs[&client].output_id,
            second_id
        );
        shared.close_command_output(client, &second_terminal);
        wait_for_command_output_close(&mailbox, second_id);
        shared.send_resync(client, &mailbox);
        assert!(take_reliable_messages(&mailbox).into_iter().any(|message| {
            matches!(
                message,
                ProtocolMessage::Event(Event {
                    payload: EventPayload::CommandOutput {
                        output_id: 0,
                        viewport: None,
                        ..
                    },
                    ..
                })
            )
        }));

        shared
            .open_command_output(client, Some(pane), "third".to_owned(), "five\nsix")
            .expect("open third command output");
        let (third_id, third_terminal) = {
            let inner = shared.inner.lock();
            let output = &inner.command_outputs[&client];
            (output.output_id, Arc::clone(&output.terminal))
        };
        assert!(third_id > second_id);
        shared.close_command_output(client, &third_terminal);
        wait_for_command_output_close(&mailbox, third_id);
        assert!(mailbox.state.lock().command_output.is_none());
    }

    #[test]
    fn command_output_retires_with_its_pane_or_attached_session() {
        let shared = Arc::new(Shared::new(1));
        let mailbox = OutboundMailbox::new();
        let (client, _) =
            shared.register_subscribed(ClientKind::Interactive, None, None, Arc::clone(&mailbox));
        let mut context = ExecutionContext::default();
        shared
            .execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new("new-session", ["-s", "first"]),
            )
            .expect("first session");
        let first_session = context.session.expect("first session id");
        let source = context.pane.expect("source pane");
        shared
            .execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new("split-window", ["-h"]),
            )
            .expect("surviving pane");
        shared.attach(client, first_session).expect("attach first");
        take_reliable_messages(&mailbox);

        shared
            .open_command_output(
                client,
                Some(source),
                "pane output".to_owned(),
                "pane-bound output",
            )
            .expect("open pane output");
        take_command_output_message(&mailbox);
        let pane_output_id = current_command_output_id(&shared, client);
        shared
            .execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new("kill-pane", ["-t", &source.to_string()]),
            )
            .expect("remove output source");
        wait_for_command_output_close(&mailbox, pane_output_id);
        assert!(!shared.inner.lock().command_outputs.contains_key(&client));

        let remaining = context.pane.expect("remaining pane");
        shared
            .open_command_output(
                client,
                Some(remaining),
                "session output".to_owned(),
                "session-bound output",
            )
            .expect("open session output");
        take_command_output_message(&mailbox);
        let session_output_id = current_command_output_id(&shared, client);
        shared
            .execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new("new-session", ["-s", "second"]),
            )
            .expect("second session");
        let second_session = context.session.expect("second session id");
        shared
            .attach(client, second_session)
            .expect("switch attached session");
        wait_for_command_output_close(&mailbox, session_output_id);
        let second_pane = context.pane.expect("second-session pane");
        shared
            .open_command_output(
                client,
                Some(second_pane),
                "window output".to_owned(),
                "window-bound output",
            )
            .expect("open window output");
        take_command_output_message(&mailbox);
        let window_output_id = current_command_output_id(&shared, client);
        shared
            .execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new("new-window", [] as [&str; 0]),
            )
            .expect("change active window");
        wait_for_command_output_close(&mailbox, window_output_id);
        let inner = shared.inner.lock();
        assert!(!inner.command_outputs.contains_key(&client));
        assert_eq!(inner.key_engines[&client].active_table(), None);
    }

    #[test]
    fn pane_input_resolves_key_tables_from_every_pane_kind() {
        let shared = Arc::new(Shared::new(1));
        let mailbox = OutboundMailbox::new();
        let (client, _) =
            shared.register_subscribed(ClientKind::Interactive, None, None, Arc::clone(&mailbox));
        let mut context = ExecutionContext::default();
        for command in [
            CommandInvocation::new("set-option", ["-g", "prefix", "C-a"]),
            CommandInvocation::new("bind-key", ["-n", "C-h", "focus-sidebar"]),
            CommandInvocation::new("bind-key", ["-r", "s", "focus-sidebar"]),
        ] {
            shared
                .execute(client, ClientKind::Interactive, &mut context, &command)
                .expect("configure key tables");
        }
        shared
            .execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new("new-session", ["-s", "routes"]),
            )
            .expect("session");
        let session = context.session.expect("session");
        let terminal = context.pane.expect("terminal");
        shared
            .execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new("split-browser", ["-h", "https://example.com"]),
            )
            .expect("browser");
        let browser = context.pane.expect("browser");
        shared
            .execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new("split-picker", ["-v"]),
            )
            .expect("agent picker");
        let agent = context.pane.expect("agent picker");
        shared
            .execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new("set-option", ["-g", "experimental-agent-pane", "on"]),
            )
            .expect("enable agent panes");
        shared
            .execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new("select-pane-kind", ["-t", &agent.to_string(), "agent"]),
            )
            .expect("agent");
        shared.attach(client, session).expect("attach");
        take_reliable_messages(&mailbox);

        let browser_key = |message: &ProtocolMessage| {
            matches!(
                message,
                ProtocolMessage::Event(Event {
                    payload: EventPayload::BrowserCommand {
                        command: BrowserCommand::Key(_),
                        ..
                    },
                    ..
                })
            )
        };
        let prefix_armed = |message: &ProtocolMessage, wanted: bool| {
            matches!(
                message,
                ProtocolMessage::Event(Event {
                    payload: EventPayload::PrefixArmed { armed },
                    ..
                }) if *armed == wanted
            )
        };
        let focus_sidebar = |message: &ProtocolMessage| {
            matches!(
                message,
                ProtocolMessage::Event(Event {
                    payload: EventPayload::FocusSidebar,
                    ..
                })
            )
        };

        shared
            .input(
                client,
                ClientKind::Interactive,
                &mut context,
                InputMessage::Key {
                    pane: browser,
                    input: test_key(
                        KeyCode::Character('a'),
                        Modifiers::new(false, true, false, false),
                        None,
                    ),
                    text_follows: false,
                },
            )
            .expect("browser prefix");
        let messages = take_reliable_messages(&mailbox);
        assert!(messages.iter().any(|message| prefix_armed(message, true)));
        assert!(!messages.iter().any(browser_key));

        let mut unrelated_surface_release = test_key(
            KeyCode::Character('a'),
            Modifiers::new(false, true, false, false),
            None,
        );
        unrelated_surface_release.action = KeyAction::Release;
        shared
            .input(
                client,
                ClientKind::Interactive,
                &mut context,
                InputMessage::BrowserSurfaceKey {
                    pane: browser,
                    input: unrelated_surface_release,
                    text_follows: false,
                },
            )
            .expect("unrelated browser surface release");
        assert!(take_reliable_messages(&mailbox).iter().any(browser_key));
        assert!(shared.inner.lock().swallowed_keys[&client].contains("a"));

        let mut prefix_release = test_key(
            KeyCode::Character('a'),
            Modifiers::new(false, true, false, false),
            None,
        );
        prefix_release.action = KeyAction::Release;
        shared
            .input(
                client,
                ClientKind::Interactive,
                &mut context,
                InputMessage::Key {
                    pane: browser,
                    input: prefix_release,
                    text_follows: false,
                },
            )
            .expect("browser prefix release");
        assert!(!take_reliable_messages(&mailbox).iter().any(browser_key));
        assert!(shared.inner.lock().swallowed_keys[&client].is_empty());
        assert_eq!(
            shared.inner.lock().key_engines[&client].active_table(),
            Some("prefix")
        );

        shared
            .input(
                client,
                ClientKind::Interactive,
                &mut context,
                InputMessage::Key {
                    pane: browser,
                    input: test_key(KeyCode::Character('s'), Modifiers::default(), Some("s")),
                    text_follows: true,
                },
            )
            .expect("browser prefix-table binding");
        let messages = take_reliable_messages(&mailbox);
        assert!(messages.iter().any(focus_sidebar));
        assert!(!messages.iter().any(browser_key));
        assert_eq!(
            shared.inner.lock().key_engines[&client].active_table(),
            Some("prefix")
        );

        shared
            .input(
                client,
                ClientKind::Interactive,
                &mut context,
                InputMessage::Key {
                    pane: browser,
                    input: test_key(KeyCode::Character('Z'), Modifiers::default(), Some("Z")),
                    text_follows: false,
                },
            )
            .expect("unbound key after the repeat window retries root");
        let messages = take_reliable_messages(&mailbox);
        assert!(messages.iter().any(browser_key));
        assert!(messages.iter().any(|message| prefix_armed(message, false)));

        shared
            .input(
                client,
                ClientKind::Interactive,
                &mut context,
                InputMessage::BrowserSurfaceKey {
                    pane: browser,
                    input: test_key(KeyCode::Character('y'), Modifiers::default(), Some("y")),
                    text_follows: false,
                },
            )
            .expect("plain browser key passes to the page");
        assert!(take_reliable_messages(&mailbox).iter().any(browser_key));

        shared
            .input(
                client,
                ClientKind::Interactive,
                &mut context,
                InputMessage::BrowserSurfaceKey {
                    pane: browser,
                    input: test_key(
                        KeyCode::Character('h'),
                        Modifiers::new(false, true, false, false),
                        None,
                    ),
                    text_follows: false,
                },
            )
            .expect("browser surface key");
        let messages = take_reliable_messages(&mailbox);
        assert!(messages.iter().any(browser_key));
        assert!(!messages.iter().any(focus_sidebar));

        let mut surface_release = test_key(
            KeyCode::Character('h'),
            Modifiers::new(false, true, false, false),
            None,
        );
        surface_release.action = KeyAction::Release;
        shared
            .input(
                client,
                ClientKind::Interactive,
                &mut context,
                InputMessage::BrowserSurfaceKey {
                    pane: browser,
                    input: surface_release,
                    text_follows: false,
                },
            )
            .expect("browser surface key release");
        let messages = take_reliable_messages(&mailbox);
        assert!(messages.iter().any(browser_key));
        assert!(!messages.iter().any(focus_sidebar));

        for (input, text_follows) in [
            (
                test_key(
                    KeyCode::Character('a'),
                    Modifiers::new(false, true, false, false),
                    None,
                ),
                false,
            ),
            (
                test_key(KeyCode::Character('s'), Modifiers::default(), Some("s")),
                true,
            ),
            (
                test_key(KeyCode::Character('Z'), Modifiers::default(), Some("Z")),
                false,
            ),
        ] {
            shared
                .input(
                    client,
                    ClientKind::Interactive,
                    &mut context,
                    InputMessage::Key {
                        pane: agent,
                        input,
                        text_follows,
                    },
                )
                .expect("agent-source key");
        }
        let messages = take_reliable_messages(&mailbox);
        assert!(messages.iter().any(focus_sidebar));
        assert!(!messages.iter().any(browser_key));
        assert_eq!(
            shared.inner.lock().key_engines[&client].active_table(),
            None
        );

        shared
            .execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new("bind-key", ["h", "select-pane", "-L"]),
            )
            .expect("bind h to select-pane -L");
        shared
            .execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new("split-picker", ["-h", "-t", &terminal.to_string()]),
            )
            .expect("editor picker beside the terminal");
        let editor = context.pane.expect("editor picker");
        shared
            .execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new("set-option", ["-g", "experimental-editor-pane", "on"]),
            )
            .expect("enable editor panes");
        shared
            .execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new("select-pane-kind", ["-t", &editor.to_string(), "editor"]),
            )
            .expect("editor");
        shared
            .execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new("select-pane", ["-t", &editor.to_string()]),
            )
            .expect("focus the editor");
        let window = context.window.expect("window");
        assert_eq!(
            shared.inner.lock().engine.state.windows[&window].active_pane,
            editor
        );
        take_reliable_messages(&mailbox);

        shared
            .input(
                client,
                ClientKind::Interactive,
                &mut context,
                InputMessage::Key {
                    pane: editor,
                    input: test_key(
                        KeyCode::Character('a'),
                        Modifiers::new(false, true, false, false),
                        None,
                    ),
                    text_follows: false,
                },
            )
            .expect("editor prefix");
        let messages = take_reliable_messages(&mailbox);
        assert!(messages.iter().any(|message| prefix_armed(message, true)));
        assert_eq!(
            shared.inner.lock().key_engines[&client].active_table(),
            Some("prefix")
        );

        shared
            .input(
                client,
                ClientKind::Interactive,
                &mut context,
                InputMessage::Key {
                    pane: editor,
                    input: test_key(KeyCode::Character('h'), Modifiers::default(), Some("h")),
                    text_follows: true,
                },
            )
            .expect("editor prefix-table select-pane -L");
        let messages = take_reliable_messages(&mailbox);
        assert!(messages.iter().any(|message| prefix_armed(message, false)));
        assert_eq!(
            shared.inner.lock().engine.state.windows[&window].active_pane,
            terminal,
            "prefix+h from the editor must focus the terminal to its left"
        );
        assert_eq!(
            shared.inner.lock().key_engines[&client].active_table(),
            None
        );

        let prefix = test_key(
            KeyCode::Character('a'),
            Modifiers::new(false, true, false, false),
            None,
        );
        let binding = test_key(KeyCode::Character('s'), Modifiers::default(), Some("s"));

        shared
            .input(
                client,
                ClientKind::Interactive,
                &mut context,
                InputMessage::Key {
                    pane: terminal,
                    input: prefix,
                    text_follows: false,
                },
            )
            .expect("normal prefix");
        assert_eq!(
            shared.inner.lock().key_engines[&client].active_table(),
            Some("prefix")
        );

        shared
            .input(
                client,
                ClientKind::Interactive,
                &mut context,
                InputMessage::Key {
                    pane: terminal,
                    input: binding,
                    text_follows: true,
                },
            )
            .expect("prefix-table binding");
        assert!(
            take_reliable_messages(&mailbox)
                .iter()
                .any(|message| matches!(
                    message,
                    ProtocolMessage::Event(Event {
                        payload: EventPayload::FocusSidebar,
                        ..
                    })
                ))
        );
        assert_eq!(
            shared.inner.lock().key_engines[&client].active_table(),
            Some("prefix")
        );

        shared
            .input(
                client,
                ClientKind::Interactive,
                &mut context,
                InputMessage::Key {
                    pane: terminal,
                    input: test_key(KeyCode::Character('Z'), Modifiers::default(), Some("Z")),
                    text_follows: false,
                },
            )
            .expect("unbound prefix-table key is discarded");
        assert_eq!(
            shared.inner.lock().key_engines[&client].active_table(),
            None
        );

        shared
            .input(
                client,
                ClientKind::Interactive,
                &mut context,
                InputMessage::Key {
                    pane: terminal,
                    input: test_key(
                        KeyCode::Character('h'),
                        Modifiers::new(false, true, false, false),
                        None,
                    ),
                    text_follows: false,
                },
            )
            .expect("root binding");
        assert!(
            take_reliable_messages(&mailbox)
                .iter()
                .any(|message| matches!(
                    message,
                    ProtocolMessage::Event(Event {
                        payload: EventPayload::FocusSidebar,
                        ..
                    })
                ))
        );

        let error = shared
            .input(
                client,
                ClientKind::Interactive,
                &mut context,
                InputMessage::BrowserSurfaceKey {
                    pane: terminal,
                    input: test_key(KeyCode::Character('x'), Modifiers::default(), Some("x")),
                    text_follows: true,
                },
            )
            .expect_err("terminal panes cannot claim the browser surface route");
        assert!(matches!(
            error,
            DaemonError::Server(ServerError::InvalidTarget(message))
                if message == format!("{terminal} is not a browser pane")
        ));
    }

    #[test]
    fn synchronized_input_fans_out_to_terminal_and_browser_panes() {
        let shared = Arc::new(Shared::new(1));
        let mailbox = OutboundMailbox::new();
        let (client, _) =
            shared.register_subscribed(ClientKind::Interactive, None, None, Arc::clone(&mailbox));
        let mut context = ExecutionContext::default();
        shared
            .execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new(
                    "new-session",
                    ["-s", "sync-input", terminal_line_echo_command()],
                ),
            )
            .expect("new session");
        let session = context.session.expect("session");
        let first = context.pane.expect("first terminal");
        shared
            .execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new("split-window", ["-h", terminal_line_echo_command()]),
            )
            .expect("second terminal");
        let second = context.pane.expect("second terminal");
        shared
            .execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new("split-browser", ["-h", "https://example.com"]),
            )
            .expect("browser pane");
        let browser = context.pane.expect("browser pane");
        shared.attach(client, session).expect("attach session");
        let (first_terminal, second_terminal) = {
            let inner = shared.inner.lock();
            (
                Arc::clone(&inner.terminals[&first]),
                Arc::clone(&inner.terminals[&second]),
            )
        };
        for terminal in [&first_terminal, &second_terminal] {
            wait_for_viewport(
                terminal,
                TerminalViewId(client.0),
                "synchronized-input terminal never became ready",
                |viewport| viewport_text(viewport).contains("zz-terminal-ready"),
            );
        }
        shared
            .execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new("set-option", ["-w", "synchronize-panes", "on"]),
            )
            .expect("enable synchronized input");
        shared
            .execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new("bind-key", ["-n", "Any", "focus-sidebar"]),
            )
            .expect("install a root catch-all that browser surface input must bypass");
        take_reliable_messages(&mailbox);

        let marker = "ZZ_SYNC_SEND_KEYS";
        let send_keys = vec![
            zz_protocol::KeyToken::Literal(format!("echo {marker}")),
            zz_protocol::KeyToken::Named("Enter".to_owned()),
        ];
        shared
            .execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new(
                    "send-keys",
                    ["-t", &first.to_string(), &format!("echo {marker}"), "Enter"],
                ),
            )
            .expect("synchronized send-keys");
        let browser_messages = take_reliable_messages(&mailbox);
        assert!(browser_messages.iter().any(|message| matches!(
            message,
            ProtocolMessage::Event(Event {
                payload: EventPayload::BrowserCommand {
                    pane,
                    command: BrowserCommand::SendKeys(keys),
                },
                ..
            }) if *pane == browser && keys == &send_keys
        )));

        for pane in [first, second] {
            let deadline = Instant::now() + Duration::from_secs(30);
            loop {
                let captured = shared
                    .execute(
                        client,
                        ClientKind::Command,
                        &mut context,
                        &CommandInvocation::new("capture-pane", ["-p", "-t", &pane.to_string()]),
                    )
                    .expect("capture synchronized terminal")
                    .output;
                if captured.contains(marker) {
                    break;
                }
                assert!(
                    Instant::now() < deadline,
                    "{pane} did not receive synchronized send-keys"
                );
                thread::sleep(Duration::from_millis(10));
            }
        }

        take_reliable_messages(&mailbox);
        let key = KeyInput {
            action: KeyAction::Press,
            key: KeyCode::Enter,
            modifiers: Modifiers::default(),
            text: None,
            unshifted_codepoint: None,
        };
        shared
            .input(
                client,
                ClientKind::Interactive,
                &mut context,
                InputMessage::BrowserSurfaceText {
                    pane: browser,
                    text: "xλz".to_owned(),
                },
            )
            .expect("synchronized text");
        shared
            .input(
                client,
                ClientKind::Interactive,
                &mut context,
                InputMessage::BrowserSurfaceKey {
                    pane: browser,
                    input: key.clone(),
                    text_follows: false,
                },
            )
            .expect("synchronized key");
        shared
            .input(
                client,
                ClientKind::Interactive,
                &mut context,
                InputMessage::TerminalView {
                    pane: first,
                    action: zz_terminal::TerminalViewAction::Paste("pasted".to_owned()),
                },
            )
            .expect("synchronized paste");

        let messages = take_reliable_messages(&mailbox);
        assert!(!messages.iter().any(|message| matches!(
            message,
            ProtocolMessage::Event(Event {
                payload: EventPayload::FocusSidebar,
                ..
            })
        )));
        let commands = messages
            .into_iter()
            .filter_map(|message| match message {
                ProtocolMessage::Event(Event {
                    payload: EventPayload::BrowserCommand { pane, command },
                    ..
                }) if pane == browser => Some(command),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert_eq!(
            commands,
            vec![
                BrowserCommand::SendKeys(vec![zz_protocol::KeyToken::Literal("xλz".to_owned())]),
                BrowserCommand::Key(key),
                BrowserCommand::SendKeys(vec![zz_protocol::KeyToken::Literal("pasted".to_owned())]),
            ]
        );

        take_reliable_messages(&mailbox);
        shared
            .execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new("set-buffer", ["buffer paste"]),
            )
            .expect("set paste buffer");
        shared
            .execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new("paste-buffer", ["-t", &first.to_string()]),
            )
            .expect("synchronized paste-buffer");
        assert!(
            take_reliable_messages(&mailbox)
                .iter()
                .any(|message| matches!(
                    message,
                    ProtocolMessage::Event(Event {
                        payload: EventPayload::BrowserCommand {
                            pane,
                            command: BrowserCommand::SendKeys(keys),
                        },
                        ..
                    }) if *pane == browser
                        && keys == &[zz_protocol::KeyToken::Literal("buffer paste".to_owned())]
                ))
        );
    }

    #[test]
    fn pane_input_off_gates_direct_synchronized_send_and_paste_input() {
        let shared = Arc::new(Shared::new(1));
        let mailbox = OutboundMailbox::new();
        let (client, _) =
            shared.register_subscribed(ClientKind::Interactive, None, None, Arc::clone(&mailbox));
        let mut context = ExecutionContext::default();
        shared
            .execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new("new-session", ["-s", "input-off"]),
            )
            .expect("new session");
        let session = context.session.expect("session");
        let terminal = context.pane.expect("terminal");
        shared
            .execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new("split-browser", ["-h", "https://example.com"]),
            )
            .expect("browser pane");
        let browser = context.pane.expect("browser");
        shared.attach(client, session).expect("attach session");
        shared
            .execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new("set-option", ["-w", "synchronize-panes", "on"]),
            )
            .expect("enable synchronized input");
        shared
            .execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new("select-pane", ["-t", &terminal.to_string()]),
            )
            .expect("select terminal");
        shared
            .execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new("last-pane", ["-d"]),
            )
            .expect("disable browser input");

        {
            let inner = shared.inner.lock();
            assert!(resolve_input_sinks(&inner, browser).unwrap().is_empty());
            let sinks = resolve_input_sinks(&inner, terminal).unwrap();
            assert_eq!(sinks.len(), 1);
            assert!(matches!(sinks[0], PaneSink::Terminal(_)));
        }

        take_reliable_messages(&mailbox);
        shared
            .execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new("send-keys", ["-t", &browser.to_string(), "blocked"]),
            )
            .expect("send keys to disabled browser");
        assert!(
            !take_reliable_messages(&mailbox)
                .iter()
                .any(|message| matches!(
                    message,
                    ProtocolMessage::Event(Event {
                        payload: EventPayload::BrowserCommand { .. },
                        ..
                    })
                ))
        );

        shared
            .execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new("set-buffer", ["blocked paste"]),
            )
            .expect("set buffer");
        take_reliable_messages(&mailbox);
        shared
            .execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new("paste-buffer", ["-t", &browser.to_string()]),
            )
            .expect("paste to disabled browser");
        assert!(
            !take_reliable_messages(&mailbox)
                .iter()
                .any(|message| matches!(
                    message,
                    ProtocolMessage::Event(Event {
                        payload: EventPayload::BrowserCommand { .. },
                        ..
                    })
                ))
        );

        shared
            .input(
                client,
                ClientKind::Interactive,
                &mut context,
                InputMessage::BrowserSurfaceText {
                    pane: browser,
                    text: "blocked direct input".to_owned(),
                },
            )
            .expect("direct input to disabled browser");
        assert!(
            !take_reliable_messages(&mailbox)
                .iter()
                .any(|message| matches!(
                    message,
                    ProtocolMessage::Event(Event {
                        payload: EventPayload::BrowserCommand { .. },
                        ..
                    })
                ))
        );
    }

    const QUIET_PANE_COMMAND: &str = "while read -r line; do eval \"$line\"; done";

    fn belled_session(
        shared: &Arc<Shared>,
        mailbox: &Arc<OutboundMailbox>,
    ) -> (ClientId, ExecutionContext, PaneId, PaneId) {
        let (client, _) =
            shared.register_subscribed(ClientKind::Interactive, None, None, Arc::clone(mailbox));
        let mut context = ExecutionContext::default();
        shared
            .execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new("new-session", [QUIET_PANE_COMMAND]),
            )
            .expect("new session");
        let session = context.session.expect("session");
        let first = context.pane.expect("first terminal");
        shared
            .execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new("new-window", [QUIET_PANE_COMMAND]),
            )
            .expect("second terminal");
        let second = context.pane.expect("second terminal");
        shared.attach(client, session).expect("attach session");
        shared
            .execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new("select-window", ["-t", ":0"]),
            )
            .expect("select the first window");
        take_reliable_messages(mailbox);
        (client, context, first, second)
    }

    fn pane_bell(messages: &[ProtocolMessage], pane: PaneId) -> bool {
        latest_reliable_snapshot(messages).sessions[0]
            .windows
            .iter()
            .find_map(|window| window.panes.get(&pane))
            .expect("snapshot pane")
            .bell
    }

    fn bell_events(messages: &[ProtocolMessage]) -> Vec<PaneId> {
        messages
            .iter()
            .filter_map(|message| match message {
                ProtocolMessage::Event(Event {
                    payload: EventPayload::Bell { pane },
                    ..
                }) => Some(*pane),
                _ => None,
            })
            .collect()
    }

    fn bell_messages(messages: &[ProtocolMessage]) -> Vec<(Option<PaneId>, String, u32)> {
        messages
            .iter()
            .filter_map(|message| match message {
                ProtocolMessage::Event(Event {
                    payload:
                        EventPayload::TimedClientMessage {
                            pane,
                            kind: ClientMessageKind::Info,
                            text,
                            duration_ms,
                            ..
                        },
                    ..
                }) => Some((*pane, text.clone(), *duration_ms)),
                _ => None,
            })
            .collect()
    }

    fn timed_message_events(
        messages: &[ProtocolMessage],
    ) -> Vec<(Option<PaneId>, String, u32, u64)> {
        messages
            .iter()
            .filter_map(|message| match message {
                ProtocolMessage::Event(Event {
                    payload:
                        EventPayload::TimedClientMessage {
                            pane,
                            kind: ClientMessageKind::Info,
                            text,
                            duration_ms,
                            message_id,
                        },
                    ..
                }) => Some((*pane, text.clone(), *duration_ms, *message_id)),
                _ => None,
            })
            .collect()
    }

    fn message_lifecycle_events(messages: &[ProtocolMessage]) -> Vec<(bool, u64)> {
        messages
            .iter()
            .filter_map(|message| match message {
                ProtocolMessage::Event(Event {
                    payload: EventPayload::TimedClientMessage { message_id, .. },
                    ..
                }) => Some((true, *message_id)),
                ProtocolMessage::Event(Event {
                    payload: EventPayload::TimedClientMessageCleared { message_id },
                    ..
                }) => Some((false, *message_id)),
                _ => None,
            })
            .collect()
    }

    #[cfg(unix)]
    fn ring_terminal_and_wait_for_bell(
        shared: &Arc<Shared>,
        mailbox: &OutboundMailbox,
        pane: PaneId,
        terminal: &Arc<TerminalSession>,
        expect_flag: bool,
    ) {
        terminal.send_text("printf '\\007'\n");
        let deadline = Instant::now() + Duration::from_secs(30);
        let mut saw_edge = false;
        loop {
            saw_edge |= bell_events(&take_reliable_messages(mailbox)).contains(&pane);
            let state_belled = shared
                .inner
                .lock()
                .engine
                .state
                .pane(pane)
                .is_some_and(|pane| pane.bell);
            if saw_edge && state_belled == expect_flag {
                return;
            }
            assert!(Instant::now() < deadline, "bell did not publish");
            thread::sleep(Duration::from_millis(10));
        }
    }

    #[test]
    fn a_bell_publishes_one_edge_and_a_flag_that_input_clears() {
        let shared = Arc::new(Shared::new(1));
        let mailbox = OutboundMailbox::new();
        let (client, mut context, first, second) = belled_session(&shared, &mailbox);
        let background_mailbox = OutboundMailbox::new();
        shared.register_subscribed(
            ClientKind::Interactive,
            None,
            None,
            Arc::clone(&background_mailbox),
        );
        take_reliable_messages(&background_mailbox);

        shared.raise_pane_bell(second);
        let messages = take_reliable_messages(&mailbox);
        let background_messages = take_reliable_messages(&background_mailbox);
        assert_eq!(bell_events(&messages), vec![second]);
        assert!(bell_events(&background_messages).is_empty());
        assert!(pane_bell(&messages, second));
        assert!(pane_bell(&background_messages, second));
        assert!(!pane_bell(&messages, first));

        shared.raise_pane_bell(second);
        assert_eq!(bell_events(&take_reliable_messages(&mailbox)), vec![second]);

        shared
            .input(
                client,
                ClientKind::Interactive,
                &mut context,
                InputMessage::Text {
                    pane: first,
                    text: "true\n".to_owned(),
                },
            )
            .expect("type into the quiet pane");
        assert!(
            shared
                .inner
                .lock()
                .engine
                .state
                .pane(second)
                .expect("second pane")
                .bell
        );

        shared
            .input(
                client,
                ClientKind::Interactive,
                &mut context,
                InputMessage::Text {
                    pane: second,
                    text: "true\n".to_owned(),
                },
            )
            .expect("type into the belled pane");
        assert!(!pane_bell(&take_reliable_messages(&mailbox), second));

        shared.raise_pane_bell(second);
        assert_eq!(bell_events(&take_reliable_messages(&mailbox)), vec![second]);
    }

    #[test]
    fn bell_action_and_visual_bell_fan_out_from_the_session_active_window() {
        let shared = Arc::new(Shared::new(1));
        let first_mailbox = OutboundMailbox::new();
        let (first_client, mut context, _first, second) = belled_session(&shared, &first_mailbox);
        let session = context.session.expect("session");
        let (second_window, second_index) = {
            let inner = shared.inner.lock();
            let window = inner
                .engine
                .state
                .window_for_pane(second)
                .expect("second window");
            (window, inner.engine.state.windows[&window].index)
        };
        let second_mailbox = OutboundMailbox::new();
        let control_mailbox = OutboundMailbox::new();
        let (second_client, _) = shared.register_subscribed(
            ClientKind::Interactive,
            None,
            None,
            Arc::clone(&second_mailbox),
        );
        let (control_client, _) = shared.register_subscribed(
            ClientKind::Control,
            None,
            None,
            Arc::clone(&control_mailbox),
        );
        shared
            .attach(second_client, session)
            .expect("attach second client");
        shared
            .attach(control_client, session)
            .expect("attach control client");
        {
            let mut inner = shared.inner.lock();
            inner.focused_windows.insert(second_client, second_window);
            inner.focused_windows.insert(control_client, second_window);
        }
        take_reliable_messages(&first_mailbox);
        take_reliable_messages(&second_mailbox);
        take_reliable_messages(&control_mailbox);

        for (name, value) in [("bell-action", "other"), ("visual-bell", "both")] {
            shared
                .execute(
                    ClientId(u64::MAX),
                    ClientKind::Command,
                    &mut context,
                    &CommandInvocation::new("set-option", ["-g", name, value]),
                )
                .expect("configure bell option");
        }
        take_reliable_messages(&first_mailbox);
        take_reliable_messages(&second_mailbox);
        take_reliable_messages(&control_mailbox);
        shared.raise_pane_bell(second);
        let first = take_reliable_messages(&first_mailbox);
        assert_eq!(bell_events(&first), vec![second]);
        assert_eq!(
            bell_messages(&first),
            vec![(Some(second), format!("Bell in window {second_index}"), 750,)]
        );
        let second_messages = take_reliable_messages(&second_mailbox);
        assert_eq!(bell_events(&second_messages), vec![second]);
        assert_eq!(
            bell_messages(&second_messages),
            vec![(Some(second), format!("Bell in window {second_index}"), 750,)]
        );
        let control_messages = take_reliable_messages(&control_mailbox);
        assert!(bell_events(&control_messages).is_empty());
        assert!(bell_messages(&control_messages).is_empty());

        for (name, value) in [("bell-action", "current"), ("visual-bell", "on")] {
            shared
                .execute(
                    ClientId(u64::MAX),
                    ClientKind::Command,
                    &mut context,
                    &CommandInvocation::new("set-option", ["-g", name, value]),
                )
                .expect("reconfigure bell option");
        }
        take_reliable_messages(&first_mailbox);
        take_reliable_messages(&second_mailbox);
        take_reliable_messages(&control_mailbox);
        shared.raise_pane_bell(second);
        let first_messages = take_reliable_messages(&first_mailbox);
        assert!(bell_events(&first_messages).is_empty());
        assert!(bell_messages(&first_messages).is_empty());
        let second_messages = take_reliable_messages(&second_mailbox);
        assert!(bell_events(&second_messages).is_empty());
        assert!(bell_messages(&second_messages).is_empty());
        let control_messages = take_reliable_messages(&control_mailbox);
        assert!(bell_events(&control_messages).is_empty());
        assert!(bell_messages(&control_messages).is_empty());

        let first_pane = context.pane.expect("active pane");
        shared.raise_pane_bell(first_pane);
        for messages in [
            take_reliable_messages(&first_mailbox),
            take_reliable_messages(&second_mailbox),
        ] {
            assert!(bell_events(&messages).is_empty());
            assert_eq!(
                bell_messages(&messages),
                vec![(Some(first_pane), "Bell in current window".to_owned(), 750)]
            );
        }
        let control_messages = take_reliable_messages(&control_mailbox);
        assert!(bell_events(&control_messages).is_empty());
        assert!(bell_messages(&control_messages).is_empty());
        assert_eq!(
            client_focused_window_for_attachment(&shared.inner.lock(), first_client),
            context.window
        );
    }

    #[test]
    fn alert_messages_fan_out_with_owned_lifecycle_and_bounded_log() {
        let shared = Arc::new(Shared::new(1));
        let first_mailbox = OutboundMailbox::new();
        let (first_client, mut context, first, second) = belled_session(&shared, &first_mailbox);
        let session = context.session.expect("session");
        let second_mailbox = OutboundMailbox::new();
        let control_mailbox = OutboundMailbox::new();
        let (second_client, _) = shared.register_subscribed(
            ClientKind::Interactive,
            Some("second-alert".to_owned()),
            None,
            Arc::clone(&second_mailbox),
        );
        let (control, _) = shared.register_subscribed(
            ClientKind::Control,
            Some("control-alert".to_owned()),
            None,
            Arc::clone(&control_mailbox),
        );
        shared
            .attach(second_client, session)
            .expect("attach second client");
        shared
            .attach(control, session)
            .expect("attach control client");

        for arguments in [
            ["-g", "display-time", "5000"],
            ["-g", "bell-action", "any"],
            ["-g", "visual-bell", "on"],
            ["-s", "message-limit", "2"],
        ] {
            shared
                .execute(
                    ClientId(u64::MAX),
                    ClientKind::Command,
                    &mut context,
                    &CommandInvocation::new("set-option", arguments),
                )
                .expect("configure alert lifecycle");
        }
        for (client, text) in [(first_client, "first"), (second_client, "second")] {
            shared
                .execute(
                    client,
                    ClientKind::Interactive,
                    &mut context,
                    &CommandInvocation::new("display-message", ["-N", "-d", "5000", text]),
                )
                .expect("seed sticky message");
        }
        let first_old = armed_client_message(&shared, first_client);
        let second_old = armed_client_message(&shared, second_client);
        {
            let mut inner = shared.inner.lock();
            assert!(inner.message_ignore_keys.contains(&first_client));
            assert!(inner.message_ignore_keys.contains(&second_client));
            inner.message_log.clear();
            push_server_message(&mut inner, "evicted".to_owned());
        }
        let message_number = shared.inner.lock().next_message_number;
        take_reliable_messages(&first_mailbox);
        take_reliable_messages(&second_mailbox);
        take_reliable_messages(&control_mailbox);
        drain_terminal_lane(&first_mailbox);
        drain_terminal_lane(&second_mailbox);

        shared.raise_pane_bell(second);

        let first_messages = take_reliable_messages(&first_mailbox);
        let second_messages = take_reliable_messages(&second_mailbox);
        let control_messages = take_reliable_messages(&control_mailbox);
        let first_timed = timed_message_events(&first_messages);
        let second_timed = timed_message_events(&second_messages);
        assert_eq!(first_timed.len(), 1);
        assert_eq!(second_timed.len(), 1);
        let first_record = armed_client_message(&shared, first_client);
        let second_record = armed_client_message(&shared, second_client);
        assert_eq!(first_timed[0].3, first_record.token);
        assert_eq!(second_timed[0].3, second_record.token);
        assert_ne!(first_record.token, second_record.token);
        assert!(first_record.freeze && first_record.deadline.is_some());
        assert!(second_record.freeze && second_record.deadline.is_some());
        assert_eq!(
            message_lifecycle_events(&first_messages),
            vec![(true, first_record.token), (false, first_old.token)]
        );
        assert_eq!(
            message_lifecycle_events(&second_messages),
            vec![(true, second_record.token), (false, second_old.token)]
        );
        assert!(timed_message_events(&control_messages).is_empty());
        assert!(cleared_message_ids(&control_messages).is_empty());
        {
            let inner = shared.inner.lock();
            assert!(!inner.client_messages.contains_key(&control));
            assert!(!inner.message_ignore_keys.contains(&first_client));
            assert!(!inner.message_ignore_keys.contains(&second_client));
            assert_eq!(inner.next_message_number, message_number + 2);
            assert_eq!(
                inner
                    .message_log
                    .iter()
                    .map(|message| message.text.as_str())
                    .collect::<Vec<_>>(),
                [
                    format!("device-{} message: Bell in window 1", first_client.0),
                    "second-alert message: Bell in window 1".to_owned(),
                ]
            );
        }
        assert!(first_mailbox.state.lock().terminals.is_empty());
        assert!(second_mailbox.state.lock().terminals.is_empty());

        let stale = ClientMessageDeadline {
            client: first_client,
            token: first_old.token,
            deadline: first_old.deadline.expect("old deadline"),
        };
        shared.expire_client_message(stale, stale.deadline);
        assert_eq!(armed_client_message(&shared, first_client), first_record);
        assert!(cleared_message_ids(&take_reliable_messages(&first_mailbox)).is_empty());
        assert!(first_mailbox.state.lock().terminals.is_empty());

        let live = ClientMessageDeadline {
            client: first_client,
            token: first_record.token,
            deadline: first_record.deadline.expect("live deadline"),
        };
        shared.expire_client_message(live, live.deadline);
        assert_eq!(
            cleared_message_ids(&take_reliable_messages(&first_mailbox)),
            vec![first_record.token]
        );
        assert_eq!(
            first_mailbox
                .state
                .lock()
                .terminals
                .keys()
                .copied()
                .collect::<Vec<_>>(),
            [first]
        );
    }

    #[test]
    fn zero_duration_alert_replacement_waits_for_input_past_the_old_deadline() {
        let shared = Arc::new(Shared::new(1));
        let mailbox = OutboundMailbox::new();
        let (client, _) =
            shared.register_subscribed(ClientKind::Interactive, None, None, Arc::clone(&mailbox));
        let (_, pane, _) = attached_message_fixture(&shared, "zero-alert", &[client]);
        let mut context = ExecutionContext::for_pane(&shared.inner.lock().engine.state, pane)
            .expect("pane context");
        for arguments in [
            ["-g", "display-time", "0"],
            ["-g", "bell-action", "any"],
            ["-g", "visual-bell", "on"],
        ] {
            shared
                .execute(
                    ClientId(u64::MAX),
                    ClientKind::Command,
                    &mut context,
                    &CommandInvocation::new("set-option", arguments),
                )
                .expect("configure zero-duration alert");
        }
        shared
            .execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new("display-message", ["-d", "5000", "old"]),
            )
            .expect("seed positive message");
        let old = armed_client_message(&shared, client);
        take_reliable_messages(&mailbox);

        shared.raise_pane_bell(pane);
        let messages = take_reliable_messages(&mailbox);
        let current = armed_client_message(&shared, client);
        assert_eq!(current.deadline, None);
        assert!(current.freeze);
        assert_eq!(
            message_lifecycle_events(&messages),
            vec![(true, current.token), (false, old.token)]
        );

        let stale = ClientMessageDeadline {
            client,
            token: old.token,
            deadline: old.deadline.expect("old deadline"),
        };
        shared.expire_client_message(stale, stale.deadline);
        assert_eq!(armed_client_message(&shared, client), current);
        assert!(cleared_message_ids(&take_reliable_messages(&mailbox)).is_empty());

        shared
            .input(
                client,
                ClientKind::Interactive,
                &mut context,
                InputMessage::Key {
                    pane,
                    input: chooser_key_press("q"),
                    text_follows: false,
                },
            )
            .expect("dismiss zero-duration alert");
        assert!(!shared.inner.lock().client_messages.contains_key(&client));
        assert_eq!(
            cleared_message_ids(&take_reliable_messages(&mailbox)),
            vec![current.token]
        );
    }

